  ('ca-business-visitors', 'same_passport_used_for_eta', 'if you need an eTA, the same passport you used in your application'),
  ('ca-business-visitors', 'us_green_card_and_passport', 'if you’re a lawful permanent resident of the United States (US), a valid green card (or equivalent official proof of status in the U S) and a valid passport from your country of nationality (or an equivalent document)'),
  ('ca-business-visitors', 'letters_of_support_and_invitation', 'letters of support from your parent company, and a letter of invitation from the Canadian host business or a letter of recognition from the Canada Border Services Agency'),
