  ('ca-electronic-travel-authorization-eta', 'sufficient_funds', 'have enough money for your stay. (The amount of money you will need can vary. It depends on things such as how long you will stay, and whether you will stay in a hotel, or with friends or relatives.)'),
  ('ca-electronic-travel-authorization-eta', 'eta_does_not_guarantee_entry', 'An eTA doesn’t guarantee entry to Canada. When you arrive, a border services officer will ask to see your passport and other documents. You must convince the officer that you’re eligible for entry to Canada.'),
  ('ca-electronic-travel-authorization-eta', 'dual_canadian_citizen_canadian_passport', 'If you’re a dual Canadian citizen, you must travel with a valid Canadian passport. American-Canadians can travel with a valid Canadian or U.S. passport.'),
  ('ca-electronic-travel-authorization-eta', 'passport_from_visa_exempt_country', 'You will need a valid passport from a visa-exempt country or territory'),
  ('ca-electronic-travel-authorization-eta', 'valid_email_address', 'a valid email address, and'),
  ('ca-electronic-travel-authorization-eta', 'accepted_payment_method', 'one of the following acceptable methods of payment to pay the $7 CAD fee (non-refundable): Visa ®, Mastercard ®, American Express ®, a pre-paid Visa ®, Mastercard ® or American Express ®, Visa Debit, or Debit Mastercard, UnionPay ®, or JCB Card ®.'),
  ('ca-electronic-travel-authorization-eta', 'complete_online_form', 'Use the online form to apply. The form cannot be saved. So have your information ready.'),
  ('ca-electronic-travel-authorization-eta', 'pay_immediately_after_form', 'Pay $7 CAD for your eTA right after you complete the form.'),
  ('ca-electronic-travel-authorization-eta', 'submit_documents_if_requested', 'You may need to submit documents before your application can be approved. If this happens to you, an email will be sent with instructions within 72 hours.'),
  ('ca-electronic-travel-authorization-eta', 'eta_fee', 'Electronic Travel Authorization (eTA) Fees $CAN Electronic Travel Authorization 7.00'),
  ('ca-express-entry', 'three_express_entry_programs', 'Express Entry is an online system that we use to manage immigration applications for 3 programs: Canadian Experience Class For skilled workers with eligible Canadian work experience Federal Skilled Worker Program For skilled workers with eligible foreign or Canadian work experience Federal Skilled Trades Program For skilled workers who are qualified in a skilled trade'),
  ('ca-express-entry', 'language_ability', 'Language skills Canadian Experience Class CLB 7 for TEER 0 or TEER 1 occupations CLB 5 for TEER 2 or TEER 3 occupations Federal Skilled Worker Program CLB 7 Federal Skilled Trades Program CLB 5 for speaking and listening CLB 4 for reading and writing'),
  ('ca-express-entry', 'type_of_work_experience', 'Type of work experience Canadian Experience Class Canadian work experience in an occupation listed in 1 or more of these NOC TEER Categories: TEER 0 TEER 1 TEER 2 TEER 3 Federal Skilled Worker Program Work experience in an occupation listed in 1 of these NOC TEER Categories: TEER 0 TEER 1 TEER 2 TEER 3 Federal Skilled Trades Program Work experience in a skilled trade under key groups of TEER 2 or TEER 3:'),
  ('ca-express-entry', 'amount_of_work_experience', 'Amount of work experience Canadian Experience Class 1 year in Canada in the last 3 years (either combination of full-time or part-time work) Federal Skilled Worker Program 1 year continuous within the last 10 years (combination of part-time, full-time or more than 1 job in your primary occupation) Federal Skilled Trades Program 2 years within the last 5 years (either combination of full-time or part-time work)'),
  ('ca-express-entry', 'job_offer', 'Job offer Canadian Experience Class Not required. Federal Skilled Worker Program Not required, but you can get selection criteria points for having a valid job offer. Federal Skilled Trades Program Required: a valid job offer of full-time employment for a total period of at least 1 year, or a certificate of qualification in the above skilled trade issued by a Canadian provincial, territorial or federal authority'),
  ('ca-express-entry', 'education', 'Education Canadian Experience Class Not required. Federal Skilled Worker Program Secondary education required. You can get more selection criteria points for your post-secondary education. Federal Skilled Trades Program Not required.'),
  ('ca-express-entry', 'documents_to_get_ready', 'Get your documents ready Language test, education, job offer, funds, police certificates'),
  ('ca-express-entry', 'eligibility_questionnaire', 'Answer a questionnaire to check if you’re eligible for the minimum requirements of Express Entry. To answer the questionnaire, you have 2 options: Option 1: Come to Canada tool Answer a few questions using the Come to Canada tool to assess your eligibility. The tool gives you a number at the end (a personal reference code).'),
  ('ca-express-entry', 'create_profile_and_enter_pool', 'How the Express Entry process works: Create a profile and enter the pool. We''ll invite the candidates with the most points in rounds. If you''re invited to apply, fill out the application. We''ll review your application and make a decision.'),
  ('ca-express-entry', 'crs_score', 'Check your score Calculate your Comprehensive Ranking System (CRS) score'),
  ('ca-express-entry', 'apply_for_permanent_residence', 'Apply for permanent residence Submit the online form, upload documents, pay your fees'),
  ('ca-express-entry', 'biometrics', 'After you apply Biometrics, processing, application status'),
  ('ca-express-entry', 'economic_immigration_application_fee', 'Economic immigration (including Express Entry) These fees apply to: Atlantic immigration program Canadian experience class Federal skilled workers Federal skilled trades Provincial nominee Rural or francophone community immigration pilots Quebec-selected skilled workers Fees $CAN Your application This amount includes the processing fee and the right of permanent residence fee. 1,590.00 Your application (without right of permanent residence fee) 990.00'),
  ('ca-express-entry', 'spouse_or_partner_fee', 'Include your spouse or partner This amount includes the processing fee and the right of permanent residence fee. 1,590.00 Include your spouse or partner (without right of permanent residence fee) 990.00'),
  ('ca-express-entry', 'dependent_child_fee', 'Include a dependent child 270.00 (per child)'),
  ('ca-express-entry', 'right_of_permanent_residence_fee', 'Right of permanent residence fee Fees $CAN Right of permanent residence fee 600.00 For most permanent residence applications, you need to pay the right of permanent residence fee (RPRF) when your application is approved. You will have to pay it before you can become a permanent resident.'),
  ('ca-express-entry', 'provincial_nominee_program', 'If you’re eligible for one of these programs, you can also apply through Express Entry for the Provincial Nominee Program. If you’re nominated, you’ll get extra points so you can be invited to apply quickly.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'sponsor_at_least_18', 'are at least 18 years old'),
  ('ca-sponsor-your-spouse-partner-or-child', 'sponsor_canadian_status', 'are a Canadian citizen, a permanent resident of Canada, or a person registered in Canada under the Canadian Indian Act'),
  ('ca-sponsor-your-spouse-partner-or-child', 'sponsor_lives_in_canada', 'live in Canada If you’re a Canadian citizen living outside Canada, you must show that you plan to live in Canada when the people you’re sponsoring become permanent residents. If you’re a permanent resident living outside Canada, you can’t sponsor.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'undertaking_and_sponsorship_agreement', 'commit to supporting the people you’re sponsoring by signing an undertaking and sponsorship agreement'),
  ('ca-sponsor-your-spouse-partner-or-child', 'meet_irpa_and_irpr', 'meet all other requirements under the Immigration and Refugee Protection Act and the Immigration and Refugee Protection Regulations'),
  ('ca-sponsor-your-spouse-partner-or-child', 'income_requirement', 'In most cases, there isn’t an income requirement to sponsor your spouse, partner or dependent child. You only need to show that you have enough money to meet the income requirement if you’re sponsoring a dependent child that has 1 or more dependent children of their own you’re sponsoring a spouse or partner that has a dependent child, and their dependent child has 1 or more dependent children of their own The Financial Evaluation Form (IMM 1283) explains how much money you’ll need and how to fill out the form.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'no_recent_sponsorship_bar', 'You may not be eligible to sponsor your spouse or partner if you were sponsored by a spouse or partner and you became a permanent resident less than 5 years ago signed an undertaking for a previous spouse or partner that you sponsored and it hasn’t been 3 years since they became a permanent resident'),
  ('ca-sponsor-your-spouse-partner-or-child', 'not_otherwise_barred_from_sponsoring', 'You may not be eligible to sponsor your spouse, partner or child if you have already applied to sponsor the same spouse, partner or child and a decision on that application hasn’t been made yet are in jail, prison or a penitentiary are behind on payments for an immigration loan a performance bond court-ordered family support payments such as alimony or child support'),
  ('ca-sponsor-your-spouse-partner-or-child', 'no_cosigner_for_spouse_or_partner', 'You can’t have a co-signer if you are sponsoring your spouse, common-law partner or conjugal partner.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'applicant_photo', 'Photo specifications The principal applicant and their accompanying family members each need to give 1 photo. Follow the instructions in the online application to scan and upload both sides of the photo.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'processing_fee_receipt', 'You have to pay your fees online (opens in a new tab) and include the receipt with your application. The instruction guide can help you understand which fees apply to you.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'imm1344', 'Sponsoring your spouse, common-law partner, conjugal partner or dependent child Application to Sponsor, Sponsorship Agreement and Undertaking (IMM 1344) Who must fill out this application form? This form must be filled out and digitally signed by: the sponsor, the co-signer, if applicable, the principal applicant (person being sponsored).'),
  ('ca-sponsor-your-spouse-partner-or-child', 'imm5476', 'If you want to use a paid representative, you must: download the Use of a Representative (IMM 5476) form complete and sign it get your representative to sign it upload it with your application'),
  ('ca-sponsor-your-spouse-partner-or-child', 'two_applications_via_pr_portal', 'To sponsor your spouse, partner or child, there are 2 applications: Sponsorship application: You apply to become a sponsor. Permanent residence application: Your spouse, partner or child applies for permanent residence. The principal applicant (the person you’re sponsoring) will submit both applications together online using the Permanent Residence (PR) Portal.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'get_application_package', 'See your application package for the document checklist for you and the people you’re sponsoring all the forms you and the people you’re sponsoring need to fill out country-specific forms and instructions based on where the people you’re sponsoring live'),
  ('ca-sponsor-your-spouse-partner-or-child', 'complete_and_sign_before_submitting', 'Before the principal applicant submits the application, they should make sure they answer all questions on the forms electronically sign the application (they will type their full name exactly as shown on their passport) include the processing fee receipt upload all the supporting documents If the application is incomplete, we’ll reject it.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'minor_principal_applicant_signature', 'Note: A parent or legal guardian must sign on behalf of a dependent child under the age of 18, where they are the principal applicant being sponsored on an application. The application will be returned if any signatures are missing (see section 10 of the IRPR for more information).'),
  ('ca-sponsor-your-spouse-partner-or-child', 'quebec_undertaking', 'If you live in Quebec Once the principal applicant submits the sponsorship and permanent residence application, you must complete an undertaking with the Government of Quebec.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'medical_exam_and_police_certificate', 'Other fees Depending on your situation, you may need to pay third parties for a medical exam a police certificate'),
  ('ca-sponsor-your-spouse-partner-or-child', 'sponsorship_fee_spouse_or_partner', 'Spouse, partner or children (abroad) Fees $CAN Sponsor your spouse or partner This amount includes the sponsorship fee, the processing fee and the right of permanent residence fee. 1,260.00 Sponsor your spouse or partner without right of permanent residence fee This amount includes the sponsorship fee, the processing fee and the right of permanent residence fee. 660.00'),
  ('ca-sponsor-your-spouse-partner-or-child', 'dependent_child_fee', 'Include any dependent child This amount includes the sponsorship fee, the processing fee and the right of permanent residence fee. 180.00 (per child) Independently sponsor a dependent child This amount includes the sponsorship fee, the processing fee and the right of permanent residence fee. 180.00 (per child)'),
  ('ca-sponsor-your-spouse-partner-or-child', 'right_of_permanent_residence_fee', 'Right of permanent residence fee Fees $CAN Right of permanent residence fee 600.00 For most permanent residence applications, you need to pay the right of permanent residence fee (RPRF) when your application is approved. You will have to pay it before you can become a permanent resident.'),
  ('ca-sponsor-your-spouse-partner-or-child', 'biometrics_fee', 'Biometrics – per individual 85.00 Biometrics – per family of 2 or more eligible people Maximum fee for a family of 2 or more people applying at the same time Family members eligible for this fee are your spouse or common-law partner your dependent children and their dependent children Check if your child is a dependant. 170.00'),
  ('ca-study-permit', 'enrolled_at_dli', 'You can come to Canada to study if you are enrolled at a DLI'),
  ('ca-study-permit', 'sufficient_funds', 'prove you have enough money to pay for your tuition fees living expenses for yourself and any family members who come with you to Canada and return transportation for yourself and any family members who come with you to Canada'),
  ('ca-study-permit', 'no_criminal_record', 'obey the law, have no criminal record and get a police certificate (if required)'),
  ('ca-study-permit', 'good_health', 'are in good health and get a medical exam (if required) and'),
  ('ca-study-permit', 'will_leave_canada', 'prove to an officer that you will leave Canada when your study permit expires'),
  ('ca-study-permit', 'letter_of_acceptance', 'Get your letter of acceptance Always required Your school will give you a letter of acceptance. Upload this to your online application.'),
  ('ca-study-permit', 'provincial_attestation_letter', 'Apply for a provincial or territorial attestation letter Needed in most cases Get a provincial or territorial attestation letter (PAL/TAL) from your school. In most cases, you need to accept your offer and pay your tuition fees, either in part or in full, to get your PAL/TAL. If you’re studying in Quebec, you need a Quebec Acceptance Certificate (Certificat d’acceptation du Québec [CAQ]).'),
  ('ca-study-permit', 'passport_copy', 'Show proof of identity Always required To show proof of identity, you (and each family member who comes with you) must have a copy of a valid passport or travel document'),
  ('ca-study-permit', 'passport_photos', '2 recent passport size photos The name and date of birth of the person must be written on the back of each photo.'),
  ('ca-study-permit', 'proof_of_funds', 'Show proof of funds Always required To support yourself and any family members coming with you, you must show proof of funds.'),
  ('ca-study-permit', 'custodianship_proof_of_care', 'Proof of care (for minor children in Canada) Check if needed Children under the age of 17 who are not coming to Canada with a parent or legal guardian must have an appointed custodian.'),
  ('ca-study-permit', 'marriage_certificate_copy', 'If you are married, you must send a photocopy of your marriage licence or certificate with your application.'),
  ('ca-study-permit', 'imm1294', 'Application for Study Permit Made Outside of Canada (IMM 1294) Who must fill out this application form? Each person requiring a study permit to come to Canada must complete this form.'),
  ('ca-study-permit', 'imm5409', 'If you are in a common-law union, you must also fill out the Statutory Declaration of Common-law Union [IMM 5409] (opens in a new tab) form and include it with your application.'),
  ('ca-study-permit', 'imm5476', 'If you wish to have a representative who can conduct business on your behalf, you must give us their email and mailing addresses in this section and fill out the Use of a Representative IMM 5476 (opens in a new tab) form.'),
  ('ca-study-permit', 'apply_online', 'If you’re applying for a study permit, you must apply online, whether you’re outside of Canada or already in Canada. You’re only eligible to apply on paper if you have a disability that prevents you from applying online hold an identity or travel document for non-national residents, refugees or stateless persons'),
  ('ca-study-permit', 'ircc_online_account', 'You need an account to apply online. You can use your account to: pay your fees submit your application check the status of your application'),
  ('ca-study-permit', 'biometrics', 'If you’re between 14 and 79 years old, you probably need to give your fingerprints and photo (biometrics).You only need to give your biometrics once every 10 years to make repeat trips to Canada easier.'),
  ('ca-study-permit', 'medical_exam', 'Get a medical exam Check if needed You may need a medical exam if any of these situations apply to you: You plan to stay in Canada for more than 6 months. You recently spent time in certain countries. You plan to work in certain jobs where public health must be protected.'),
  ('ca-study-permit', 'police_certificate', 'Get a police certificate Check if needed In some cases, we may ask you for a police certificate. If you think you might need one, you should apply for one as early as possible.'),
  ('ca-study-permit', 'study_permit_fee', 'Study Permits (including extensions) Fees $CAN Study permit (including extensions) – per person 150.00'),
  ('ca-study-permit', 'biometrics_fee', 'Biometrics – per individual 85.00 Biometrics – per family of 2 or more eligible people Maximum fee for a family of 2 or more people applying at the same time Family members eligible for this fee are your spouse or common-law partner your dependent children and their dependent children Check if your child is a dependant. 170.00'),
  ('ca-study-permit', 'letter_of_explanation', 'Write a letter of explanation Recommended You must explain why you want to study in Canada, and that you understand your responsibilities as an international student in Canada.'),
  ('ca-super-visa', 'host_is_child_or_grandchild', 'To be eligible for a super visa, you must have a host who you can prove is your biological or adopted child or grandchild'),
  ('ca-super-visa', 'host_status_and_age', 'is a Canadian citizen, permanent resident of Canada or registered Indian is at least 18 years old and lives in Canada'),
  ('ca-super-visa', 'host_meets_minimum_necessary_income', 'meets or exceeds the minimum necessary income'),
  ('ca-super-visa', 'host_letter_of_invitation', 'writes and signs a letter of invitation (opens in a new tab) for you to come Canada'),
  ('ca-super-visa', 'applicant_outside_canada', 'To be eligible, you (the applicant) must be outside Canada when you submit your application have your visa printed by a visa office outside Canada (wait for visa office instructions) be allowed to enter Canada'),
  ('ca-super-visa', 'private_health_insurance_one_year', 'show proof that you have private health insurance valid for a minimum of 1 year from the date of entry from a Canadian insurance company or from a company outside Canada that has been approved by the minister'),
  ('ca-super-visa', 'immigration_medical_exam', 'take an immigration medical exam (opens in a new tab) meet certain other conditions'),
  ('ca-super-visa', 'genuine_visitor_assessment', 'Before we make a decision on your application, we’ll also consider whether you’re a genuine visitor to Canada who will leave by choice at the end of your visit your ties to your home country the purpose of your visit your family and finances'),
  ('ca-super-visa', 'visa_exempt_still_needs_eta_by_air', 'Even if you don’t need a visitor visa to enter Canada, you can still get a super visa to stay in Canada for 5 years. If we approve your application, we’ll issue you a letter to give to a border services officer when you arrive in Canada. If you travel by air, you may also need to apply for an electronic travel authorization (eTA) separately to allow you to travel to and enter Canada.'),
  ('ca-super-visa', 'sponsorship_application_does_not_block', 'If you’ve already submitted a sponsorship application, you can apply for a super visa while you wait for a decision or withdraw your sponsorship application at any time and apply for a super visa'),
  ('ca-super-visa', 'stay_five_years_per_entry', 'You’re eligible to stay for 5 years at a time. If a border officer grants you entry to Canada, you can stay for 5 years, even if the border officer doesn’t stamp your passport.'),
  ('ca-super-visa', 'insurance_policy_conditions', 'The health insurance policy should include the insurance company name that issued the policy (sometimes known as “the insurer” or “the underwriter”) be valid for a minimum of 1 year from the date of entry be paid in full or in instalments with a deposit (quotes aren’t accepted) cover the applicant’s health care, hospitalization and repatriation provide a minimum emergency coverage of $100,000 be valid for each entry to Canada be available for review by the border services officers on request'),
  ('ca-super-visa', 'insurer_must_be_osfi_listed_if_foreign', 'Your insurant must be from either a Canadian insurance company or an insurance company outside Canada that is authorized by the Office of the Superintendent of Financial Institutions (OSFI) under the Insurance Companies Act to provide accident and sickness insurance, and appears on OSFI’s publicly available list of federally regulated financial institutions, and has issued or made the policy while doing insurance business in Canada'),
  ('ca-super-visa', 'proof_of_medical_exam', 'You must provide proof that you had a medical exam with an approved panel physician.'),
  ('ca-super-visa', 'proof_of_host_status', 'You must provide proof that your host is one of the following: a Canadian citizen Provide a copy of Canadian citizenship for your host (and their spouse or common-law partner if applicable). a permanent resident Provide a copy of a permanent resident document for your host (and their spouse or common-law partner, if applicable). a registered Indian Provide a copy of a Secure Certificate of Indian Status or Certificate of Indian Status (status card) for your host (and their spouse or common-law partner, if applicable).'),
  ('ca-super-visa', 'proof_of_relationship', 'You must prove that you’re the parent or grandparent of your host. We accept the following documents as proof: a copy of the host’s birth certificate or baptismal certificate another official document naming you as the parent or grandparent of your host'),
  ('ca-super-visa', 'letter_of_invitation_contents', 'Your letter of invitation, written and signed by your host child or grandchild, must include proof that they meet or exceed the minimum necessary income'),
  ('ca-super-visa', 'co_signer_limited_to_spouse', 'Your host child’s or grandchild’s spouse or common-law partner may co-sign the letter of invitation and provide proof of income, if required, to meet the minimum necessary income. Other family members of your host, such as siblings, can’t co-sign.'),
  ('ca-super-visa', 'local_visa_office_instructions', 'Your visa office may require additional documents. Tell us where you’re applying from to get the visa office requirements for your country or territory.'),
  ('ca-super-visa', 'family_size_counts_people_outside_canada', 'To determine your host’s minimum necessary income, include the following people in the family size count: you and any other super visa applicants the host will be supporting (such as your spouse or common-law partner) the host child or grandchild the host’s spouse (which might include a separated spouse) or common-law partner dependent children of the host and of their spouse or common-law partner'),
  ('ca-super-visa', 'dependent_children_counted_regardless_of_custody', 'Children who meet the definition of a dependent child must be included in the count, regardless of custody and child support arrangements.'),
  ('ca-super-visa', 'minimum_necessary_income_table', 'Minimum income your host needs based on the size of the family Updated July 29, 2025 Number of family members Minimum income the host needs (in Canadian dollars) 1 $30,526 2 $38,002 3 $46,720 4 $56,724 5 $64,336 6 $72,560 7 $80,784 If more than 7 people, for each additional family member, add $8,224'),
  ('ca-super-visa', 'income_proof_option_one', 'Option 1 Your host can show that their total income (including the co-signer’s income, if applicable) meets or exceeds the minimum required amount in either of the 2 tax years before the application is submitted. Documents to prove the income requirement Your host, or their co-signer, must include their notice of assessment from the Canada Revenue Agency (CRA).'),
  ('ca-super-visa', 'income_proof_option_two', 'Option 2 Your host can show that their total income (including the co-signer’s income, if applicable) in the year before the application is submitted was at least 75% of the minimum required amount. You can add your own income to cover the remaining amount, if needed. The combined amount must meet or exceed the minimum necessary income requirements.'),
  ('ca-super-visa', 'applicant_income_must_continue', 'You must provide proof that you’ll continue to earn an income while in Canada. The document you use to prove this must include the currency you’re paid in.'),
  ('ca-visitor-visa-temporary-resident-visa', 'valid_travel_document', 'You must: have a valid travel document, like a passport'),
  ('ca-visitor-visa-temporary-resident-visa', 'good_health', 'be in good health'),
  ('ca-visitor-visa-temporary-resident-visa', 'no_convictions', 'have no criminal or immigration-related convictions'),
  ('ca-visitor-visa-temporary-resident-visa', 'ties_to_home_country', 'convince an immigration officer that you have ties—such as a job, home, financial assets or family—that will take you back to your home country'),
  ('ca-visitor-visa-temporary-resident-visa', 'will_leave_canada', 'convince an immigration officer that you will leave Canada at the end of your visit'),
  ('ca-visitor-visa-temporary-resident-visa', 'sufficient_funds', 'have enough money for your stay The amount of money you will need depends on how long you will stay and if you will stay in a hotel, or with friends or relatives.'),
  ('ca-visitor-visa-temporary-resident-visa', 'passport_copy', 'All applicants need to include a digital copy of your valid (not expired) passport or travel document Your passport or travel document should be valid for at least 6 months from the date you plan to travel.'),
  ('ca-visitor-visa-temporary-resident-visa', 'minor_travel_authorization', 'a letter that authorizes a minor child to travel to Canada (if applicable) You may need to include other documents, depending on whether the minor child travels alone or not.'),
  ('ca-visitor-visa-temporary-resident-visa', 'imm5257', 'Application for visitor visa (temporary resident visa) (IMM 5257)'),
  ('ca-visitor-visa-temporary-resident-visa', 'imm5645', 'Your document checklist may include supporting documents such as the following: Family Information (IMM 5645) form'),
  ('ca-visitor-visa-temporary-resident-visa', 'imm5476', 'Use of a representative (IMM 5476) (opens in a new tab) (if using an authorized representative)'),
  ('ca-visitor-visa-temporary-resident-visa', 'imm5475', 'Authority to Release Personal Information to a Designated Individual (IMM 5475) form (opens in a new tab) (if authorizing information from your case file to be released to someone other than yourself)'),
  ('ca-visitor-visa-temporary-resident-visa', 'invitation_letter', 'You may also need a medical exam and letter of invitation from someone who lives in Canada.'),
  ('ca-visitor-visa-temporary-resident-visa', 'medical_exam', 'You may also need a medical exam and letter of invitation from someone who lives in Canada.'),
  ('ca-visitor-visa-temporary-resident-visa', 'biometrics', 'If you are a citizen of certain countries or territories, you have to give your biometrics (fingerprints and photograph) when you apply for a: visitor visa'),
  ('ca-visitor-visa-temporary-resident-visa', 'processing_fee', 'Visitor visa - per person Single or multiple entry temporary resident visa What''s this? Single or multiple entry temporary resident visa The same fee applies to both types of visas. We’ll decide which visa to give you based on your application. Find out more about the difference between single and multiple entry visas. 100.00'),
  ('ca-visitor-visa-temporary-resident-visa', 'biometrics_fee', 'Biometrics – per individual 85.00'),
  ('ca-visitor-visa-temporary-resident-visa', 'travel_history', 'Recommended documents Travel history If you’ve travelled to Canada or to other countries, this can show that you’ve been able to get a visa in the past.'),
  ('ca-work-permit', 'work_permit_required', 'Most foreign nationals need a work permit to work in Canada. You may be eligible for an employer-specific or an open work permit.'),
  ('ca-work-permit', 'job_offer_for_employer_specific_permit', 'Types of work permits Employer-specific work permit Job offer required Open work permit Job offer not required'),
  ('ca-work-permit', 'permit_duration_within_passport_validity', 'Note: A work permit cannot be issued for a duration that is longer than the validity of your passport.'),
  ('ca-work-permit', 'lmia_and_employment_contract', 'a) If you need an LMIA to get a work permit, type the name of the employer as shown on the LMIA. Attach original employment contract and LMIA.'),
  ('ca-work-permit', 'lmia_or_offer_of_employment_number', 'Type the seven-digit number of your valid LMIA or the alpha numeric combination of the offer of employment number (LMIA Exempt). This number begins with the letter “A” and is followed by seven numbers.'),
  ('ca-work-permit', 'marriage_certificate_copy', 'If you are married, you must send a photocopy of your marriage licence or certificate with your application.'),
  ('ca-work-permit', 'imm1295', 'Application for Work Permit Made Outside of Canada (IMM 1295) Who must fill out this application form? Each person who needs a work permit must fill out this form.'),
  ('ca-work-permit', 'imm5409', 'If you are in a common-law union, you must also fill out the Statutory Declaration of Common-law Union [IMM 5409] (opens in a new tab) form and include it with your application.'),
  ('ca-work-permit', 'imm5476', 'If you wish to have a representative who can conduct business on your behalf, you must give us their email and mailing addresses in this section and fill out the Use of a Representative [IMM 5476] (opens in a new tab) form.'),
  ('ca-work-permit', 'submit_application_online', 'Submit your application Sign in to your account, upload documents, pay fees, give biometrics'),
  ('ca-work-permit', 'validate_form_barcode_page', 'Note: If this application form is completed on a computer it must be validated to generate a barcode page. If you apply on paper, print and place the barcode page (page 5 of 5) on the top of your application (or if applying as a group, each individual application package).'),
  ('ca-work-permit', 'original_passport_for_visa_counterfoil', 'Note: If you need a Temporary Resident Visa (TRV) and your work permit application is approved, you must give us your original passport so we can issue the visa counterfoil.'),
  ('ca-work-permit', 'work_permit_fee', 'Work Permits (including extensions) Fees $CAN Work permit (including extensions) – per person 155.00 Work permit (including extensions) – per group (3 or more performing artists) Maximum fee for a group of 3 or more performing artists applying at the same time and place 465.00'),
  ('ca-work-permit', 'biometrics_fee', 'Biometrics – per individual 85.00 Biometrics – per family of 2 or more eligible people Maximum fee for a family of 2 or more people applying at the same time Family members eligible for this fee are your spouse or common-law partner your dependent children and their dependent children Check if your child is a dependant. 170.00 Biometrics – per group of 3 or more performing artists Maximum fee for a group of 3 or more performing artists applying for a work permit at the same time 255.00'),
  ('fi-employed-person', 'confirmed_employment', 'You must have confirmed employment before you can apply for this permit.'),
  ('fi-employed-person', 'field_of_employment_scope', 'A residence permit for an employed person is granted for the field of employment to which your job belongs.'),
  ('fi-employed-person', 'found_a_job_terms_of_employment', 'Your employer must supplement your application by filling in and submitting your terms of employment. The employer can do it either online in Enter Finland or by using a paper form.'),
  ('fi-employed-person', 'qualifications_verified_by_employer', '2. You have sufficient qualifications and education for the job in question. Your employer must verify that you have the professional skills required for the job. Your employer must document this when they fill in the terms of employment for your application.'),
  ('fi-employed-person', 'regulated_profession_authorisation', 'Health care professionals, for example, need a permission to practise their profession from the Finnish Supervisory Agency (lvv.fi), the National Supervisory Authority for Welfare and Health.'),
  ('fi-employed-person', 'income_requirement', 'Your total gross salary must be at least EUR 1,600 per month in 2026. You may earn your income from several employment relationships. The employment relationship or employment relationships may be part-time.'),
  ('fi-employed-person', 'zero_hours_contracts_excluded', 'However, a zero-hours contract or an on-demand contract of employment do not meet the requirements for granting a residence permit for an employed person because your employer has not agreed on regular minimum working hours with you.'),
  ('fi-employed-person', 'salary_supplements_excluded', 'Salary supplements, such as evening work or night work supplements, are excluded from the total salary.'),
  ('fi-employed-person', 'fringe_benefits_cap', 'Some of your salary may consist of fringe benefits, such as company car or employer-provided accommodation. A maximum of 50% of your salary may consist of fringe benefits. When your salary is assessed, the taxable value of your fringe benefits will be taken into account in the calculation.'),
  ('fi-employed-person', 'labour_market_test', 'A residence permit for an employed person may be subject to labour market testing, which means that the employer must establish if there is available labour force within a reasonable time in Finland or within the EU/EEA for the work in question.'),
  ('fi-employed-person', 'light_entrepreneurs_excluded', 'A residence permit for an employed person is not granted to so called light entrepreneurs (who work through an invoicing service company).'),
  ('fi-employed-person', 'supply_contract', 'You must also attach a supply contract to your residence permit application, indicating the work covered by the contract.'),
  ('fi-employed-person', 'apply_abroad_for_first_permit', 'If you apply for this permit as a first residence permit, you must submit the application abroad. Applications for an extended permit can only be submitted in Finland.'),
  ('fi-employed-person', 'application_fee_electronic', 'Electronic application fee First permit 750 € / extended permit 230 €'),
  ('fi-employed-person', 'application_fee_paper', 'Paper application fee First permit 950 € / extended permit 430 €'),
  ('fi-employed-person', 'passport', 'A valid passport issued by your country of nationality. For more information, see the page Passports and other travel documents. Show the passport when you visit a service point to prove your identity.'),
  ('fi-employed-person', 'passport_photo', 'A passport photo complying with the photo guidelines issued by the police, or a photograph retrieval code you received from a photo shop The passport photo must be no more than 6 months old.'),
  ('fi-employed-person', 'passport_copies', 'Colour copies of the passport page containing personal data and of all passport pages that contain notes'),
  ('fi-employed-person', 'proof_of_legal_stay_where_applying', 'Document showing that you are legally staying in the country where you submit the application This document is not needed if you apply for an extended permit.'),
  ('fi-employed-person', 'form_mp1', 'Response to possible denial of admittance or stay and to entry ban (the form MP_1) This form is needed only if you, for some reason, submit your residence permit application in Finland.'),
  ('fi-employed-person', 'prove_identity_in_person', 'If you applied for your residence permit abroad, book an appointment to visit a Finnish mission (finlandabroad.fi).'),
  ('fi-employed-person', 'no_work_before_permit', 'You cannot start working before you get a residence permit for an employed person.'),
  ('fi-employed-person', 'work_confined_to_granted_field', 'You can only work in the field of employment to which your job belongs and for which you have been granted a residence permit. You may have several jobs in the same field of employment.'),
  ('fi-employed-person', 'general_valid_passport', 'You have a valid passport. When you apply for a residence permit, you must usually have a valid national passport.'),
  ('fi-employed-person', 'general_no_entry_prohibition', 'You have not been prescribed a prohibition of entry.'),
  ('fi-employed-person', 'general_public_order', 'You are not a danger to public order or security.'),
  ('fi-employed-person', 'general_national_security', 'You are not a danger to national security.'),
  ('fi-employed-person', 'general_public_health', 'You are not a danger to public health.'),
  ('fi-employed-person', 'general_international_relations', 'You are not a danger to Finland’s international relations.'),
  ('fi-entrepreneur', 'eligible_form_of_business', '1. You are a self-employed person and your form of business is one of the following: a private trader, in other words a private entrepreneur a partner in a general partnership a general partner (not a silent partner) in a limited partnership a member of a cooperative who has an unlimited liability for refinancing entrepreneur in a limited liability company'),
  ('fi-entrepreneur', 'shareholder_thirty_percent_and_managerial', 'a shareholder in a managerial position in a limited-liability company (Managing Director or member of the Board of Directors) or a person working in another type of company in a managerial position if you personally own at least 30 per cent of the company’s share capital or personally have at least 30 per cent of the number of votes produced by the company’s shares'),
  ('fi-entrepreneur', 'business_must_be_profitable', '2. Your business operations are profitable. Your business must be profitable. Your means of support must be secured by your income from your business. Economic Development Centre will assess whether you meet these requirements.'),
  ('fi-entrepreneur', 'registered_in_trade_register', '3. You have registered your business in the Trade Register maintained by the Finnish Patent and Registration Office.'),
  ('fi-entrepreneur', 'business_id_required', 'You can apply for a residence permit for an entrepreneur only if you have your own Business ID.'),
  ('fi-entrepreneur', 'private_trader_business_id_exception', 'As a private trader, you can apply for a residence permit for an entrepreneur without a Business ID only if you apply for a first residence permit before arriving in Finland. This is because you cannot establish an individually-owned business (toiminimi) abroad.'),
  ('fi-entrepreneur', 'must_also_work_in_the_company', 'You cannot get a residence permit only because you own a company. You must also work in the company in Finland.'),
  ('fi-entrepreneur', 'two_stage_decision', 'The application will be processed in two stages. First, the Economic Development Centre (elinvoimakeskus.fi) will make a partial decision. After this, the Finnish Immigration Service will process the application. If you do not meet the general requirements for obtaining a residence permit, the Economic Development Centre will not issue a partial decision.'),
  ('fi-entrepreneur', 'light_entrepreneurs_and_freelancers_excluded', 'If you are a freelancer or working through an invoicing service company (in Finnish: kevytyrittäjä), it is not possible to apply for this permit.'),
  ('fi-entrepreneur', 'apply_abroad_for_first_permit', 'If you apply for this permit as a first residence permit, you must submit the application abroad. Applications for an extended permit can only be submitted in Finland.'),
  ('fi-entrepreneur', 'application_fee_electronic', 'Electronic application fee First permit 750 € / extended permit 230 €'),
  ('fi-entrepreneur', 'application_fee_paper', 'Paper application fee First permit 900 € / extended permit 430 €'),
  ('fi-entrepreneur', 'general_attachments', 'A valid passport issued by your country of nationality. For more information, see the page Passports and other travel documents. Show the passport when you visit a service point to prove your identity. A passport photo complying with the photo guidelines issued by the police (poliisi.fi), or a photograph retrieval code you received from a photo shop The passport photo must be no more than 6 months old. Colour copy of the passport page containing your personal data.'),
  ('fi-entrepreneur', 'form_mp1', 'Response to possible denial of admittance or stay and to entry ban (the form MP_1) This form is needed only if you, for some reason, submit your residence permit application in Finland.'),
  ('fi-entrepreneur', 'business_plan', 'Business plan Add this attachment if you are applying for a first residence permit for an entrepreneur or if you are applying for an extended permit and there have been changes in your business activities.'),
  ('fi-entrepreneur', 'financial_forecast_two_years', 'Financial forecast for the next two years Add this attachment only if you are applying for a first residence permit for an entrepreneur or if you are applying for an extended permit and there have been changes in your business activities.'),
  ('fi-entrepreneur', 'bank_statements_three_months', 'Proof of financial resources (a bank statement, for example) Attach bank statements from your own bank account from the past three months if you have funds of your own for the initial operating stage of your company or for supporting yourself.'),
  ('fi-entrepreneur', 'company_form_documents', 'Attachments regarding form of company: If your company is a limited liability company: memorandum of association, if your company has not been entered in the Finnish Trade Register; articles of association, if your company has not been entered in the Finnish Trade Register; shareholder register.'),
  ('fi-entrepreneur', 'business_premises_documents', 'Documents regarding your company’s business premises (rental agreement or proof of ownership of the premises) Add this attachment if your company has business premises and if you are applying for a first residence permit or if you are applying for an extended permit and there have been changes in your business activities.'),
  ('fi-entrepreneur', 'qualifications_evidence', 'Proof of professional qualifications and competence (degree certificates and/or certificates of employment) Add these attachments if you have relevant work experience or qualifications in your company’s line of business.'),
  ('fi-entrepreneur', 'general_valid_passport', 'You have a valid passport. When you apply for a residence permit, you must usually have a valid national passport.'),
  ('fi-entrepreneur', 'general_no_entry_prohibition', 'You have not been prescribed a prohibition of entry.'),
  ('fi-entrepreneur', 'general_public_order', 'You are not a danger to public order or security.'),
  ('fi-entrepreneur', 'general_national_security', 'You are not a danger to national security.'),
  ('fi-entrepreneur', 'general_public_health', 'You are not a danger to public health.'),
  ('fi-entrepreneur', 'general_international_relations', 'You are not a danger to Finland’s international relations.'),
  ('fi-family-spouse', 'married_or_registered_partnership', '1 You and your spouse are married or in a registered partnership. If you are married, present a marriage certificate. If you are in a registered partnership, present a certificate of registered partnership. The certificate must be legalised, unless it has been issued in the Nordic countries or in an EU Member State.'),
  ('fi-family-spouse', 'sponsor_holds_permit_or_applies_together', '2 Your spouse has a residence permit in Finland or you are applying for a residence permit at the same time with your spouse.'),
  ('fi-family-spouse', 'both_spouses_at_least_21', '3 You and your spouse are at least 21 years of age when your residence permit becomes valid. The residence permit application may be submitted at the earliest 9 months before turning 21. If you submit the application earlier, the decision may be negative. The validity period of the residence permit cannot begin before you and your spouse have turned 21. If you and your spouse have joint custody of a child, you can obtain a residence permit as the child’s parent or guardian even if you or your spouse are not yet 21 years of age. If your spouse has a residence permit for studies in Finland, you can submit your application 3 months before you turn 21 or your spouse turns 21 at the earliest.'),
  ('fi-family-spouse', 'income_requirement', '4 Income requirement. You must meet the income requirement (requirement for sufficient financial resources). You can prove that you meet the income requirement by submitting evidence of your or your spouse’s salary or income from business activities, for example. Your income cannot be based on social assistance, labour market subsidy, basic unemployment allowance or general social security benefit. Note that the general social security benefit paid by Kela replaces labour market subsidy and basic unemployment allowance as of 1 May 2026.'),
  ('fi-family-spouse', 'general_attachments', 'General attachments A valid passport issued by your country of nationality. For more information, see the page Passports and other travel documents. Show the passport when you visit a service point to prove your identity. A passport photo complying with the photo guidelines issued by the police (poliisi.fi), or a photograph retrieval code you received from a photo shop The passport photo must be no more than 6 months old. Colour copy of the passport page containing your personal data and copies of all passport pages with notes.'),
  ('fi-family-spouse', 'supplement_form_spouse', 'Supplement form for spouse LIITE_PUOLISO (pdf) (your spouse or partner must fill in and sign the form).'),
  ('fi-family-spouse', 'proof_of_legal_stay_where_applying', 'Document showing that you are legally staying in the country where you submit the application.'),
  ('fi-family-spouse', 'form_mp1', 'Form MP_1 (pdf) (if you already are in Finland and apply for your first residence permit).'),
  ('fi-family-spouse', 'legalisation_and_translation', 'The documents must be legalised, unless they have been issued by authorities of the Nordic countries or by authorities of an EU Member State. If the attachments are in a language other than Finnish, Swedish or English, you must have them translated by an authorised translator or by an official translator of another EU Member State. In some situations, the attachments must also be verified before legalisation.'),
  ('fi-family-spouse', 'relationship_certificates', 'Marriage certificate if the marriage was contracted in another country than Finland. Certificate of registered partnership if the partnership was registered in another country than Finland.'),
  ('fi-family-spouse', 'prior_relationship_certificates', 'Divorce certificate (if your spouse or you have previously been married to someone and have divorced) Certificate of dissolution of registered partnership (if your spouse or you have previously been in a registered partnership that has been dissolved) Death certificate (if your spouse or you have previously been married or in a registered partnership and the former spouse has died).'),
  ('fi-family-spouse', 'prove_identity_abroad', '3 Prove your identity. Book an appointment to visit a Finnish mission (finlandabroad.fi) to prove your identity. Applications for a first residence permit can be submitted in Finland only in certain exceptional situations.'),
  ('fi-family-spouse', 'income_is_net_and_regional', 'The required income is calculated from your net income, that is, from income that remains after tax and after employer’s and employee’s pension and insurance contributions. The amount of money that is required is based on the basic social assistance granted to beneficiaries of social assistance by Kela and on the housing costs and healthcare expenses that are observed when granting social assistance. The amount of money that you must have depends on where you live, since there is regional variation in housing costs.'),
  ('fi-family-spouse', 'income_thresholds_helsinki_region', 'Required income: Income thresholds for families as of 1 November 2024 1. Helsinki metropolitan area: Espoo, Helsinki, Kauniainen, Vantaa Person €/month (net) €/year (net) 1 adult 1,210 14,520 2nd adult living in the same household 610 7,320 1st child 610 7,320 2nd child 480 5,760 3rd child 360 4,320 4th child 360 4,320 5th child 360 4,320 The income threshold for a family increases by 360 euros per each child starting from the third child.'),
  ('fi-family-spouse', 'income_thresholds_large_municipalities', '2. Other large municipalities: Hyvinkää, Hämeenlinna, Joensuu, Jyväskylä, Järvenpää, Kerava, Kirkkonummi, Kuopio, Lahti, Lohja, Nokia, Nurmijärvi, Oulu, Porvoo, Raisio, Riihimäki, Rovaniemi, Seinäjoki, Sipoo, Siuntio, Tampere, Turku, Tuusula, Vihti Person €/month (net) €/year (net) 1 adult 1,090 13,080 2nd adult living in the same household 550 6,600 1st child 550 6,600 2nd child 430 5,160 3rd child 320 3,840 4th child 320 3,840 5th child 320 3,840 The income threshold for a family increases by 320 euros per each child starting from the third child.'),
  ('fi-family-spouse', 'income_thresholds_other_municipalities', '3. Other municipalities: Person €/month (net) €/year (net) 1 adult 1,030 12,360 2nd adult living in the same household 520 6,240 1st child 520 6,240 2nd child 410 4,920 3rd child 310 3,720 4th child 310 3,720 5th child 310 3,720 The income threshold for a family increases by 310 euros per each child starting from the third child.'),
  ('fi-family-spouse', 'expense_compensating_benefits_count', 'Certain social benefits reduce the amount of financial resources required. These are called ‘social security benefits compensating for expenses’. For example the following benefits belong to this category: child benefit child care allowance child maintenance allowance study grant housing allowance'),
  ('fi-family-spouse', 'income_derogation_for_children', 'For families with children, we may deviate from the required sums on a case-by-case basis if the family’s income is slightly below the income threshold. Making an exception to the income requirement is possible if there are exceptionally weighty reasons or if a derogation is in the best interest of a child. If you are requesting an exception to the income requirement, submit an explanation and documents supporting your claim.'),
  ('fi-family-spouse', 'application_fee', 'Residence permits and registration of an EU citizen EUR Paper application Electronic application First residence permit (others than those mentioned below) 800 750'),
  ('fi-family-spouse', 'general_valid_passport', 'You have a valid passport. When you apply for a residence permit, you must usually have a valid national passport.'),
  ('fi-family-spouse', 'general_no_entry_prohibition', 'You have not been prescribed a prohibition of entry.'),
  ('fi-family-spouse', 'general_public_order', 'You are not a danger to public order or security.'),
  ('fi-family-spouse', 'general_national_security', 'You are not a danger to national security.'),
  ('fi-family-spouse', 'general_public_health', 'You are not a danger to public health.'),
  ('fi-family-spouse', 'general_international_relations', 'You are not a danger to Finland’s international relations.'),
  ('fi-residence-permit-studies', 'accepted_study_place', '2. You have a study place You can get a residence permit if you have been accepted to study at an educational institution in Finland. Your studies must lead to a vocational qualification or a degree. You may also get a residence permit for other types of studies if you have a well-founded reason for it. You cannot get a residence permit for studies to complete basic education.'),
  ('fi-residence-permit-studies', 'distance_learning_excluded', 'You cannot be granted a residence permit for studies, if your studies mainly consist of distance learning online and do not require you to stay in Finland.'),
  ('fi-residence-permit-studies', 'funds_800_per_month', '1. You need to be able to support yourself in Finland for the entire duration of your studies. You must have at least EUR 800 at your disposal every month to be able to pay for your accommodation, food and other needs. Add to your application proof of how you will finance your stay in Finland during the first year of studies. you must have 9,600 euros in your bank account when you submit the application. If your studies will take less than one year, you must have 800 euros per month at your disposal.'),
  ('fi-residence-permit-studies', 'tuition_fee_held_if_unpaid', 'If you will pay the tuition fee at a later stage, you must have the money for the tuition fee in your bank account when you submit the residence permit application.'),
  ('fi-residence-permit-studies', 'institutional_support_reduces_funds', 'If your educational institution supports your living in Finland, you do not necessarily need to have 800 euros per month at your disposal. Attach to your application documentation of the support your educational institution provides.'),
  ('fi-residence-permit-studies', 'private_medical_insurance', '3. You have insurance As a student, you must personally cover the costs if you become ill in Finland. In order to get a residence permit, you must take out private insurance that will cover your medical and pharmaceutical expenses. Attach a certificate of insurance to your application. Your insurance must be valid when you arrive in Finland. If you have a Kela card, a European Health Insurance Card (EHIC) or a UK Global Health Insurance Card (GHIC) you do not need to take out other insurance.'),
  ('fi-residence-permit-studies', 'apply_abroad_for_first_permit', 'Apply for a first residence permit abroad. You can only apply for an extended permit in Finland.'),
  ('fi-residence-permit-studies', 'application_fee_electronic', 'Electronic application fee First permit 600 € Electronic application fee, minor holder First permit 400 €'),
  ('fi-residence-permit-studies', 'application_fee_paper', 'Paper application fee First permit 750 € Paper application fee, minor holder First permit 430 €'),
  ('fi-residence-permit-studies', 'general_attachments', 'General attachments A valid passport issued by your country of nationality. For more information, see the page Passports and other travel documents. Show the passport when you visit a service point to prove your identity. A passport photo complying with the photo guidelines issued by the police (poliisi.fi), or a photograph retrieval code you received from a photo shop The passport photo must be no more than 6 months old. Colour copy of the passport page containing your personal data If applicable, a document showing that you are legally staying in the country where you submit your residence permit application to Finland (your visa or residence permit, for example)'),
  ('fi-residence-permit-studies', 'certificate_of_acceptance', 'Application-specific attachments Certificate of acceptance/attendance from your educational institution in Finland'),
  ('fi-residence-permit-studies', 'bank_statement_six_months', 'Documentation of sufficient financial resources. A bank statement covering the past 6 months.'),
  ('fi-residence-permit-studies', 'minor_applicant_attachments', 'If you are under 18 years of age, you should also attach to your application a birth certificate your parent’s or guardian’s consent for you to move to Finland.'),
  ('fi-residence-permit-studies', 'form_mp1', 'Form MP_1 (pdf) if you already are in Finland and apply for your first residence permit.'),
  ('fi-residence-permit-studies', 'right_to_work_30_hours', 'If you have been granted a residence permit for studies, you are allowed to work in paid employment in any field for an average of 30 hours per week. The number of working hours can be exceeded some weeks, as long as the average working hours are no more than 30 hours per week at the end of the year.'),
  ('fi-residence-permit-studies', 'a_or_b_permit_outcome', 'If you are coming to Finland to pursue a higher education degree, you will be granted an A permit, that is, a continuous residence permit. If you are coming to Finland to pursue a degree other than a higher education degree, you will be granted a B permit, that is, a temporary residence permit. B permits are also granted to exchange students.'),
  ('fi-residence-permit-studies', 'general_valid_passport', 'You have a valid passport. When you apply for a residence permit, you must usually have a valid national passport.'),
  ('fi-residence-permit-studies', 'general_no_entry_prohibition', 'You have not been prescribed a prohibition of entry.'),
  ('fi-residence-permit-studies', 'general_public_order', 'You are not a danger to public order or security.'),
  ('fi-residence-permit-studies', 'general_national_security', 'You are not a danger to national security.'),
  ('fi-residence-permit-studies', 'general_public_health', 'You are not a danger to public health.'),
  ('fi-residence-permit-studies', 'general_international_relations', 'You are not a danger to Finland’s international relations.'),
  ('fi-specialist', 'special_expertise_duties', '2. Your duties must require special expertise. Specialists include, among others: IT experts; experts in some field of specialisation who have a higher education degree; other persons with a higher education degree whose work requires special expertise.'),
  ('fi-specialist', 'salary_threshold', '3. Your gross salary must be at least EUR 3,937 per month in 2026. Fringe benefits are not counted towards this sum.'),
  ('fi-specialist', 'below_threshold_apply_as_employed_person', 'If your salary is less than EUR 3,937, you should apply for a residence permit for an employed person.'),
  ('fi-specialist', 'higher_education_or_acquired_expertise', '4. As a rule, you must have a higher education degree. If you have not completed a higher education degree, you need to have acquired the special expertise required in your work through work experience or other education. Your employer must verify that you have the special expertise required in your work.'),
  ('fi-specialist', 'confirmed_employment', 'You must have confirmed employment before you apply.'),
  ('fi-specialist', 'employer_terms_of_employment', '1. You must have a job in Finland. Your employer must supplement your application by filling in your terms of employment either online in Enter Finland for Employers or by using a paper form.'),
  ('fi-specialist', 'permit_duration_two_years', 'A first residence permit for a specialist is granted for a maximum of 2 years. If your employment lasts for less than 2 years, the permit will be valid for the duration of your employment relationship.'),
  ('fi-specialist', 'fast_track_available', 'You can apply for this residence permit via the fast-track service and get the permit in two weeks.'),
  ('fi-specialist', 'apply_abroad_for_first_permit', 'Apply for a first residence permit abroad. You can only apply for an extended permit in Finland.'),
  ('fi-specialist', 'application_fee_electronic', 'Electronic application fee First permit 530 € / extended permit 230 €'),
  ('fi-specialist', 'application_fee_paper', 'Paper application fee First permit 630 € / extended permit 430 €'),
  ('fi-specialist', 'passport', 'A valid passport issued by your country of nationality. For more information, see the page Passports and other travel documents. Show the passport when you visit a service point to prove your identity.'),
  ('fi-specialist', 'passport_photo', 'A passport photo complying with the photo guidelines issued by the police (poliisi.fi), or a photograph retrieval code you received from a photo shop The passport photo must be no more than 6 months old.'),
  ('fi-specialist', 'passport_copies', 'Colour copies of the passport page containing personal data and of all passport pages that contain notes'),
  ('fi-specialist', 'proof_of_legal_stay_where_applying', 'Document showing that you are legally staying in the country where you submit the application This document is not needed if you apply for an extended permit.'),
  ('fi-specialist', 'form_mp1', 'Response to possible denial of admittance or stay and to entry ban (the form MP_1) This form is needed only if you, for some reason, submit your residence permit application in Finland.'),
  ('fi-specialist', 'prove_identity_in_person', '4 Prove your identity If you applied for your residence permit abroad, book an appointment to visit a Finnish mission (finlandabroad.fi).'),
  ('fi-specialist', 'right_to_work_and_90_day_exemption', 'Right to work You have the right to work as a specialist. Check your right to work if you wish to change jobs. The right to work begins once a residence permit has been issued. Specialists may work without a residence permit if the work lasts for a maximum of 90 days.'),
  ('fi-specialist', 'general_valid_passport', 'You have a valid passport. When you apply for a residence permit, you must usually have a valid national passport.'),
  ('fi-specialist', 'general_no_entry_prohibition', 'You have not been prescribed a prohibition of entry.'),
  ('fi-specialist', 'general_public_order', 'You are not a danger to public order or security.'),
  ('fi-specialist', 'general_national_security', 'You are not a danger to national security.'),
  ('fi-specialist', 'general_public_health', 'You are not a danger to public health.'),
  ('fi-specialist', 'general_international_relations', 'You are not a danger to Finland’s international relations.'),
  ('gb-electronic-travel-authorisation-eta', 'eta_or_visa_required', 'Most visitors need an ETA or a visa. What you need depends on: your nationality ... why you’re coming to the UK, Jersey, Guernsey or the Isle of Man'),
  ('gb-electronic-travel-authorisation-eta', 'not_covered_by_an_exemption', 'You do not need an ETA to travel to the UK if: you’re a British or Irish citizen'),
  ('gb-electronic-travel-authorisation-eta', 'one_eta_per_traveller', 'Each person travelling needs an ETA, including babies and children.'),
  ('gb-electronic-travel-authorisation-eta', 'landside_transit_needs_eta', 'You need an ETA if you’re passing through border control at a UK airport before continuing your onward journey.'),
  ('gb-electronic-travel-authorisation-eta', 'dual_citizens_cannot_get_eta', 'If you’re a dual citizen with British or Irish citizenship, you cannot get an ETA.'),
  ('gb-electronic-travel-authorisation-eta', 'eta_scope_and_duration', '​​An electronic travel authorisation (ETA) lets you travel to the UK, Jersey, Guernsey or the Isle of Man for up to 6 months.'),
  ('gb-electronic-travel-authorisation-eta', 'eta_does_not_guarantee_entry', 'An ETA does not guarantee entry to the UK, Jersey, Guernsey or the Isle of Man.'),
  ('gb-electronic-travel-authorisation-eta', 'travel_passport', 'You’ll need: the passport you’ll travel with'),
  ('gb-electronic-travel-authorisation-eta', 'email_address', 'an email address'),
  ('gb-electronic-travel-authorisation-eta', 'payment_method', 'a credit card, debit card, Apple Pay or Google Pay'),
  ('gb-electronic-travel-authorisation-eta', 'face_photo', 'When you apply, you’ll need to upload or take photos of the face of the person applying.'),
  ('gb-electronic-travel-authorisation-eta', 'passport_and_face_photo_for_someone_else', 'If the person you’re applying for is not with you, you must apply for their ETA online. You’ll need a photo of their passport and a photo of their face.'),
  ('gb-electronic-travel-authorisation-eta', 'irish_residence_document', 'If you’re 16 or older, you’ll need to bring one of the following: Irish driving licence ... The document must be: an original ... issued by the Irish government ... valid at the time you travel'),
  ('gb-electronic-travel-authorisation-eta', 'apply_via_app_or_online', 'Apply on the UK ETA app You’ll need to use your phone’s camera to scan your passport and your face.'),
  ('gb-electronic-travel-authorisation-eta', 'wait_for_decision_before_travel', 'You must wait until you get an email confirming you have an ETA before you travel to the UK.'),
  ('gb-electronic-travel-authorisation-eta', 'eta_fee', 'It costs £20 to apply online or through the UK ETA app. You cannot get a refund after you apply.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'both_partners_18_or_over', 'To apply as a partner, you and your partner both need to be 18 or over.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'partner_immigration_status', 'Your partner must also either: be a British or Irish citizen'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'intend_to_live_together_permanently', 'You and your partner must intend to live together permanently in the UK after you apply.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'qualifying_relationship', 'You must be able to prove one of the following: you’re in a civil partnership or marriage that’s recognised in the UK'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'knowledge_of_english', 'You also need to prove you: have a good knowledge of English'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'financial_requirement', 'meet the financial requirements'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'fiance_marry_within_6_months', 'You must prove that: you plan to marry or become civil partners within 6 months of arriving in the UK ... any previous marriages or civil partnerships have ended'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'passport_or_travel_id', 'You’ll need to provide: all your names ... your date of birth ... your current passport or other valid travel ID'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'previous_passport_copies', 'copies of the photo page and any visa or entry stamps in your previous passports'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'previous_immigration_applications', 'details of any previous immigration applications you’ve made'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'criminal_convictions', 'details of any criminal convictions'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'national_insurance_number', 'your national insurance number, if you have one'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'parents_date_of_birth_and_nationality', 'your parents’ date of birth and nationality if you’re applying from outside the UK'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'tb_test_results', 'your tuberculosis test results if you’re from a country where you have to take the test'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'certified_translations', 'a certified translation of any document that is not in English or Welsh'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'proof_of_immigration_status', 'You’ll also need to provide either: online proof of your immigration status if you have an eVisa - you’ll need to get a share code ... your biometric residence permit (BRP) - you can use it for 24 months after the expiry date printed on your card or until 31 December 2026, whichever comes first'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'relationship_evidence', 'Send evidence that: comes from the government, a bank, landlord, utility provider, or a medical professional ... confirms your relationship with your partner - for example, that you live together, share expenses or are married or in a civil partnership ... is less than 4 years old'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'proof_of_income', 'You’ll need to provide proof of the income with your application.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'partner_details', 'If you have a partner, you’ll be asked about their: name ... date of birth ... nationality ... passport ... right to be in the UK, for example they’re a British citizen'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'children_details', 'You’ll need to give details of your children (and your partner’s children if you have one). You’ll be asked about all children, even if they’re not applying.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'life_outside_the_uk', 'You’ll need to give details of: countries outside the UK you’ve lived in and visited ... family and friends in the countries where you were born or have nationality'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'apply_online', 'Outside the UK You must apply online from outside the UK. In the UK You must apply online in the UK.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'email_address', 'You’ll need an email address to make an online application.'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'application_fee', 'Apply outside the UK Apply in the UK Cost if joining your partner, parent or child £2,064 £1,407 Cost for each dependant added to your application £2,064 each person £1,407 each person'),
  ('gb-family-visas-apply-extend-or-switch-apply-as-a-partner-or-spouse', 'healthcare_surcharge', 'For each adult (18 or older) it costs: £2,587.50 if you’re staying for 2 years and 6 months ... £3,105 if you’re staying for 2 years and 9 months ... £5,175 if you’re staying for 5 years ... For each child (under 18), it costs: £1,940 if you’re staying for 2 years and 6 months ... £2,328 if you’re staying for 2 years and 9 months ... £3,880 if you’re staying for 5 years'),
  ('gb-skilled-worker-visa', 'approved_uk_employer', 'You must have a job offer from an approved UK employer before you apply for a Skilled Worker visa. Approved employers are also known as sponsors, because they are sponsoring you to come to or stay in the UK.'),
  ('gb-skilled-worker-visa', 'certificate_of_sponsorship', 'have a ‘certificate of sponsorship’ (CoS) from your employer with information about the role you’ve been offered in the UK'),
  ('gb-skilled-worker-visa', 'eligible_occupation', 'You must meet all the following requirements to be eligible for a Skilled Worker visa: your job is eligible for this visa'),
  ('gb-skilled-worker-visa', 'minimum_salary', 'The minimum salary for the type of work you’ll be doing is whichever is the highest of: £41,700 per year ... the ‘going rate’ for the type of work you’ll be doing'),
  ('gb-skilled-worker-visa', 'knowledge_of_english', 'You must be able to speak, read, write and understand English. You’ll usually need to prove your knowledge of English when you apply.'),
  ('gb-skilled-worker-visa', 'personal_savings', 'You must have at least £1,270 in your bank account to show you can support yourself in the UK. You will need to have had the money available for at least 28 days in a row. Day 28 must be within 31 days of applying for this visa.'),
  ('gb-skilled-worker-visa', 'apply_within_3_months_of_cos', 'You must apply for your visa within 3 months of getting your certificate of sponsorship.'),
  ('gb-skilled-worker-visa', 'employer_cqc_registration_care_roles', 'Your employer must be registered with the Care Quality Commission if you’re a care worker (code 6135) or senior care worker (code 6136) working in England.'),
  ('gb-skilled-worker-visa', 'cos_reference_number', 'When you apply you’ll need to provide: your certificate of sponsorship reference number - your employer will give you this'),
  ('gb-skilled-worker-visa', 'proof_of_english', 'proof of your knowledge of English'),
  ('gb-skilled-worker-visa', 'valid_passport', 'a valid passport or other document that shows your identity and nationality'),
  ('gb-skilled-worker-visa', 'job_and_employer_details', 'your job title and annual salary ... your job’s occupation code ... the name of your employer and their sponsor licence number - this will be on your certificate of sponsorship'),
  ('gb-skilled-worker-visa', 'proof_of_personal_savings', 'Depending on your circumstances, you might be asked to provide: evidence that you have enough personal savings to support yourself in the UK, for example bank statements (unless your certificate of sponsorship shows your employer can support you)'),
  ('gb-skilled-worker-visa', 'proof_of_relationship_to_dependants', 'proof of your relationship with your partner or children if they’re applying with you'),
  ('gb-skilled-worker-visa', 'tb_test_results', 'your tuberculosis test results if you’re from a listed country'),
  ('gb-skilled-worker-visa', 'criminal_record_certificate', 'You’ll need to provide a criminal record certificate if you’re applying from outside the UK and you work in: education, for example teachers, education advisers and school inspectors, childminders, teaching assistants'),
  ('gb-skilled-worker-visa', 'atas_certificate', 'a valid ATAS certificate if your employer tells you that you need one because your job involves researching a sensitive subject at PhD level or higher'),
  ('gb-skilled-worker-visa', 'phd_certificate_or_ecctis_reference', 'your UK PhD certificate, or your unique Ecctis reference number if your qualification is from outside the UK - you’ll need to apply through Ecctis'),
  ('gb-skilled-worker-visa', 'certified_translations', 'If your documents are not in English or Welsh you’ll also need to provide a certified translation.'),
  ('gb-skilled-worker-visa', 'apply_online', 'You must apply online for a Skilled Worker visa.'),
  ('gb-skilled-worker-visa', 'prove_your_identity', 'As part of your application, you’ll need to prove your identity. How you do this depends on where you’re from and what type of passport you have.'),
  ('gb-skilled-worker-visa', 'application_fee', 'If you’re applying from outside the UK, the standard fee depends on whether you’ll be in the UK for: up to 3 years - £819 per person ... more than 3 years - £1,618 per person ... If you’re applying from inside the UK to extend, switch or update your visa, the standard fee depends on whether you’ll be in the UK for: up to 3 years - £943 per person ... more than 3 years - £1,865 per person ... The fee for each person applying is: £628 if you’re staying for up to 3 years ... £1,235 if you’re staying for more than 3 years'),
  ('gb-skilled-worker-visa', 'healthcare_surcharge', 'pay the healthcare surcharge - this is usually £1,035 per year'),
  ('gb-standard-visitor-visa-visit-on-business', 'business_activities_not_paid_by_uk_source', 'You can visit the UK as a Standard Visitor for up to 6 months: to do certain business activities, if you are not paid by a UK-based organisation or client'),
  ('gb-standard-visitor-visa-visit-on-business', 'permitted_business_activities', 'You can visit the UK as a Standard Visitor to do the following business activities if you’re not paid by a UK-based organisation or client: attend interviews, meetings, conferences and seminars'),
  ('gb-standard-visitor-visa-visit-on-business', 'no_other_paid_or_unpaid_work', 'You’ll need to apply for a work visa if you want to do any other paid or unpaid work in the UK.'),
  ('gb-standard-visitor-visa-visit-on-business', 'permitted_paid_engagement', 'if you are visiting as an expert in your profession to do a permitted paid engagement'),
  ('gb-standard-visitor-visa-visit-on-business', 'overseas_job_role_activities', 'You can do certain additional activities in the UK as a Standard Visitor, if you’re employed overseas as: an archaeologist'),
  ('gb-standard-visitor-visa-visit-on-business', 'passport_valid_whole_stay', 'You must have a passport or travel document that is valid for the whole of your stay in the UK.'),
  ('gb-standard-visitor-visa-visit-on-business', 'circumstantial_application_details', 'Depending on your circumstances, you might also need to provide: details of your travel history for the past 10 years'),
  ('gb-standard-visitor-visa-visit-on-business', 'tb_test_certificate', 'a certificate proving that you’ve had a tuberculosis (TB) test if you’re visiting for more than 6 months'),
  ('gb-standard-visitor-visa-visit-on-business', 'certified_translations', 'You must provide certified translations of any documents that are not in English or Welsh.'),
  ('gb-standard-visitor-visa-visit-on-business', 'check_eligibility_and_visa_need', 'You should: check you meet the basic eligibility requirements for a Standard Visitor ... check if you need a visa to visit the UK ... apply for a Standard Visitor visa online - if you need one'),
  ('gb-standard-visitor-visa-visit-on-business', 'apply_online', 'If you need a Standard Visitor visa, you must apply online before you travel to the UK and attend an appointment at a visa application centre. The earliest you can apply is 3 months before you travel.'),
  ('gb-standard-visitor-visa-visit-on-business', 'online_application_information', 'You’ll need to provide the following information in your online application: the dates you’re planning to travel to the UK'),
  ('gb-standard-visitor-visa-visit-on-business', 'biometrics_appointment', 'At your appointment, you’ll need to: prove your identity with your passport or travel document ... have your fingerprints and a photo (biometric information) taken ... provide the required documents that show you’re eligible for a Standard Visitor visa'),
  ('gb-standard-visitor-visa-visit-on-business', 'standard_visitor_visa_fee', 'Fee Maximum length of stay Standard Visitor visa £135 6 months Standard Visitor visa for medical reasons £234 11 months Standard Visitor visa for academics £234 12 months 2 year long-term Standard Visitor visa £506 6 months per visit 5 year long-term Standard Visitor visa £903 6 months per visit 10 year long-term Standard Visitor visa £1,128 6 months per visit'),
  ('gb-standard-visitor-visa', 'valid_travel_document', 'You must have a passport or travel document to enter the UK. It should be valid for the whole of your stay.'),
  ('gb-standard-visitor-visa', 'will_leave_uk', 'You must be able to show that: you’ll leave the UK at the end of your visit'),
  ('gb-standard-visitor-visa', 'support_self_and_dependants', 'you’re able to support yourself and your dependants during your trip (or have funding from someone else to support you)'),
  ('gb-standard-visitor-visa', 'funds_for_return_journey', 'you’re able to pay for your return or onward journey (or have funding from someone else to pay for the journey)'),
  ('gb-standard-visitor-visa', 'no_residence_by_frequent_visits', 'you’ll not live in the UK for extended periods through frequent or successive visits, or make the UK your main home'),
  ('gb-standard-visitor-visa', 'permitted_activities_only', 'You cannot: do paid or unpaid work for a UK company or as a self-employed person, unless you’re doing a permitted paid engagement or event'),
  ('gb-standard-visitor-visa', 'maximum_stay_six_months', 'You can usually stay in the UK for up to 6 months. You might be able to apply to stay for longer in certain circumstances, for example to get medical treatment.'),
  ('gb-standard-visitor-visa', 'passport_valid_whole_stay', 'You must have a passport or travel document that is valid for the whole of your stay in the UK.'),
  ('gb-standard-visitor-visa', 'circumstantial_application_details', 'Depending on your circumstances, you might also need to provide: details of your travel history for the past 10 years'),
  ('gb-standard-visitor-visa', 'tb_test_certificate', 'a certificate proving that you’ve had a tuberculosis (TB) test if you’re visiting for more than 6 months'),
  ('gb-standard-visitor-visa', 'additional_documents_by_visit_purpose', 'You need to provide additional documents if you’re visiting the UK: to study ... as an academic ... for certain paid engagements or events (a ‘permitted paid engagement’ ... for medical reasons'),
  ('gb-standard-visitor-visa', 'certified_translations', 'You must provide certified translations of any documents that are not in English or Welsh.'),
  ('gb-standard-visitor-visa', 'apply_online', 'If you need a Standard Visitor visa, you must apply online before you travel to the UK and attend an appointment at a visa application centre. The earliest you can apply is 3 months before you travel.'),
  ('gb-standard-visitor-visa', 'online_application_information', 'You’ll need to provide the following information in your online application: the dates you’re planning to travel to the UK'),
  ('gb-standard-visitor-visa', 'biometrics_appointment', 'At your appointment, you’ll need to: prove your identity with your passport or travel document ... have your fingerprints and a photo (biometric information) taken ... provide the required documents that show you’re eligible for a Standard Visitor visa'),
  ('gb-standard-visitor-visa', 'standard_visitor_visa_fee', 'Fee Maximum length of stay Standard Visitor visa £135 6 months Standard Visitor visa for medical reasons £234 11 months Standard Visitor visa for academics £234 12 months 2 year long-term Standard Visitor visa £506 6 months per visit 5 year long-term Standard Visitor visa £903 6 months per visit 10 year long-term Standard Visitor visa £1,128 6 months per visit'),
  ('gb-student-visa', 'age_16_or_over', 'You can apply for a Student visa to study in the UK if you’re 16 or over and you:'),
  ('gb-student-visa', 'offer_from_licensed_sponsor', 'You must have an unconditional offer of a place on a course with a licensed student sponsor.'),
  ('gb-student-visa', 'enough_money', 'have enough money to support yourself and pay for your course - the amount will vary depending on your circumstances'),
  ('gb-student-visa', 'knowledge_of_english', 'can speak, read, write and understand English'),
  ('gb-student-visa', 'parental_consent_16_or_17', 'have consent from your parents if you’re 16 or 17 - you’ll need evidence of this when you apply'),
  ('gb-student-visa', 'eligible_course_type', 'You can do one of the following courses: a full-time course leading to a qualification that’s below degree level (RQF level 3, 4 or 5) with at least 15 hours a week of organised daytime study'),
  ('gb-student-visa', 'apply_within_6_months_of_cas', 'You must apply for your visa within 6 months of receiving your CAS.'),
  ('gb-student-visa', 'application_timing', 'Applying from outside the UK The earliest you can apply for a visa is 6 months before you start your course.'),
  ('gb-student-visa', 'passport', 'When you apply for your Student visa you must provide: a current passport or other valid travel documentation'),
  ('gb-student-visa', 'confirmation_of_acceptance_for_studies', 'a Confirmation of Acceptance for Studies (CAS) from your course provider'),
  ('gb-student-visa', 'proof_of_funds', 'You may also need to provide: proof you have enough money to support yourself and pay for your course - this will vary depending on your circumstances'),
  ('gb-student-visa', 'atas_certificate', 'a valid ATAS certificate if your course and nationality require it'),
  ('gb-student-visa', 'parental_consent_evidence', 'If you’re under 18 you’ll need written consent from both parents or legal guardians (or one parent if they have sole responsibility).'),
  ('gb-student-visa', 'proof_of_relationship_to_parent', 'proof of your relationship to your parent or guardian if you’re under 18'),
  ('gb-student-visa', 'tb_test_results', 'your tuberculosis test results'),
  ('gb-student-visa', 'financial_sponsor_consent', 'written consent for your application from your financial sponsor if you’ve received sponsorship for your course fees and living costs in the last 12 months'),
  ('gb-student-visa', 'apply_online', 'You must apply online for a Student visa.'),
  ('gb-student-visa', 'prove_your_identity', 'As part of your application, you’ll need to prove your identity. How you do this depends on where you’re from and what type of passport you have.'),
  ('gb-student-visa', 'student_visa_fee', 'It costs: £558 to apply for a Student visa from outside the UK ... £558 to extend or switch to a Student visa from inside the UK ... You must pay the visa fee for each person that joins you.'),
  ('gb-student-visa', 'healthcare_surcharge', 'You’ll also have to pay the healthcare surcharge as part of your application. How much you pay depends on how long your visa lasts.'),
  ('gb-youth-mobility-scheme', 'age_band_18_to_35', 'You can apply for the visa if you’re aged 18 to 35 and from: Australia Canada New Zealand South Korea You must be aged 18 or over when your visa starts, or 35 or under when you apply for it. You can apply for your visa before you turn 18 and you can be over 35 when it starts.'),
  ('gb-youth-mobility-scheme', 'age_band_18_to_30', 'You can apply for the visa if you’re aged 18 to 30 and from: Andorra Iceland Japan Monaco San Marino Uruguay'),
  ('gb-youth-mobility-scheme', 'british_national_categories', 'You can also apply if you’re aged 18 to 30 and you’re a: British overseas citizen British overseas territories citizen British national (overseas) You must be aged 18 or over when your visa starts, or 30 or under when you apply for it.'),
  ('gb-youth-mobility-scheme', 'ballot_required_hong_kong_taiwan', 'You must be selected in the Youth Mobility Scheme ballot before you can apply for your visa if you’re from: Hong Kong, if you have an SAR passport Taiwan'),
  ('gb-youth-mobility-scheme', 'children_bar', 'You cannot apply if you have: children under the age of 18 who live with you children you’re financially responsible for already been in the UK under the scheme'),
  ('gb-youth-mobility-scheme', 'india_different_scheme', 'If you’re from India There’s a different scheme for Indian nationals. Check if you’re eligible for the India Young Professionals Scheme visa.'),
  ('gb-youth-mobility-scheme', 'savings_2530_held_28_days', 'You must have at least £2,530 in your bank account to show you can support yourself in the UK. You will need to have had the money available for at least 28 days in a row. Day 28 must be within 31 days of applying for this visa.'),
  ('gb-youth-mobility-scheme', 'passport_or_identity_document', 'When you apply you’ll need to provide: a valid passport or other document that shows your identity and nationality a bank statement showing you have at least £2,530 in savings'),
  ('gb-youth-mobility-scheme', 'tuberculosis_test', 'your tuberculosis (TB) test results if you’re from a country where you have to take the test'),
  ('gb-youth-mobility-scheme', 'certified_translations', 'You’ll need to provide a certified translation of any documents that are not in English or Welsh.'),
  ('gb-youth-mobility-scheme', 'criminal_record_certificate_by_nationality', 'If you’re from Andorra You must provide an Andorran certificate of criminal records. It must have been issued less than 6 months before you apply for the Youth Mobility Scheme visa.'),
  ('gb-youth-mobility-scheme', 'san_marino_suitability_letter', 'If you’re from San Marino You must provide a letter from the Directorate of Political and Diplomatic Affairs of the Republic of San Marino Department of Foreign Affairs. The letter must: confirm that you’re suitable for the Youth Mobility Scheme have been issued less than 6 months before you apply for the Youth Mobility Scheme visa'),
  ('gb-youth-mobility-scheme', 'ballot_confirmation_email', 'If you’re from Hong Kong or Taiwan You must provide a valid email from the Home Office confirming you were successful in the Youth Mobility Scheme ballot.'),
  ('gb-youth-mobility-scheme', 'application_fee', 'Application fee The application fee is £340.'),
  ('gb-youth-mobility-scheme', 'healthcare_surcharge', 'pay the healthcare surcharge, which is usually £776 per year'),
  ('gb-youth-mobility-scheme', 'apply_no_earlier_than_six_months', 'The earliest you can apply for a visa is 6 months before you travel.'),
  ('gb-youth-mobility-scheme', 'decision_time', 'Once you’ve applied online, proved your identity and provided your documents, you’ll usually get a decision on your visa within 3 weeks.'),
  ('gb-youth-mobility-scheme', 'stay_24_months', 'You’ll be given a visa to live and work in the UK for up to 24 months. You can enter the UK at any time while your visa is valid, and leave and come back at any time during your stay. If you turn 31 after your visa is issued, you can stay in the UK for as long as your visa is valid.'),
  ('gb-youth-mobility-scheme', 'self_employment_limits', 'be self-employed and set up a company - as long as your premises are rented, your equipment is not worth more than £5,000 and you do not have any employees'),
  ('gb-youth-mobility-scheme', 'prohibited_activities', 'You cannot: work as a professional sportsperson (for example as a coach) extend your stay unless you’re from Australia, Canada or New Zealand get public funds bring in family members on your application - they must apply separately'),
  ('hk-general-employment-policy', 'discretion_reserved', 'All applications are processed and determined by the ImmD. Approval of applications is entirely discretionary and is subject to changes in government policies. The Director of Immigration reserves absolute discretion to refuse any application even if the application meets all eligibility criteria.'),
  ('hk-general-employment-policy', 'no_security_objection', 'there is no security objection and no known record of serious crime in respect of the applicant;'),
  ('hk-general-employment-policy', 'good_education_background', 'the applicant has a good education background, normally a first degree in the relevant field, but in special circumstances, good technical qualifications, proven professional abilities and/or relevant experience and achievements supported by documentary evidence may also be accepted;'),
  ('hk-general-employment-policy', 'genuine_job_vacancy', 'there is a genuine job vacancy;'),
  ('hk-general-employment-policy', 'offer_relevant_and_not_locally_available', 'the applicant has a confirmed offer of employment and is employed in a job relevant to his academic qualifications or work experience that cannot be readily taken up by the local work force; and'),
  ('hk-general-employment-policy', 'market_rate_remuneration', 'the remuneration package including income, accommodation, medical and other fringe benefits is broadly commensurate with the prevailing market level for professionals in the HKSAR.'),
  ('hk-general-employment-policy', 'quota_free_non_sector_specific', 'The GEP is quota-free and non-sector specific.'),
  ('hk-general-employment-policy', 'mainland_residents_excluded', 'This entry arrangement does not apply to: ... Chinese residents of the Mainland'),
  ('hk-general-employment-policy', 'excluded_nationalities', 'nationals of Afghanistan, Cuba and Korea (Democratic People''s Republic of).'),
  ('hk-general-employment-policy', 'normal_immigration_requirements', 'an applicant should meet normal immigration requirements (such as holding a valid travel document with adequate returnability to his/her country of residence or citizenship; be of clear criminal record and raise no security or criminal concerns to the HKSAR; have no likelihood of becoming a burden on the HKSAR, etc.) as well as the relevant specific eligibility criteria detailed above'),
  ('hk-general-employment-policy', 'overseas_chinese_prc_passport_facilitation', 'the applicant has permanent residence overseas; or ... the applicant has been residing overseas for at least one year immediately before the submission of application'),
  ('hk-general-employment-policy', 'dependants_partnership_recognition', 'Applicants admitted or seeking admission under the GEP may apply to bring their spouse or the other party to a same-sex civil partnership, same-sex civil union, “same-sex marriage”, opposite-sex civil partnership or opposite-sex civil union entered into by him/her in accordance with the local law in force of the place of celebration and with such status being legally and officially recognised by the local authorities of the place of celebration'),
  ('hk-general-employment-policy', 'partnership_definition_and_exclusions', 'Such relationships do not include de facto spouse, partners in cohabitation, fianc&eacute;/fianc&eacute;e, etc.'),
  ('hk-general-employment-policy', 'dependant_sponsorship_criteria', 'there is reasonable proof of a genuine relationship between the dependant and the sponsor; ... the sponsor is able to support the dependant''s living at a standard well above the subsistence level and provide him/her with suitable accommodation in the HKSAR.'),
  ('hk-general-employment-policy', 'dependant_stay_linked_to_sponsor', 'The length of stay of such dependants will normally be linked to that of their sponsors. Any subsequent applications for extension of stay will be considered only when the applicant continues to meet the eligibility criteria for entry for residence as dependants (including that there is no change in circumstances which would have otherwise resulted in loss of sponsorship for the applicant, e.g. change in marriage relationship between the dependent spouse and the sponsor, or death of sponsor) and the sponsor remains a bona fide Hong Kong resident living in the HKSAR.'),
  ('hk-general-employment-policy', 'dependants_may_work_or_study', 'These dependants are not prohibited from taking up employment or studies in the HKSAR under the existing policy.'),
  ('hk-general-employment-policy', 'processing_four_weeks', 'For applications submitted under the GEP, it normally takes four weeks upon receipt of all the required documents and the relevant application fee. The Immigration Department (hereafter “ImmD”) will not be able to start processing the application unless all the required documents and the relevant application fee have been received.'),
  ('hk-general-employment-policy', 'application_fee_non_refundable', 'The application fee paid is non-refundable in any circumstance irrespective of the application result.'),
  ('hk-general-employment-policy', 'evisa_only', 'A visa/entry permit (in the form of “e-Visa”) will be issued upon successful application.'),
  ('hk-quality-migrant-admission-scheme', 'no_job_offer_required', 'Applicants are not required to have secured an offer of local employment before applying for entry or being admitted to Hong Kong for settlement under the Scheme.'),
  ('hk-quality-migrant-admission-scheme', 'four_stage_selection', 'Stage 1: Prerequisites ... Stage 2: Assessment Routes ... Stage 3: Selection exercise ... Stage 4: Issuance of visa/entry permit'),
  ('hk-quality-migrant-admission-scheme', 'prerequisites_are_pass_fail', 'If the applicant fails to provide satisfactory supporting documents showing that he/she has met all the above prerequisites, his/her application will not be further processed and will be refused immediately.'),
  ('hk-quality-migrant-admission-scheme', 'age_18_or_above', 'The applicant must be aged 18 or above when submitting an application under the Scheme.'),
  ('hk-quality-migrant-admission-scheme', 'self_funding_no_public_assistance', 'The applicant must be able to demonstrate that he/she is capable of supporting and accommodating himself/herself and his/her dependant(s), if any, on his/her own financial resources without relying on public assistance during his/her stay in Hong Kong.'),
  ('hk-quality-migrant-admission-scheme', 'good_character', 'The applicant must not have any criminal record or adverse immigration record in Hong Kong or elsewhere.'),
  ('hk-quality-migrant-admission-scheme', 'basic_academic_qualifications', 'The applicant must have a good educational background, normally a first degree from a recognized university or tertiary educational institution. Under special circumstances, good technical qualifications, proven professional abilities, and/or experience and achievements supported by documentary evidence may be considered.'),
  ('hk-quality-migrant-admission-scheme', 'two_assessment_routes', 'Applicants who have met all the prerequisites may choose to be assessed either under the General Points Test or the Achievement-based Points Test. There are 12 assessment criteria under the General Points Test and two assessment criteria under the Achievement-based Points Test.'),
  ('hk-quality-migrant-admission-scheme', 'passing_threshold_is_not_approval', 'In general, not all applications meeting both the prerequisites and the passing threshold will necessarily be approved and applications meeting more assessment criteria will be considered more favourably.'),
  ('hk-quality-migrant-admission-scheme', 'merit_based_selection_panel', 'The Assessment Panel will take a holistic view of the manpower requirements in different sectors and industries, socio-economic needs of Hong Kong, the background and credentials of applicants, and other relevant factors and advise the Director of Immigration on the applicants’ suitability.'),
  ('hk-quality-migrant-admission-scheme', 'absolute_discretion_no_reason', 'The Director of Immigration has absolute discretion to determine whether applicants have fulfilled any assessment criterion under the two assessment routes of the Scheme as the Director thinks fit and to approve or refuse any application without giving any reason.'),
  ('hk-quality-migrant-admission-scheme', 'excluded_nationalities', 'The Scheme is not applicable to nationals of Afghanistan, Cuba and Korea (Democratic People''s Republic of).'),
  ('hk-quality-migrant-admission-scheme', 'dependants_spouse_partner_children', 'Successful applicants under the Scheme may bring their spouse or the other party to a same-sex civil partnership, same-sex civil union, “same-sex marriage”, opposite-sex civil partnership or opposite-sex civil union entered into by him/her in accordance with the local law in force of the place of celebration and with such status being legally and officially recognised by the local authorities of the place of celebration Note and unmarried dependent children under the age of 18 to Hong Kong, provided that they are capable of supporting and accommodating their dependants on their own financial resources without relying on public assistance in Hong Kong.'),
  ('hk-quality-migrant-admission-scheme', 'partnership_exclusions', 'Such relationships do not include de facto spouse, partners in cohabitation, fianc&eacute;/fianc&eacute;e, etc.'),
  ('hk-quality-migrant-admission-scheme', 'declare_dependants_in_application', 'Applicants under the Scheme are advised to fill in the part of accompanying dependant for all accompanying family members during the online application process.'),
  ('hk-quality-migrant-admission-scheme', 'false_statement_offence', 'Any person who knowingly and wilfully makes a statement or gives information which he/she knows to be false or does not believe to be true under or for the purpose of the Scheme shall be guilty of an offence under the Laws of Hong Kong and is liable to prosecution and subsequent removal from Hong Kong.'),
  ('hk-quality-migrant-admission-scheme', 'initial_stay_36_months', 'Persons admitted through the General Points Test under the Scheme will normally be granted an initial stay of 36 months on time limitation only without other conditions of stay upon entry.'),
  ('hk-quality-migrant-admission-scheme', 'originals_on_request', 'Notwithstanding that applicants have already furnished all necessary copies of documents and information stated in the Guidance Notes, they may still be required to submit originals of the documents in connection with their applications upon request.'),
  ('hk-quality-migrant-admission-scheme', 'application_fee_non_refundable', 'The application fee paid is non-refundable in any circumstance irrespective of the application result.'),
  ('ie-family-reunification-non-eea', 'separate_application_per_category', 'Different family members can apply to join an Irish national, including spouse, civil partner, de facto partner, minor child, dependent parent and dependent adult child (Only where they are dependent on the care of the parent sponsor for their subsistence due to a serious medical or psychological condition that makes independent life unsustainable). There is a separate application for each category of applicant and different conditions will apply.'),
  ('ie-family-reunification-non-eea', 'non_nuclear_family_generally_ineligible', 'If you are not a nuclear family member, dependent parent or dependent adult child of an Irish national you will generally not be eligible for family reunification. However, you may apply where exceptional circumstances arise, see Section 13 of the Policy document.'),
  ('ie-family-reunification-non-eea', 'dependent_adult_child_condition', 'If you are the adult child over the age of 18 of an Irish national parent and you are dependent on the care of that parent for your subsistence due to a serious medical or psychological condition that makes independent life unsustainable, please note there are additional qualifying conditions and there is a higher minimum financial threshold.'),
  ('ie-family-reunification-non-eea', 'sponsor_assumes_full_financial_responsibility', 'The sponsor must assume full financial responsibility for the family member they are seeking to bring to reside in Ireland with them. The State does not have an obligation to subsidise the family concerned and the sponsor must show evidence that they can provide for their family members if they are permitted to enter and reside in Ireland.'),
  ('ie-family-reunification-non-eea', 'no_state_support_reliance_two_years', 'All sponsors must not have been mainly reliant on State supports from the Irish State for a continuous period of two years or longer immediately prior to application.'),
  ('ie-family-reunification-non-eea', 'one_sponsor_income_only', 'only the income of one sponsor will be considered, so you cannot combine your salary with that of your spouse, partner or any other family member to reach these thresholds.'),
  ('ie-family-reunification-non-eea', 'category_a_spouse_threshold', 'Category A sponsors (e.g. Irish citizens) must have earned a gross income over and above any State benefits of not less than €75,000, cumulative, over the three-year period prior to application (e.g. €25,000 per year over three years), with the expectation that this level of income will be maintained.'),
  ('ie-family-reunification-non-eea', 'category_c_spouse_threshold', 'Category C sponsors (e.g. General Employment Permit holder) must have a gross income in excess of €30,000 in the previous year, with the expectation that this level of income will be maintained.'),
  ('ie-family-reunification-non-eea', 'category_b_no_published_figure', 'For Category B sponsors (e.g. Critical Skills Employment Permit holder or researcher), the immigration status granted assumes certain levels of income either immediately or in the future or on the basis that the sponsor falls into a category whose migration to Ireland is promoted as part of Government policy.'),
  ('ie-family-reunification-non-eea', 'minor_children_thresholds_category_c', 'Number of Children Minimum Annual Net Salary Required (2026)[1] Indicative Annual Gross Salary Equivalent (2026) 1 Child €39,780 €50,200 2 Children €45,032 €60,200 3 Children €50,284 €70,100 4 Children €55,016 €80,000 5 Children €61,568 €93,700 6 Children €67,600 €106,300 7 Children €74,672 €121,100 8+ Children €79,664 €131,600'),
  ('ie-family-reunification-non-eea', 'dependent_adult_relative_thresholds', 'Number of Dependent Adult Relatives Minimum Annual Gross Salary Required (2026)[2] 1 Adult €96,929 2 Adults €130,985 3 Adults €165,042'),
  ('ie-family-reunification-non-eea', 'sponsor_categories', 'Category A: Irish nationals Category B: Critical Skills Employment Permit (CSEP) holders, Intra-company transferees, Full-time non-locum doctors in employment, Researchers on Hosting Agreements, Investors on the Immigrant Investor Programme (IIP), Entrepreneurs on the Start-up Entrepreneur Programme (STEP), ISD-approved scholarship programme students (e.g. KASP), PhD student permission holders (subject to additional conditions), Ministers of Religion under the relevant scheme (subject to additional conditions).'),
  ('ie-long-stay-employment-visa', 'employment_permit_first', 'If you wish to work in Ireland, you need to have an Employment Permit. This permit is issued by the Department of Enterprise, Trade and Employment (DETE).'),
  ('ie-long-stay-employment-visa', 'permit_makes_you_eligible', 'Once you have received a permit, you are eligible to apply for an Employment Visa.'),
  ('ie-long-stay-employment-visa', 'apply_from_home_or_legal_residence', 'You must apply from your home country or where you are a legal resident.'),
  ('ie-long-stay-employment-visa', 'apply_up_to_3_months_ahead', 'You should apply for a long stay employment visa up to 3 months before your date of travel to Ireland.'),
  ('ie-long-stay-employment-visa', 'avats_online_application', 'Use the Automated Visa Application and Tracking System (AVATS) to apply for your visa online'),
  ('ie-long-stay-employment-visa', 'submit_documents_within_30_days', 'You must do this within 30 days of creating an online application via AVATS. We will not process your application until we receive everything.'),
  ('ie-long-stay-employment-visa', 'originals_not_photocopies', 'Original documents must be provided. We do not accept photocopies except where stated.'),
  ('ie-long-stay-employment-visa', 'certified_translation', 'If you want to submit a document that is not in English or Irish, it must be accompanied by a full certified translation.'),
  ('ie-long-stay-employment-visa', 'business_letters_headed_paper', 'All letters submitted from a business, company or organisation must be original and on official headed paper. This is to make sure that they can be verified.'),
  ('ie-long-stay-employment-visa', 'no_digital_media', 'Do not submit documentation on USB sticks, memory cards, CD ROMs as documents on these devices cannot be accessed.'),
  ('ie-long-stay-employment-visa', 'no_false_information', 'NOTE: Do not include false or misleading information or documents in your application. If you do, your application may be refused. In some circumstances, you may not be allowed to appeal the visa decision and may be blocked from getting an Irish visa for 5 years.'),
  ('ie-long-stay-employment-visa', 'passport', 'Send us your current passport. This must be valid for at least twelve months after the date you plan to arrive in Ireland.'),
  ('ie-long-stay-employment-visa', 'passport_photographs', 'Include two passport-sized colour photographs with your application. These must not be more than 6 months old.'),
  ('ie-long-stay-employment-visa', 'application_letter', 'Type or write a letter explaining why you want to come to Ireland. Sign and date the letter and submit it with your documents.'),
  ('ie-long-stay-employment-visa', 'employment_permit_document', 'You must supply one of the following: Critical Skills Employment Permit General Employment Permit Intra-Company Transfer Employment Permit Contract for Services Employment Permit Exchange Agreement Employment Permit Internship Employment Permit Sports & Cultural Employment Permit.'),
  ('ie-long-stay-employment-visa', 'contract_of_employment', 'If you have an Employment Contract please submit it. If you do not please submit a letter from your employer.'),
  ('ie-long-stay-employment-visa', 'employer_letter', 'The letter should include: Details of your new job The salary you will be paid Details of the accommodation, if the employer is providing you with accommodation.'),
  ('ie-long-stay-employment-visa', 'evidence_of_qualifications', 'Evidence of qualifications and previous work experience must be submitted in support of the visa application.'),
  ('ie-long-stay-employment-visa', 'finances_bank_statement', 'You must provide an up-to-date bank statement, showing what money has been paid into and out of the account over the last six months, and showing sufficient funds to cover your costs. Bank statements must be on headed paper – internet printouts will not be accepted.'),
  ('ie-long-stay-employment-visa', 'disclose_visa_refusals', 'For all visa or preclearance applications, if you have been refused a visa or preclearance in the past for any country, you must provide details to us. The original letter issued to you by the authorities of that country must be provided with your application. Not disclosing any previous visa refusals will result in your application being refused.'),
  ('ie-long-stay-employment-visa', 'insurance_at_port_of_entry', 'Evidence of medical or travel insurance does not need to be provided with your application. However, the Visa Officer may request it before they make a decision on your application.'),
  ('ie-long-stay-employment-visa', 'visa_fee', 'The fees for visas are: Single entry: €60 Multi entry: €100 Transit: €25'),
  ('ie-long-stay-employment-visa', 'do_not_book_travel', 'You are advised not to purchase travel tickets before you know the outcome of your visa application.'),
  ('ie-long-term-study-visa', 'study_longer_than_3_months', 'If you wish to come to Ireland to study for more than 3 months, you need to apply for a long term study visa.'),
  ('ie-long-term-study-visa', 'meet_study_policy', 'You should first read our Policy on Non-EEA Nationals studying in Ireland. You must make that you meet the policy requirements before you make your visa application.'),
  ('ie-long-term-study-visa', 'apply_up_to_3_months_before', 'You should apply for a long term study visa up to 3 months before your date of travel to Ireland.'),
  ('ie-long-term-study-visa', 'apply_from_home_or_residence', 'You must apply from your home country or where you are a legal resident.'),
  ('ie-long-term-study-visa', 'transit_visa_before_applying', 'If you are visiting another state prior to travelling to Ireland, you must have the relevant visa for that state in your passport before applying for an Irish visa.'),
  ('ie-long-term-study-visa', 'avats_online_application', 'Use the Automated Visa Application and Tracking System (AVATS) to apply for your visa online'),
  ('ie-long-term-study-visa', 'passport_valid_12_months', 'Send us your current passport. This must be valid for at least twelve months after the date you plan to arrive in Ireland.'),
  ('ie-long-term-study-visa', 'previous_passports', 'Include a photocopy of each page from all previous passports, if availa'),
  ('ie-long-term-study-visa', 'passport_photographs', 'Include two passport-sized colour photographs with your application. These must not be more than 6 months old. On the back of each photo: Sign your name in your own handwriting and language Write your Visa Application Transaction Number from AVATS'),
  ('ie-long-term-study-visa', 'course_fees_paid', 'Note: Where the course fees are less than €6,000, you must pay fees in full to the college before to applying for your visa. Where the course fees are more than €6,000, you must pay at least this amount before applying for your visa. Evidence of this should be visible in your Letter of Acceptance. This minimum amount is an immigration requirement.'),
  ('ie-long-term-study-visa', 'electronic_transfer_evidence', 'You must provide a copy of an Electronic Transfer of Funds (ETF) to the Irish bank account of the college. This must show: the beneficiary college’s name, address and bank details your name, address and bank details'),
  ('ie-long-term-study-visa', 'sufficient_funds', 'You must show that you have enough funds to support your stay in Ireland. This should be achieved without the need to access public funds or rely on casual employment.'),
  ('ie-long-term-study-visa', 'summary_of_finances_form', 'All applicants for long stay Irish study visas must complete this form.'),
  ('ie-long-term-study-visa', 'private_medical_insurance', 'Private Medical Insurance cover is required. Your college may arrange this on your behalf. If so, your Letter of Acceptance from the college must include details of this. If it is not arranged by the college, you must organise this yourself. You must provide evidence of this with your application.'),
  ('ie-long-term-study-visa', 'academic_ability', 'You must provide evidence that you have the ability to follow your chosen course. Examples of this are previous exam results or qualifications.'),
  ('ie-long-term-study-visa', 'employment_history', 'You must give full details of your employment history. We need this to see where you have filled any gaps in your education with periods of employment.'),
  ('ie-long-term-study-visa', 'previous_visa_refusals', 'If you have been refused a visa in the past for any country, you must provide the details in your current application.'),
  ('ie-short-stay-business-visa', 'stay_90_days_business', 'A short stay ‘C’ business visa allows you to travel to Ireland for up to 90 days for activities related to your job, including to: Attend meetings Negotiate or sign agreements or contracts Work for 14 days or less.'),
  ('ie-short-stay-business-visa', 'no_work_15_days_or_longer', 'Work in any way (paid or unpaid) for 15 days or longer'),
  ('ie-short-stay-business-visa', 'no_public_services', 'Rely on Irish public services, for example public hospitals.'),
  ('ie-short-stay-business-visa', 'work_within_single_14_day_period', 'You should apply for a business visa if your work in Ireland starts and ends within a single 14 day period (2 calendar weeks).'),
  ('ie-short-stay-business-visa', 'cannot_work_more_than_once_in_90_days', 'You cannot work more than once during the 90 day period'),
  ('ie-short-stay-business-visa', 'visa_is_not_permission_to_enter', 'A visa allows you to travel to Ireland only. It does not give you permission to enter the country or to stay here. An immigration officer at border control can refuse you entry even if you have a visa.'),
  ('ie-short-stay-business-visa', 'one_application_per_traveller', 'Each traveller must apply for a separate visa.'),
  ('ie-short-stay-business-visa', 'avats_online_application', 'Create your visa application online'),
  ('ie-short-stay-business-visa', 'passport_valid_6_months', 'Your current passport must be valid for at least 6 months after the date you plan to leave Ireland.'),
  ('ie-short-stay-business-visa', 'previous_passports', 'A photocopy of each page from all previous passports you have (where available).'),
  ('ie-short-stay-business-visa', 'passport_photographs', 'Include 2 passport-sized colour photographs of the visa applicant. On the back of each photo: Sign your name (in your native script and language) Write your Visa Application Transaction Number from AVATS'),
  ('ie-short-stay-business-visa', 'third_country_travel_letter', 'Include a letter that describes your travel plan to-or-from Ireland if you intend to: Travel to Ireland directly from a country that is not your home country, or a country where you are a legal resident Or travel from Ireland directly to a different country'),
  ('ie-short-stay-business-visa', 'residence_permission_if_not_citizen', 'If you are not a citizen of the country you are applying from you must submit proof that you have permission to be in that country, for example a photocopy of your residence card. You must also show you have at least 3 months’ permission to remain in that country after the date you plan to leave Ireland.'),
  ('ie-short-stay-business-visa', 'finances_no_minimum', 'There is no minimum amount of finance for approving or refusing a visa application. The visa officer will decide if you have enough based on your own circumstances.'),
  ('ie-short-stay-business-visa', 'bank_statement', 'An up-to-date bank statement, it must be original and on headed bank paper. Note: You may use a printed internet statement but it must be officially certified by your bank. We will not accept uncertified internet statements'),
  ('ie-short-stay-business-visa', 'no_employer_bank_statements', 'Do not submit your employer’s bank statements unless requested to do so.'),
  ('ie-short-stay-c-visa', 'stay_90_days_max', 'A short stay or ‘C’ visa allows you travel to Ireland for up to 90 days'),
  ('ie-short-stay-c-visa', 'no_work_permitted', 'This visa does not allow you to: Do paid or unpaid work of any kind'),
  ('ie-short-stay-c-visa', 'no_publicly_funded_services', 'Use any publicly funded services, such as a public hospital.'),
  ('ie-short-stay-c-visa', 'apply_from_home_or_residence_country', 'Apply for a visa before travelling. You must do this from your home country or the country where you are a legal resident.'),
  ('ie-short-stay-c-visa', 'one_application_per_person', 'Apply for a visa for each person travelling. Ireland do not issue Family visas or E-visas'),
  ('ie-short-stay-c-visa', 'do_not_book_before_approval', 'Wait for approval before you buy any travel tickets.'),
  ('ie-short-stay-c-visa', 'visa_is_not_permission_to_enter', 'A visa allows you to travel to Ireland only. It does not give you permission to enter the country or to stay here. An immigration officer at border control can refuse entry even if you have a visa.'),
  ('ie-short-stay-c-visa', 'avats_online_application', 'Use the Automated Visa Application and Tracking System (AVATS) to apply for your visa online'),
  ('ie-short-stay-c-visa', 'visa_application_fee', 'Pay the visa application fee Details of the current visa fees are available here. The fee covers the administrative cost of processing your application. This will not be refunded if you withdraw your application or if we refuse your application.'),
  ('ie-short-stay-c-visa', 'submit_hardcopy_documents', 'Documents in hardcopy format only will be accepted'),
  ('ie-short-stay-c-visa', 'passport_valid_6_months_after_departure', 'Your current passport – your current passport must be valid for at least 6 months after the date you plan to leave Ireland'),
  ('ie-short-stay-c-visa', 'previous_passports_copies', 'A photocopy of each page from all previous passports you have (where available). Your application will be delayed if you do not provide copies of all previous passports you have'),
  ('ie-short-stay-c-visa', 'passport_photographs', 'Include 2 passport-sized colour photographs of the visa applicant. On the back of each photo: Sign your name (in your native script and language) Write your Visa Application Transaction Number from AVATS'),
  ('ie-short-stay-c-visa', 'application_summary_sheets', 'Print, sign and date the application summary sheets (from AVATS).'),
  ('ie-short-stay-c-visa', 'application_letter', 'Type or write a letter explaining why you want to come to Ireland. Sign and date the letter and submit it with your documents.'),
  ('ie-short-stay-c-visa', 'commitments_in_application_letter', 'Your letter must also include a commitment from you that you will: Obey the conditions of your visa in full Not rely on public services (for example public hospitals) or become a burden on the State Leave Ireland before your immigration permission expires.'),
  ('ie-short-stay-c-visa', 'evidence_of_ties_to_home_country', 'it is important that you provide evidence that you have strong family, social or economic ties to your country of residence. This is necessary in order to satisfy the Visa Officer that you will leave Ireland on, or before, your intended date of departure from Ireland.'),
  ('ie-short-stay-c-visa', 'proof_of_finances', 'You must show that you have enough finance (money) to support yourself in Ireland.'),
  ('ie-short-stay-c-visa', 'finances_no_minimum', 'Note: There is no minimum amount of finance for approving or refusing a visa application. The visa officer will decide if you have enough based on your own circumstances.'),
  ('ie-short-stay-c-visa', 'previous_visa_refusals_disclosure', 'For all visa or preclearance applications, if you have been refused a visa or preclearance in the past for any country, you must provide details to us. The original letter issued to you by the authorities of that country must be provided with your application. Not disclosing any previous visa refusals will result in your application being refused.'),
  ('ie-short-stay-c-visa', 'medical_or_travel_insurance', 'Evidence of medical or travel insurance does not need to be provided with your application. However, the Visa Officer may request it before they make a decision on your application. If your visa is approved, you must have evidence of medical or travel insurance when you arrive at the port of entry (airport or seaport) and must present it to the Immigration Officer on request.'),
  ('my-long-term-social-visit-pass', 'minimum_six_months', 'The Long-Term Social Visit Pass (LTSVP) is issued by the Jabatan Imigresen Malaysia to foreign nationals for temporary residence in Malaysia for a minimum period of six (6) months.'),
  ('my-long-term-social-visit-pass', 'spouse_up_to_five_years', 'The pass may be granted for up to five (5) years, subject to approval and compliance with the prescribed conditions.'),
  ('my-long-term-social-visit-pass', 'work_without_converting', 'The pass holder is permitted to work, engage in business, or undertake professional employment without the need to convert to an Employment Pass or Visit Pass (Temporary Employment).'),
  ('my-long-term-social-visit-pass', 'naziran_inspection', 'Naziran is carried out as a verification activity to ensure that holders of immigration facilities comply with the prescribed conditions. The implementation of Naziran may involve visits to the registered address or premises, observation, interviews with relevant parties and review of documents submitted to the Department.'),
  ('my-long-term-social-visit-pass', 'apply_with_spouse_in_person', 'The application must be submitted by the applicant together with his or her Malaysian citizen spouse.'),
  ('my-long-term-social-visit-pass', 'marriage_legally_registered', 'The applicant must be legally married to a Malaysian citizen and holding a Social Visit Pass under the spouse facility of a Malaysian citizen.'),
  ('my-long-term-social-visit-pass', 'employment_must_be_lawful', 'The employment or business undertaken must be lawful under the laws of Malaysia.'),
  ('my-long-term-social-visit-pass', 'work_permission_endorsed_in_passport', 'Approval to work or conduct business will be endorsed in the applicant’s passport.'),
  ('my-long-term-social-visit-pass', 'comply_with_director_general_rules', 'Applicants who have been granted permission to work must comply with all regulations set by the Director General of Immigration Malaysia.'),
  ('my-long-term-social-visit-pass', 'children_of_citizens_under_seven', 'Applicants must be under 7 years old.'),
  ('my-long-term-social-visit-pass', 'child_application_by_citizen_parent', 'The application must be submitted by the citizen’s parents.'),
  ('my-long-term-social-visit-pass', 'spouse_identity_card', 'Copy of the Malaysian citizen spouse’s Identity Card (MyKad).'),
  ('my-long-term-social-visit-pass', 'applicant_passport_and_pass', 'Copy of the applicant’s passport and current pass.'),
  ('my-long-term-social-visit-pass', 'statutory_declaration', 'Completed Statutory Declaration Form with photograph, duly affirmed before a Commissioner for Oaths.'),
  ('my-long-term-social-visit-pass', 'marriage_certificate', 'Copy of Marriage Certificate or Marriage Registration Certificate.'),
  ('my-long-term-social-visit-pass', 'employer_offer_letter', 'Letter of Offer from the employer (on official company letterhead).'),
  ('my-long-term-social-visit-pass', 'stamped_employment_contract', 'Employment Contract duly stamped with RM10 revenue stamp and containing the following details:'),
  ('my-long-term-social-visit-pass', 'tripartite_information_form', 'Applicant, Malaysian Spouse and Employer Information Form.'),
  ('my-long-term-social-visit-pass', 'ssm_company_registration', 'Latest copy of the Company Registration Form printed directly from the MyData SSM system.'),
  ('my-long-term-social-visit-pass', 'apply_in_state_of_employment', 'The application must be submitted at the Visa, Pass and Permit Division in the state where the applicant is employed.'),
  ('my-long-term-social-visit-pass', 'apply_with_pass_or_after_offer', 'At the time of applying for the Long-Term Social Visit Pass; or ... At any time after receiving a job offer.'),
  ('my-long-term-social-visit-pass', 'originals_required_incomplete_rejected', 'All original documents must be presented for verification. Incomplete applications will not be processed.'),
  ('my-student-pass', 'apply_from_outside_malaysia', 'd. Applicants MUST BE OUTSIDE MALAYSIA at the time of application submission.'),
  ('my-student-pass', 'institution_must_be_approved', 'b. Admission to Private Higher Education Institutions (IPTS) with courses and establishment approved by the Ministry of Higher Education (MOHE), and authorized to enrol international students by the Ministry of Home Affairs (MOHA).'),
  ('my-student-pass', 'emgs_academic_screening', 'Applications may be submitted online by institutions or students via the STARS system or EMGS portal ... EMGS will conduct academic screening and issue the Approval to Study for International Student letter only to eligible applicants.'),
  ('my-student-pass', 'eval_approval_then_visa', 'f. Upon obtaining eVAL approval, applicants from countries requiring a visa'),
  ('my-student-pass', 'evisa_not_available_from_three_places', 'g. Note: eVISA applications can be made worldwide, except from Malaysia, Israel, and North Korea'),
  ('my-student-pass', 'post_arrival_medical_7_days', 'h. Upon arrival in Malaysia, students must undergo a Post-Arrival Medical Examination within 7 days.'),
  ('my-student-pass', 'institution_submits_for_endorsement', 'i. After passing the medical examination and receiving EMGS support letter, institutions may submit applications to the Immigration Office nearest to the institution’s address for Student Pass endorsement and issuance.'),
  ('my-student-pass', 'dependants_masters_or_phd_only', 'g. Only Student Pass holders at Master’s or PhD level are permitted to bring dependents to reside in Malaysia.'),
  ('my-student-pass', 'centre_students_no_dependants', 'i. Student Pass holders under the Language Centre, Training/Skills Centre, and Accredited Centre category are not permitted to bring dependents.'),
  ('my-student-pass', 'dependants_may_not_work', 'h. Dependents are NOT ALLOWED to work, conduct business, deliver political speeches, lectures, or engage in political activities.'),
  ('my-student-pass', 'part_time_work_20_hours', 'b. Student Pass holders are allowed to work part-time during their study period, limited to 20 hours per week, only at approved locations:'),
  ('my-student-pass', 'work_prohibitions', 'c. Students are prohibited from front desk duties in line with current foreign worker policies and from working as student recruitment agents.'),
  ('my-student-pass', 'student_pass_fee', 'a. Student Pass – RM60.00'),
  ('my-student-pass', 'dependant_pass_fee', 'b. Social Visit Pass for Dependents / Guardians of Student Pass holders – RM90.00'),
  ('my-student-pass', 'emgs_support_letter', 'EMGS Support Letter [Acceptance Declaration (AD)]'),
  ('my-student-pass', 'form_14', '14 Form (New & Renewal Applications)'),
  ('my-student-pass', 'passport_18_months_all_pages', 'Copy of passport (all pages including cover; validity must be at least 18 months)'),
  ('my-student-pass', 'photo_35x50_white', 'Passport-sized photo (3.5cm x 5cm, white background)'),
  ('my-student-pass', 'health_insurance_12_months', 'Health Insurance Policy recognized in Malaysia with a coverage period of at least 12 months.'),
  ('my-student-pass', 'personal_bond_stamped', 'Personal Bond form (stamped)'),
  ('my-student-pass', 'moha_approval_letter', 'Valid MOHA approval letter for international student intake'),
  ('my-student-pass', 'sarawak_extra_documents', 'Letter of Authorization from the Institution of Higher Learning (Sarawak only) ... Cover Letter from the Institution of Higher Learning (Sarawak only) ... Pre-VAL Medical Report / Health Report from Country of Origin (Sarawak only)'),
  ('nl-european-blue-card', 'non_eu_highly_educated', 'A European Blue Card is a European work and residence permit for highly educated employees from outside the European Union (EU), the European Economic Area (EEA), or Switzerland.'),
  ('nl-european-blue-card', 'general_requirements', 'You meet the requirements that apply to everyone.'),
  ('nl-european-blue-card', 'highly_qualified_work', 'You will be doing highly qualified work in the Netherlands and:'),
  ('nl-european-blue-card', 'higher_education_diploma', 'you have a diploma of a programme in higher education. This programme was at least 3 years. The diploma is needed for the profession or sector and is appropriate for the profession or sector.'),
  ('nl-european-blue-card', 'foreign_diploma_nuffic_evaluation', 'Do you have a foreign diploma? Then Nuffic must evaluate the diploma. This means that Nuffic will examine what the foreign diploma (‘credential’) is worth in the Netherlands,'),
  ('nl-european-blue-card', 'work_experience_alternative', 'or you have a minimum of 5 years of relevant work experience. Your work experience is at the level of a higher education diploma. Are you an IT manager or IT professional? A minimum of 3 years of relevant work experience is required during the period of 7 years before the application.'),
  ('nl-european-blue-card', 'income_requirements', 'You meet the income requirements.'),
  ('nl-european-blue-card', 'blue_card_salary_higher', 'The reduced salary criterion is higher for the European Blue Card in comparison to the criterion for highly skilled migrants.'),
  ('nl-european-blue-card', 'contract_at_least_6_months', 'Your employment contract is valid for at least 6 months.'),
  ('nl-european-blue-card', 'employer_economic_activity', 'Your employer''s company carries out economic activity.'),
  ('nl-european-blue-card', 'employer_not_fined', 'Your employer has not been fined in the past 5 years for violating one of the following laws:'),
  ('nl-european-blue-card', 'no_recognised_sponsor_needed', 'Your employer does not need to be a recognised sponsor in order to apply for a European Blue Card. For a highly skilled migrant application, this is mandatory.'),
  ('nl-european-blue-card', 'may_apply_yourself', 'Your employer will apply to the IND for the residence permit. Your employer must do this within 3 months after you travel to the Netherlands. You may also apply to the IND yourself.'),
  ('nl-european-blue-card', 'application_fee', 'The application costs € 423,00. For all fees and exceptions, visit our web page Fees: costs of an application.'),
  ('nl-european-blue-card', 'long_term_eu_residency_2_years', 'With a European Blue Card, you can in some cases apply for long-term EU residency after 2 years instead of 5 years.'),
  ('nl-highly-skilled-migrant', 'recognised_sponsor_applies', 'Only an employer recognised by the IND can apply for your permit.'),
  ('nl-highly-skilled-migrant', 'general_requirements', 'You meet the general requirements that apply to everyone.'),
  ('nl-highly-skilled-migrant', 'employment_contract', 'You have an employment contract with an employer or research institution in the Netherlands.'),
  ('nl-highly-skilled-migrant', 'employer_is_recognised_sponsor', 'This employer is a sponsor recognised by the IND. A recognised sponsor is listed in the public register of recognised sponsors.'),
  ('nl-highly-skilled-migrant', 'income_requirements', 'You meet the income requirements.'),
  ('nl-highly-skilled-migrant', 'salary_at_market_rate', 'The agreed salary is in line with the market rate. In line with the market rate means that you earn the same as what people in the same job earn on average.'),
  ('nl-highly-skilled-migrant', 'big_registration_healthcare', 'Are you going to work in individual healthcare? And do you practise a medical profession that is listed in Article 3 and Article 36a of the Individual Healthcare Professions Act (BIG Act)? If so, you must be registered in the BIG register.'),
  ('nl-highly-skilled-migrant', 'documents_legalised_and_translated', 'Have foreign documents legalised and translated into Dutch, English, French or German.'),
  ('nl-highly-skilled-migrant', 'employer_holds_document_list', 'Your employer has a list of documents that you need.'),
  ('nl-highly-skilled-migrant', 'employer_applies_for_mvv_and_permit', 'Your employer applies for the MVV and the residence permit at the same time.'),
  ('nl-highly-skilled-migrant', 'apply_within_3_months_if_in_nl', 'Then your employer must do this within 3 months after you have travelled to the Netherlands.'),
  ('nl-highly-skilled-migrant', 'application_fee', 'The application costs € 423,00. For all fees and exceptions visit our web page Fees: costs of an application. Your employer pays automatically by direct debit.'),
  ('nl-highly-skilled-migrant', 'decision_period_90_days', 'The IND must take a decision within 90 days. This is called the decision period. We can extend the decision period if it takes longer to decide.'),
  ('nl-highly-skilled-migrant', 'intra_corporate_transferee_exclusion', 'Do you have an employment contract with a company located outside the EU? And are you going to be transferred as a manager, specialist or trainee? Then you are an intra corporate transferee and other requirements apply to you.'),
  ('nl-orientation-year', 'general_requirements', 'You meet the general requirements that apply to everyone.'),
  ('nl-orientation-year', 'one_qualifying_situation', 'One of these situations applies to you:'),
  ('nl-orientation-year', 'route_scientific_research', 'You have conducted scientific research in the Netherlands in the 3 years before the date of application.'),
  ('nl-orientation-year', 'route_erasmus_mundus', 'You obtained a master’s degree in the 3 years before the date of application in the context of an Erasmus Mundus Joint Master programme.'),
  ('nl-orientation-year', 'route_dutch_study_programme', 'An accredited bachelor’s or master’s degree programme at a Dutch higher education institution. A post-master’s study programme in the Netherlands for at least one academic year (at least 10 months).'),
  ('nl-orientation-year', 'route_foreign_top_200_institution', 'Your educational institution is in the top 200 of the general rankings or the rankings by subject of at least 2 of the 3 publishers. Your educational institution is in the top 200 of these rankings on the date of your graduation or promotion.'),
  ('nl-orientation-year', 'subject_ranking_must_match', 'Is your educational institution in a ranking by subject? In that case that ranking must be about your study or research subject.'),
  ('nl-orientation-year', 'programme_language', 'Your master’s degree programme, doctoral programme or post-master’s study programme was in English or Dutch.'),
  ('nl-orientation-year', 'nuffic_diploma_evaluation', 'All foreign diplomas have to be evaluated by Nuffic before they can be accepted. This credential evaluation shows the worth of a foreign degree in the Netherlands. Nuffic may also check whether your diploma is genuine.'),
  ('nl-orientation-year', 'mvv_required', 'A valid provisional residence permit (MVV) is needed for this application'),
  ('nl-orientation-year', 'documents_legalised_and_translated', 'Have official foreign documents legalised and translated into Dutch, English, French or German.'),
  ('nl-orientation-year', 'application_form_lists_documents', 'The application form lists which documents you need. Collect all documents before you apply.'),
  ('nl-orientation-year', 'application_fee', 'The application costs € 254,00. For all fees and exceptions, visit our web page F ees: costs of an application.'),
  ('nl-orientation-year', 'payment_timing', 'Please wait 1 week after your appointment with the Dutch representation before paying for your application. The application form explains how to pay for the application. You must pay no later than 3 weeks after the date of your appointment.'),
  ('nl-orientation-year', 'second_orientation_year_possible', 'The IND can give a residence permit for an orientation year after each performed research project. Or after each completed study programme at a Dutch higher education institution, or a doctoral programme. However, the new study programme or doctoral programme must have been completed after your previous orientation year.'),
  ('nl-partner-residence-permit', 'valid_travel_document', 'You and your partner have a valid passport or other travel document.'),
  ('nl-partner-residence-permit', 'verifiable_relationship', 'You have a verifiable relationship with your partner. You are married, you have a registered partnership, or you are unmarried.'),
  ('nl-partner-residence-permit', 'age_21_or_18_if_already_married', 'You are both 21 years or older. Were you already married to your partner when you both (still) lived outside the Netherlands? Then you also meet the requirement when you are both 18 years or older.'),
  ('nl-partner-residence-permit', 'living_together_registered', 'In the Netherlands, you live together with your partner. You and your partner are registered at the same address with the municipality.'),
  ('nl-partner-residence-permit', 'income_requirement', 'You meet the income requirements. Do you want to know whether your income is sufficient? Take the income test.'),
  ('nl-partner-residence-permit', 'sponsor_declaration', 'You declare that you are a sponsor for your partner in the application form. This means that you have obligations and responsibilities.'),
  ('nl-partner-residence-permit', 'sponsor_dutch_nationality_or_permit', 'You have Dutch nationality or you have a valid Dutch residence permit.'),
  ('nl-partner-residence-permit', 'excluded_sponsor_permit_purposes', 'You cannot have your partner come join you in the Netherlands if you have a residence permit for one of these purposes of stay: Au pair Working Holiday Cultural exchange Work experience (intern or apprentice) Seasonal work Seafaring service as a crew member on board a seagoing vessel EU-UK Trade Agreement'),
  ('nl-partner-residence-permit', 'one_year_residence_if_obliged_to_integrate', 'Are you obliged to integrate in the Netherlands? Then you must have lived for at least 1 year in the Netherlands with a valid residence permit, before you can bring your partner to the Netherlands. This does not apply when it is in the interest of your minor children that your partner already comes to the Netherlands now.'),
  ('nl-partner-residence-permit', 'civic_integration_exam_abroad', 'Before you apply for the MVV, your partner has passed the civic integration exam abroad. Sometimes your partner does not have to take the exam.'),
  ('nl-partner-residence-permit', 'tb_test_after_arrival', 'After your partner arrives in the Netherlands, your partner must take a TB (tuberculosis) test.'),
  ('nl-partner-residence-permit', 'no_danger_public_order', 'Your partner does not pose a danger to public order or national security. Everyone over the age of 12 must completely fill in an Appendix Antecedents Certificate and enclose it with the application.'),
  ('nl-partner-residence-permit', 'legalise_and_translate_documents', 'Have official foreign documents legalised and translated into Dutch, English, French or German.'),
  ('nl-partner-residence-permit', 'apply_mvv_and_permit_together', 'You apply for the MVV and the residence permit at the same time. You can apply online or in writing by post.'),
  ('nl-partner-residence-permit', 'application_fee', 'The application costs € 254,00. For all fees and exceptions, visit our web page Fees: application costs.'),
  ('nl-partner-residence-permit', 'decision_period_90_days', 'The IND must take a decision within 90 days. This is called the decision period.'),
  ('nl-student-residence-permit-higher-education', 'general_requirements', 'You meet the general requirements that apply to everyone.'),
  ('nl-student-residence-permit-higher-education', 'proof_of_registration', 'You have proof of registration or temporary proof of registration as a student at a university or institute of higher professional education'),
  ('nl-student-residence-permit-higher-education', 'accredited_programme', 'Your study programme is accredited: this means that it has been recognised by Accreditation Organisation of the Netherlands and Flanders or NVAO (in the Netherlands) or the European Quality Assurance Register for Higher Education or EQAR (Europe).'),
  ('nl-student-residence-permit-higher-education', 'recognised_sponsor_institution', 'Your educational institution is a sponsor recognised by the IND.'),
  ('nl-student-residence-permit-higher-education', 'full_time_enrolment', 'You will enrol on a full-time study programme.'),
  ('nl-student-residence-permit-higher-education', 'income_requirements', 'You meet the income requirements.'),
  ('nl-student-residence-permit-higher-education', 'study_progress_50_percent', 'Every year you make enough progress in your studies. This means that you obtain at least 50% of the credits for each study year.'),
  ('nl-student-residence-permit-higher-education', 'institution_applies_on_your_behalf', 'Your educational institution submits the application and applies for your MVV and student residence permit at the same time.'),
  ('nl-student-residence-permit-higher-education', 'mvv_required', 'A valid provisional residence permit (MVV) is needed for this application'),
  ('nl-student-residence-permit-higher-education', 'documents_legalised_and_translated', 'Have official foreign documents legalised and translated into Dutch, English, French or German.'),
  ('nl-student-residence-permit-higher-education', 'collect_documents', 'The educational institution has a list of documents you need. Collect all documents before your educational institution submits the application.'),
  ('nl-student-residence-permit-higher-education', 'application_fee', 'The application costs € 254,00. For all fees and exceptions, visit our web page Fees: application costs. The costs are paid through the educational institution.'),
  ('nl-student-residence-permit-higher-education', 'decision_period_60_days', 'The IND must take a decision within 60 days. This is called the decision period. We can extend the decision period if it takes longer to decide.'),
  ('nl-student-residence-permit-higher-education', 'mvv_appointment_within_3_months', 'You have to make the appointment within 3 months after the IND has taken a decision on your application.'),
  ('nl-student-residence-permit-higher-education', 'passport_valid_6_months_at_mvv', 'Your passport must be valid for at least another 6 months when the Dutch representation places the MVV visa sticker in the passport. The MVV is valid for 90 days.'),
  ('nl-student-residence-permit-higher-education', 'collect_residence_permit', 'When your student residence permit is ready at the IND desk, your educational institution will receive a letter. You must make an appointment to collect it.'),
  ('nl-student-residence-permit-higher-education', 'application_form_7504', 'Application for the purpose of residence ''study'' (recognised sponsor) Higher education 7504'),
  ('no-family-cohabitant', 'both_over_18', 'Both of you must be over the age of 18.'),
  ('no-family-cohabitant', 'will_live_together_in_norway', 'You are going to live together in Norway.'),
  ('no-family-cohabitant', 'one_qualifying_cohabitation_basis', 'You must meet one of the following two requirements:'),
  ('no-family-cohabitant', 'basis_two_years_cohabitation', 'You must have lived together for at least two years and neither of you can be married to someone else. If you have lived together in Norway, both of you must have had legal residence.'),
  ('no-family-cohabitant', 'basis_child_together', 'You have, or are expecting, a child together. You are both unmarried or divorced.'),
  ('no-family-cohabitant', 'both_at_least_24', 'You must be at least 24 years old.'),
  ('no-family-cohabitant', 'age_24_exemption_possible', 'Some couples can be exempted from this requirement. When UDI assesses whether you can be granted an exemption, we will consider what countries your background is from, and whether forced marriages occur in these countries.'),
  ('no-family-cohabitant', 'applicant_application_fee', 'First-time application for family immigration for adults NOK 11900'),
  ('no-family-cohabitant', 'applicant_documented_identity', 'You must document your identity. A valid passport is usually valid proof of identity.'),
  ('no-family-cohabitant', 'applicant_no_entry_prohibition', 'You must not be subject to a prohibition against entry to Norway or Schengen.'),
  ('no-family-cohabitant', 'reference_person_income', 'You must have an income of at least NOK 436 957 per year pre-tax. This amount is adjusted in May each year, but this is the applicable amount if you apply now. You must have this amount of income the first year your family member receives a permit in Norway. In addition, you must have had at least this income last year and during the time we process the application.'),
  ('no-family-spouse', 'application_fee', 'First-time application for family immigration for adults NOK 11900'),
  ('no-family-spouse', 'marriage_validly_entered', 'Your marriage/partnership must have been validly entered into.'),
  ('no-family-spouse', 'marriage_recognisable_in_norway', 'It must be possible to have your marriage recognised in Norway if you entered into marriage while abroad.'),
  ('no-family-spouse', 'plans_to_live_together', 'You must have plans to live together in Norway.'),
  ('no-family-spouse', 'not_forced_marriage', 'You must not have been forced to marry (forced marriage).'),
  ('no-family-spouse', 'not_circumvention_marriage', 'Your marriage must not be circumvention marriage.'),
  ('no-family-spouse', 'both_at_least_24', 'You must be at least 24 years old.'),
  ('no-family-spouse', 'age_24_exemption_possible', 'Some couples can be exempted from this requirement. When UDI assesses whether you can be granted an exemption, we will consider what countries your background is from, and whether forced marriages occur in these countries.'),
  ('no-family-spouse', 'applicant_documented_identity', 'You must document your identity. A valid passport is usually valid proof of identity.'),
  ('no-family-spouse', 'applicant_no_entry_prohibition', 'You must not be subject to a prohibition against entry to Norway or Schengen.'),
  ('no-family-spouse', 'reference_person_income', 'You must have an income of at least NOK 436 957 per year pre-tax. This amount is adjusted in May each year, but this is the applicable amount if you apply now. You must have this amount of income the first year your family member receives a permit in Norway. In addition, you must have had at least this income last year and during the time we process the application.'),
  ('no-skilled-worker', 'application_fee', 'You must pay an application fee.'),
  ('no-skilled-worker', 'qualifications', 'You must have one of the following types of education/qualifications a completed vocational training programme of at least three years at upper secondary school level, for example as a carpenter or health worker. There must be a corresponding vocational training programme in Norway. completed education or degree from a university/ university college, for example a bachelor''s degree as an engineer or nurse.'),
  ('no-skilled-worker', 'special_qualifications_experience', 'special qualifications are skills acquired through long professional experience, possibly in combination with courses and education. You must have as high competence as someone who has completed vocational education from upper secondary school. Generally, you must have at least six years of work experience.'),
  ('no-skilled-worker', 'documentation_scrutiny_warning', 'it may be difficult to obtain a residence permit to work as a skilled worker at a vocational level, particularly within the restaurant, automotive industry, and construction industries.'),
  ('no-skilled-worker', 'concrete_job_offer', 'You must have received a concrete job offer from one specific employer in Norway.'),
  ('no-skilled-worker', 'employer_confirmation_code', 'If you are applying on your own from abroad, your employer must submit confirmation of the job offer before you can submit the application form. You will receive a code from your employer that you must enter in the application form.'),
  ('no-skilled-worker', 'full_time_or_80_percent', 'The job must normally be full-time. If you have been offered at least an 80% position, we will accept this.'),
  ('no-skilled-worker', 'job_requires_skilled_qualifications', 'The job you are offered must require qualifications as a skilled worker. You must have the qualifications that the job requires.'),
  ('no-skilled-worker', 'pay_and_conditions_not_poorer', 'The pay and working conditions must not be poorer than is normal in Norway.'),
  ('no-skilled-worker', 'occupational_authorisation', 'If you are going to work in an occupation for which recognition or authorisation is required (external website), you must have such recognition or authorisation.'),
  ('no-skilled-worker', 'staffing_agency_assignment_list', 'If you are to work through a staffing agency, you must present a list of the assignments that the employer has planned for you. The assignments must be confirmed by the business/businesses you are carrying out the assignments for. It is only possible for you to get a residence permit for the period of time when you are carrying out the assignments on this list.'),
  ('no-skilled-worker', 'permit_duration_by_qualification', 'If the position requires that you have completed a vocational training programme at upper secondary school level, you can get a residence permit for up to one year at a time. If the position requires that you have completed an education or degree from a university/ university college, you can normally get a residence permit for up to three years at a time.'),
  ('no-skilled-worker', 'change_of_employer', 'If you are later going to change employers, but work in the same type of position, you do not need to apply for a new residence permit.'),
  ('no-skilled-worker', 'job_loss_six_months', 'If you lose your job, you can stay in Norway for up to six months to look for a new job. You must notify the police where you live within seven days.'),
  ('no-study-permit', 'study_longer_than_3_months', 'If you wish to study or go to school in Norway for more than three months, you must apply for a study permit.'),
  ('no-study-permit', 'work_rights', 'If you are granted a study permit, you will also be able to work for up to 20 hours a week while you are studying and full-time during holidays.'),
  ('no-study-permit', 'application_fee', 'You must pay an application fee.'),
  ('no-study-permit', 'admission_to_institution', 'You must have been admitted to a university college or university.'),
  ('no-study-permit', 'full_time_study', 'You must study full-time.'),
  ('no-study-permit', 'maintenance_funds', 'You must have enough money to live on during the period you are going to study in Norway. This means at least NOK 15 488 per month, or NOK 170 368 per year for the entire academic year.'),
  ('no-study-permit', 'maintenance_single_semester', 'If you are going to be a student for only one semester in Norway, you must document NOK 77 440 for the autumn semester and NOK 92 928 for the spring semester.'),
  ('no-study-permit', 'acceptable_fund_sources', 'This amount of money may consist of student loans, grants, own funds that you have in a Norwegian bank account or the deposit account of the educational institution, or a combination of the above. If you have already been offered a part-time job in Norway, the income from this work may be included.'),
  ('no-study-permit', 'funds_location', 'The money must be in a Norwegian bank account or the deposit account of the educational institution.'),
  ('no-study-permit', 'tuition_fees_covered', 'If you have to pay tuition fees, you must also have money to cover this or document in your application that your tuition fees for the academic year 2025/2026 have already been paid. If you have paid for one semester, you must provide documentation in your application showing that you have enough money to pay for the second semester.'),
  ('no-study-permit', 'tuition_exemption_confirmed', 'If you have an exemption from paying tuition fees this must be confirmed by your educational institution.'),
  ('no-study-permit', 'accommodation', 'You must have somewhere to live.'),
  ('no-study-permit', 'likelihood_of_return', 'The circumstances in your home country must indicate that it is likely that you can return home when you have completed your studies.'),
  ('no-visitor-visa', 'schengen_wide_validity', 'If you plan to visit Norway for up to 90 days, you can apply for a visitor visa. This visa is valid for entry to all Schengen countries.'),
  ('no-visitor-visa', 'application_fee', 'You must pay an application fee.'),
  ('no-visitor-visa', 'embassy_checklist_documents', 'You must hand in all the documents on the embassy’s checklist. You will find the checklist by clicking on the “How to apply”-button below and choosing the country you live in.'),
  ('no-visitor-visa', 'passport_validity', 'You must have a passport that is valid for at least three months after the end of your visit. The passport must be issued within the last ten years.'),
  ('no-visitor-visa', 'travel_insurance', 'You must have valid travel insurance.'),
  ('no-visitor-visa', 'sufficient_funds', 'You must have enough money to finance your stay in Norway and your return journey. You must be able to document that you have sufficient means to support yourself during your stay in Norway and the Schengen area. Whether your funds are considered sufficient will be assessed individually in each case.'),
  ('no-visitor-visa', 'funds_guideline_amounts', 'The following amounts serve as general guidelines for what is regarded as a sufficient minimum: NOK 300 per day is regarded as a sufficent minimum if you will be staying with family or friends, or in accommodation that has been paid for in advance. NOK 1,300 per day is regarded as sufficient if you have not documented pre-booked or pre-paid accommodation for the entire duration of your stay. If several people are travelling together, the amount should be at least NOK 1,000 per person per day.'),
  ('no-visitor-visa', 'sponsor_if_insufficient_funds', 'If you do not have enough money yourself, you must have a financial guarantee: The person or company you are visiting must fill out a sponsorship form, which can be either electronic or on a paper form. Remember to have the four-word sponsor code ready when you apply for a visitor visa (if your sponsor uses the electronic form). You only need a sponsor for the visit if you do not have enough money yourself.'),
  ('no-visitor-visa', 'no_entry_prohibition', 'You must not be subject to a prohibition against entry to Norway or Schengen.'),
  ('no-visitor-visa', 'schengen_90_180_check', 'If you have been in the Schengen area in the last 90 days, you must check when it is possible for you to re-enter, and how many days you can stay in Schengen.'),
  ('no-visitor-visa', 'fingerprints', 'You must register your fingerprints.'),
  ('no-visitor-visa', 'minor_parental_signature', 'If you are under the age of 18, both your parents, or other persons responsible for you, must sign your application.'),
  ('no-visitor-visa', 'invitation_from_host', 'You must have an invitation from the person you are going to visit.'),
  ('no-visitor-visa', 'likelihood_of_return_assessed', 'When we process your application, we consider how probable it is that you will return to your home country or the country you live in when the visit is over. We consider the situation in your country and your own situation. We will focus on whether you have anything that ties you to your home country, for example work, property, a spouse or family members who you are supporting. If we believe that it is unlikely that you will return, your application will normally be rejected.'),
  ('nz-accredited-employer-work-visa', 'job_offer_from_accredited_employer', 'have an offer of full-time work from an accredited employer'),
  ('nz-accredited-employer-work-visa', 'job_offer_conditions', 'Your job offer must be: current at the time you apply for your visa for at least 30 hours of work a week from an employer who is accredited to hire migrants for the Accredited Employer Work Visa (AEWV) and has an approved job check for your job'),
  ('nz-accredited-employer-work-visa', 'skill_requirements', 'meet our skill requirements meet the requirements of your job''s ANZSCO or NOL skill level and qualifications have the skills and experience your employer requires'),
  ('nz-accredited-employer-work-visa', 'occupational_registration', 'have occupational registration, if your job requires it to work in New Zealand'),
  ('nz-accredited-employer-work-visa', 'stand_down_period', 'have spent the required time outside New Zealand if applying for another Accredited Employer Work Visa (AEWV) after staying for as long as you can on previous AEWVs'),
  ('nz-accredited-employer-work-visa', 'english_language_skill_level_3_5', 'speak and understand English, if your job is skill level is 3 to 5'),
  ('nz-accredited-employer-work-visa', 'good_health', 'be in good health'),
  ('nz-accredited-employer-work-visa', 'good_character', 'have a good character'),
  ('nz-accredited-employer-work-visa', 'genuine_reason', 'have a genuine reason for coming to New Zealand.'),
  ('nz-accredited-employer-work-visa', 'employment_agreement', 'a copy of the employment agreement and job description'),
  ('nz-accredited-employer-work-visa', 'signed_job_offer', 'a signed copy of the job offer.'),
  ('nz-accredited-employer-work-visa', 'employment_agreement_contents', 'The employment agreement must include: your employer''s name, address and phone number your name and address your job title the address for your place of work the kind of work you will be doing and your responsibilities at work'),
  ('nz-accredited-employer-work-visa', 'employer_sends_application_link', 'The employer must send you a link to the online application form.'),
  ('nz-accredited-employer-work-visa', 'no_payment_for_job_offer', 'We will decline an application for an AEWV if we consider you or your agent has offered or promised money to the employer (or their agent) in exchange for a job offer.'),
  ('nz-accredited-employer-work-visa', 'application_fee', 'Cost From NZD $1540'),
  ('nz-accredited-employer-work-visa', 'length_of_stay', 'Length of stay Up to 5 years based on the job offered'),
  ('nz-accredited-employer-work-visa', 'study_limit', 'study for up to 3 months in any 12-month period, or do any study required as part of your employment'),
  ('nz-accredited-employer-work-visa', 'visa_tied_to_employer', 'If your situation changes and you want to change your employer, job, location or a combination of these, you must apply to vary the conditions of y'),
  ('nz-exchange-student-visa', 'accepted_into_approved_exchange_scheme', 'show you have been accepted into an approved exchange student scheme'),
  ('nz-exchange-student-visa', 'study_abroad_not_eligible', 'Study Abroad programmes are not approved exchange schemes. Students planning to study with a Study Abroad programme should apply for a Fee Paying Student Visa.'),
  ('nz-exchange-student-visa', 'offer_of_place_evidence', 'If you are attending a school-to-school or tertiary exchange programme, you need to provide evidence of an offer of place from an — this should state you are an exchange student. If you are coming to New Zealand with an exchange programme organisation (EPO), you need to provide a letter from your EPO explaining that you are an exchange student.'),
  ('nz-exchange-student-visa', 'exchange_scheme_acceptance_evidence', 'You must provide evidence that you have been accepted into an. For example, a letter from the scheme organiser.'),
  ('nz-exchange-student-visa', 'outside_new_zealand', 'You must be outside New Zealand when you apply. We will check our records to make sure you are not already in New Zealand.'),
  ('nz-exchange-student-visa', 'sufficient_funds_or_sponsor', 'have enough money to pay your living expenses, or have an acceptable sponsor'),
  ('nz-exchange-student-visa', 'intent_to_leave', 'show you can leave New Zealand at the end of your stay.'),
  ('nz-exchange-student-visa', 'good_health', 'be in good health'),
  ('nz-exchange-student-visa', 'good_character', 'be of good character'),
  ('nz-exchange-student-visa', 'genuine_reason', 'have a genuine reason for coming to New Zealand'),
  ('nz-exchange-student-visa', 'practical_work_experience_evidence', 'provide evidence that practical work experience is part of your course, where required'),
  ('nz-exchange-student-visa', 'written_permission_to_work', 'provide information about your holidays and your course, and have written permission, if you plan to work'),
  ('nz-exchange-student-visa', 'work_rights', 'work part-time up to 25 hours a week while studying, or in the holidays, depending on your age and how long your study is for.'),
  ('nz-exchange-student-visa', 'no_tuition_fees', 'You do not need to pay tuition fees as you are considered a.'),
  ('nz-exchange-student-visa', 'application_fee', 'Cost From NZD $850'),
  ('nz-exchange-student-visa', 'length_of_stay', 'Length of stay Up to 4 years'),
  ('nz-post-study-work-visa', 'recently_finished_nz_study', 'have recently finished studying in New Zealand for an approved qualification'),
  ('nz-post-study-work-visa', 'hold_qualifying_nz_qualification', 'You must have gained a qualification in New Zealand that lets you apply for this visa.'),
  ('nz-post-study-work-visa', 'route_degree_level_7_or_higher', 'If you have studied a degree level 7 or higher qualification, you must have studied it full-time for at least 30 weeks in New Zealand.'),
  ('nz-post-study-work-visa', 'route_non_degree_on_eligible_list', 'If you have studied a non-degree level 7 or lower qualification, it must be on the list of qualifications eligible for a Post Study Work Visa. Your study must have been full-time in New Zealand, and for the full duration required to gain the qualification. The job you end up taking must be related to what you studied. This will be specified in your visa conditions.'),
  ('nz-post-study-work-visa', 'application_deadline', 'apply no later than 3, 6 or 12 months after your student visa expires, depending on what you studied and what visa you had'),
  ('nz-post-study-work-visa', 'once_only', 'You can only have this visa once.'),
  ('nz-post-study-work-visa', 'good_health', 'We may ask you to have a chest X-ray, a medical examination or both as proof of your good health.'),
  ('nz-post-study-work-visa', 'chest_xray_tb_rule', 'If you will stay in New Zealand for more than 6 months, you must have a chest X-ray if you: are a citizen of a country that does not have a low incidence of tuberculosis (TB), or have spent more than 3 months in the last 5 years in a country that does not have a low incidence of TB.'),
  ('nz-post-study-work-visa', 'good_character', 'If you have a criminal conviction or are a security risk to New Zealand we might not give you a visa.'),
  ('nz-post-study-work-visa', 'police_certificates', 'You must provide police certificates that are less than 6 months old when you apply if: you are aged 17 or older, and your total time in New Zealand will be 24 months or longer. This includes time you spent in New Zealand in the past on other visas.'),
  ('nz-post-study-work-visa', 'genuine_intentions', 'have a genuine reason for coming to New Zealand'),
  ('nz-post-study-work-visa', 'funds_nzd_5000', 'When you apply you must provide documents, such as bank statements in your name, that show you have at least NZD $5,000 in total for your stay. This applies to visa applications for 1, 2 or 3 years.'),
  ('nz-post-study-work-visa', 'passport_validity', 'Your passport or certificate of identity must be valid for at least 3 months after the date you plan to leave New Zealand.'),
  ('nz-post-study-work-visa', 'proof_of_qualification', 'You must provide: a copy of your qualification your academic transcript, or a letter from your tertiary education provider confirming you have completed your qualification.'),
  ('nz-post-study-work-visa', 'photo', '1 acceptable photo if you apply online, or 2 photos if you apply on paper'),
  ('nz-post-study-work-visa', 'application_fee', 'Cost From NZD $1670'),
  ('nz-post-study-work-visa', 'incomplete_qualification_warning', 'If you did not complete the qualification recorded on your student visa, we may not approve your Post Study Work Visa application.'),
  ('nz-post-study-work-visa', 'stay_and_work_up_to_3_years', 'You can stay and work in New Zealand for up to 3 years depending on the level of your qualification and how long you spent studying for it.'),
  ('nz-post-study-work-visa', 'partner_and_children_may_apply', 'support visas for your partner and dependent children — your partner can apply for a work visa and your children can apply for student visas to study as in New Zealand.'),
  ('nz-post-study-work-visa', 'eligibility_extension_from_2026_11_16', 'From 16 November 2026, Post Study Work Visa eligibility will be extended to applicants who have: an NZQCF level 7 graduate diploma that they studied full-time for in New Zealand, and a bachelor’s degree that they completed in New Zealand or overseas.'),
  ('nz-visitor-visa', 'good_health', 'be in good health'),
  ('nz-visitor-visa', 'good_character', 'be of good character'),
  ('nz-visitor-visa', 'genuine_reasons', 'have genuine reasons for coming to New Zealand'),
  ('nz-visitor-visa', 'sufficient_funds_or_sponsor', 'have enough money to pay your living expenses, or have an acceptable sponsor'),
  ('nz-visitor-visa', 'can_leave_at_end_of_stay', 'show you can leave New Zealand at the end of your stay.'),
  ('nz-visitor-visa', 'no_work_in_new_zealand', 'not plan to work in New Zealand, unless you work remotely for a business overseas'),
  ('nz-visitor-visa', 'chest_xray_or_medical', 'We may ask you to have a chest X-ray, a medical examination or both as proof of your health.'),
  ('nz-visitor-visa', 'health_evidence_thresholds', 'If you are staying less than: 6 months, you do not normally need a chest X-ray 12 months, you do not normally need a medical certificate.'),
  ('nz-visitor-visa', 'police_certificates', 'You must provide police certificates that are less than 6 months old when you apply, if: you are aged 17 or older, and'),
  ('nz-visitor-visa', 'criminal_conviction_may_bar', 'If you have a criminal conviction, or are a security risk to New Zealand, we might not give you a visa.'),
  ('nz-visitor-visa', 'funds_threshold', 'If you are paying for yourself You must have at least NZD $1,000 a month, or NZD $400 a month if you have already paid for your accommodation.'),
  ('nz-visitor-visa', 'proof_of_funds', 'Evidence can include: proof of accommodation pre-payment, like hotel pre-paid vouchers or receipts bank statements or credit card statements bank drafts or traveller''s cheques.'),
  ('nz-visitor-visa', 'funds_evidence_must_show', 'Evidence must show: the bank account is in the applicant''s name which bank the account is with, and which currency the money is in.'),
  ('nz-visitor-visa', 'application_fee', 'Cost From NZD $441'),
  ('nz-visitor-visa', 'length_of_stay', 'Length of stay Up to either 6 months or 9 months'),
  ('nz-visitor-visa', 'study_limit', 'You cannot work, but you can study for up to 3 months.'),
  ('nz-working-holiday-visa', 'citizen_of_agreement_country', 'To apply, you must be a citizen of a country that has a working holiday agreement with New Zealand.'),
  ('nz-working-holiday-visa', 'age_band', 'Working holiday visas are available to young people — normally aged 18 to 30, but 18 to 35 in a select few countries.'),
  ('nz-working-holiday-visa', 'per_scheme_rules_govern', 'The visa requirements for each country will tell you: how old you have to be how long you can stay how much money you need to bring with you any specific criteria and conditions.'),
  ('nz-working-holiday-visa', 'duration_by_scheme', 'Note If you are from Canada, you can stay for up to 23 months on a working holiday visa. If you are from the United Kingdom you can stay up to 36 months.'),
  ('nz-working-holiday-visa', 'holiday_must_be_the_main_purpose', 'On a working holiday visa, you need to: have a return ticket, or be able to pay for one, and be coming mainly to holiday — work or study should be secondary intentions.'),
  ('nz-working-holiday-visa', 'employment_limits', 'You must work for an employer under an employment contract or a contract for services. You cannot operate a business as an owner. You also cannot take a permanent job while you are in New Zealand on a working holiday visa.'),
  ('nz-working-holiday-visa', 'study_limit_six_months', 'On a working holiday visa, you can study 1 or more courses for up to 6 months in New Zealand.'),
  ('nz-working-holiday-visa', 'valid_physical_passport', 'Note You must have a valid physical passport when you apply. If you do not have one, your application may be declined.'),
  ('nz-working-holiday-visa', 'apply_online_only_when_open', 'You can only apply when the working holiday visa for your country is open for applications. Check the website for this information. If you apply before the opening date, your application will be automatically deleted.'),
  ('nz-working-holiday-visa', 'some_schemes_require_home_country', 'In most cases, you can apply from any country, including from within New Zealand. However, some schemes require you to be in your home country when you apply. For example, you must be in China when you apply for the China Working Holiday Visa.'),
  ('nz-working-holiday-visa', 'one_working_holiday_visa_only', 'Warning Make sure you are applying for the right visa for your visit. You can only get a working holiday visa once to work in New Zealand, even if you do not use it.'),
  ('nz-working-holiday-visa', 'arrive_within_twelve_months', 'When you are given a working holiday visa, you must come to New Zealand within 12 months of the date your visa is issued. You cannot delay or cancel a working holiday visa. If you do not arrive in New Zealand within 12 months, the visa will expire, and you will not be able to apply for another working holiday visa.'),
  ('nz-working-holiday-visa', 'traveller_declaration_trap', 'If you are from a visa waiver country and coming to New Zealand on a working holiday visa, make sure you tick the option ''I hold a temporary entry class visa'' when completing your New Zealand Traveller Declaration (NZTD). If you do not do this, we may give you a visitor visa at the border, and your working holiday visa will be cancelled. You will not be able to apply for another working holiday visa.'),
  ('nz-working-holiday-visa', 'chest_xray_if_tb_exposure', 'If you are outside New Zealand and your country’s working holiday scheme allows you to stay up to 12 months, you: must have a chest X-ray if you have spent more than 3 months in the last 5 years in a country that does not have a low incidence of TB do not need to have a chest X-ray or general medical examination if you have only spent time in countries with a low incidence of TB.'),
  ('nz-working-holiday-visa', 'full_medical_if_over_twelve_months', 'If you plan to stay in New Zealand for more than 12 months (including time on visas other than a Working Holiday Visa), you must have a chest X-ray and a general medical examination.'),
  ('nz-working-holiday-visa', 'austria_malaysia_no_medical', 'Malaysia and Austria If you are outside New Zealand and applying for an Austria or Malaysia Working Holiday Visa you do not need to have a chest X-ray or a general medical examination.'),
  ('nz-working-holiday-visa', 'medical_if_applying_inside_nz', 'If you are in New Zealand and applying for a working holiday visa, in most situations you must have a: chest X-ray, and general medical examination.'),
  ('nz-working-holiday-visa', 'english_language_some_schemes', 'English language skills for working holiday visas For some working holiday visas, you will need proof of your English language skills. Check what you will need for the visa you are applying for.'),
  ('se-eu-blue-card', 'valid_passport', 'You must have a valid passport'),
  ('se-eu-blue-card', 'higher_education_or_experience', 'Your higher education must correspond to at least 180 higher education credits. Alternatively, you can have at least five years of relevant professional experience.'),
  ('se-eu-blue-card', 'employment_contract_six_months', 'You must have a highly qualified employment for a period of at least six months. The employment contract must be signed by both you and your employer.'),
  ('se-eu-blue-card', 'salary_threshold', 'Every year, the Swedish Migration Agency determines the salary threshold that you need to exceed in order to be able to get an EU Blue Card. The salary threshold corresponds to 1.25 times the average gross salary in Sweden published by the National Mediation Office. Since 15 July 2026, the salary threshold is SEK 53,625 per month.'),
  ('se-eu-blue-card', 'comprehensive_health_insurance', 'The insurance must be valid for the entire time you will be in Sweden and cover the cost of urgent and other medical care, hospitalisation, and emergency dental care. It must also cover the cost of medical repatriation, if you need to return to your country of origin for health reasons. If you are going to be in Sweden for a period shorter than a total of one year, health insurance must be taken out for an additional three months in addition to the period of employment.'),
  ('se-eu-blue-card', 'employer_starts_application', 'Your employer needs information about your name, date of birth, citizenship and email address. They will use this information when they start your application for an EU Blue Card.'),
  ('se-eu-blue-card', 'translate_documents', 'All submitted documents should be in Swedish or English. If you have translated your documents, the translation should be certified. You must also include a copy of the document in its original language.'),
  ('se-eu-blue-card', 'nominate_embassy', 'You may need to present your passport or be interviewed at an embassy or a consulate-general before you can receive a decision. In the application, you must therefore state which embassy you want to visit.'),
  ('se-eu-blue-card', 'family_maintenance_requirement', 'If your family applies together with you, you are subject to a maintenance requirement.'),
  ('se-eu-blue-card', 'family_maintenance_amounts', 'For 2025, the amount you must have left after paying your rent is: SEK 6,243 for a single adult SEK 10,314 for cohabiting spouses or cohabiting partners SEK 3,336 for children 0–6 years of age SEK 4,004 for children 7–10 years of age SEK 4,672 for children 11–14 years of age SEK 5,339 for children 15 years of age or older.'),
  ('se-eu-blue-card', 'application_fee', 'Employees/self-employed people: SEK 2,000. Adult family members: SEK 1,500 Children: SEK 750 Citizens of Japan do not pay an application fee.'),
  ('se-eu-blue-card', 'work_limited_to_employer_and_profession', 'The card entitles you to work in Sweden for the employer and within the profession specified in your application.'),
  ('se-eu-blue-card', 'report_changes', 'If you already have an EU Blue Card, but your employment ceases, you change jobs, or if something that affects the conditions for the permit changes, you need to report this to the Swedish Migration Agency.'),
  ('se-eu-blue-card', 'permit_validity', 'The first time you are granted an EU Blue Card, it is valid for at least nine months and a maximum of four years.'),
  ('se-eu-blue-card', 'register_population_register', 'If you are granted a permit for at least one year, you should register in Sweden’s population register. This will give you access to health and medical care and dental care.'),
  ('se-family-partner', 'both_over_21', 'You must both be over 21 years old Exceptions can only be made on special grounds, for example if you have children together.'),
  ('se-family-partner', 'relationship_status', 'You must be married, registered partners, or cohabiting partners, or plan to enter one of these relationships'),
  ('se-family-partner', 'plans_to_settle_together', 'To be granted a residence permit, you must be able to show that you have plans to settle in Sweden together. If you cannot describe your specific relocation plans at the time of application, you can add this information later.'),
  ('se-family-partner', 'applicant_valid_passport', 'You must have a valid passport EU/EEA citizens must have a valid passport or national ID card.'),
  ('se-family-partner', 'applicant_outside_sweden', 'You must currently be located outside of Sweden There are some exceptions, see Can I get a residence permit if I apply from within Sweden?'),
  ('se-family-partner', 'sponsor_residence_status', 'The person in Sweden must have one of the following: Swedish citizenship Nordic citizenship permanent residence permit permanent residence card permanent right of residence permanent residence status temporary residence permit as a refugee or person in need of subsidiary protection, or due to exceptionally distressing circumstances.'),
  ('se-family-partner', 'sponsor_maintenance_requirement', 'The person in Sweden must meet the maintenance requirement The person in Sweden must be able to support both of you and have a large enough home to house you both. Some people may be exempt from the maintenance requirement.'),
  ('se-family-partner', 'maintenance_income_thresholds', 'In 2026, the amount you must have left over after tax and the rent is paid is: SEK 6,243 for a single adult SEK 10,314 for cohabiting spouses or cohabiting partners SEK 3,336 for children 0–6 years of age SEK 4,004 for children 7–10 years of age SEK 4,672 for children 11–14 years of age SEK 5,339 for children 15 years of age or older.'),
  ('se-family-partner', 'maintenance_housing', 'You must be able to show that you have housing for at least one year in the future that is large enough to accommodate all of you.'),
  ('se-family-partner', 'swedish_citizen_maintenance_exemption', 'As a Swedish citizen, your partner does not need to meet the maintenance requirement, as long as the two of you have a well-established relationship (for example, if you have lived together for a long time). However, your partner must meet the maintenance requirement if you have any children who will be moving to Sweden with the two of you, and your partner is not their parent or legal guardian.'),
  ('se-family-partner', 'application_fee', 'What does it cost to apply? Adults: SEK 2,000 Children under 18 years of age: SEK 1,000 You will not receive a refund if your application is rejected.'),
  ('se-family-partner', 'register_relationship_tax_agency', 'If you and the person in Sweden have married or entered into a registered partnership, it is important that the person in Sweden registers this relationship with the Swedish Tax Agency.'),
  ('se-family-partner', 'translate_documents', 'All submitted documents should be in Swedish or English. If you have translated your documents, the translation should be certified. You must also include a copy of the document in its original language.'),
  ('se-family-partner', 'select_embassy_for_interview', 'In your application, you must indicate which Swedish embassy or consulate-general you want to visit for your interview. Not all Swedish embassies and consulates-general handle migration cases.'),
  ('se-family-partner', 'fast_track_90_day_decision', 'In order to receive a decision within 90 days, you must meet the requirements to get a residence permit. In addition, the following requirements must be met: Your relationship with your partner must be well-established If you do not have children together, you must have lived together for at least two years. If you have children together, you must have lived together for at least one year. Your partner must be a Swedish citizen At the time of your application, you and your partner must be living together abroad and have done so for a continuous period of at least 12 months'),
  ('se-higher-education-study-permit', 'valid_passport', 'Du ska ha ett giltigt pass'),
  ('se-higher-education-study-permit', 'finally_admitted_full_time', 'Du ska vara slutligt antagen till studier på heltid i Sverige.'),
  ('se-higher-education-study-permit', 'no_distance_learning', 'Du kan inte få uppehållstillstånd för studier med distansundervisning som studieform.'),
  ('se-higher-education-study-permit', 'full_time_definition', 'För studier på universitet och högskola räknas 30 högskolepoäng per termin som heltidsstudier. För studier vid övriga utbildningar, till exempel studier vid en folkhögskoleutbildning, behöver studierna omfatta planerat studiearbete om minst 20 undervisningstimmar per vecka i genomsnitt.'),
  ('se-higher-education-study-permit', 'tuition_paid_for_final_admission', 'Du ska ha betalat eventuella studieavgifter innan du ansöker Det är först när du har betalat din studieavgift som du räknas som slutligt antagen.'),
  ('se-higher-education-study-permit', 'comprehensive_health_insurance', 'Om du är antagen till studier som ska pågå kortare tid än ett år behöver du en heltäckande sjukförsäkring. Om du inte har en försäkring via lärosätet, måste du ha eller ha ansökt om en egen försäkring. Försäkringen ska gälla för hela den tid som du ska vara i Sverige och täcka kostnader för akut och annan sjukvård, sjukhusvistelse och akut tandvård. Den ska också täcka kostnader för hemtransport av medicinska skäl.'),
  ('se-higher-education-study-permit', 'registration_for_long_studies', 'Om dina studier ska pågå i minst ett år bör du folkbokföra dig i Sverige och får då tillgång till hälso- och sjukvård och tandvård.'),
  ('se-higher-education-study-permit', 'maintenance_whole_period', 'Din försörjning ska räcka under hela den tid som du ansöker om uppehållstillstånd för. Om din familj ansöker tillsammans med dig ska du kunna försörja dem också, om de inte har en egen försörjning.'),
  ('se-higher-education-study-permit', 'maintenance_amounts', 'Försörjningskravet är minst 10 656 kronor per månad, om du har ansökt 2026 minst 10 584 kronor per månad, om du har ansökt 2025.'),
  ('se-higher-education-study-permit', 'maintenance_reductions', 'Månadsbeloppet kan minskas med 2 960 kronor per månad för fri mat och 4 736 kronor per månad för fri bostad, om du har ansökt under 2026.'),
  ('se-higher-education-study-permit', 'maintenance_family_additions', 'Då tillkommer 4 440 kronor per månad för make, maka eller sambo 2 664 kronor per månad för varje barn.'),
  ('se-higher-education-study-permit', 'acceptable_means', 'Försörjningskravet innebär att du måste visa att du har pengar tillgängliga genom egna banktillgångar, stipendium, studiebidrag eller studielån från hemlandet, sponsor eller inkomst från anställning. Du kan kombinera olika försörjningsformer.'),
  ('se-higher-education-study-permit', 'documents_language', 'Alla dokument som du skickar med bör vara på svenska eller engelska.'),
  ('se-schengen-visa', 'schengen_90_in_180', 'för att få resa in och vara i Schengenområdet upp till 90 dagar under en period av 180 dagar'),
  ('se-schengen-visa', 'visa_required_by_nationality', 'Du ska ha ett Schengenvisum för att besöka Sverige i upp till 90 dagar om du kommer från ett land vars medborgare behöver visum för att resa in i Sverige och Schengenområdet.'),
  ('se-schengen-visa', 'passport_valid_3_months_after', 'Du behöver ha ett pass som är giltigt minst tre månader efter att du lämnat Schengenområdet'),
  ('se-schengen-visa', 'return_ticket', 'en tur- och returbiljett som ska vara giltig inom 90 dagar'),
  ('se-schengen-visa', 'invitation_or_hotel_booking', 'en skriftlig inbjudan från din familjemedlem eller vän som du ska bo hos, eller en bokningsbekräftelse om du ska bo på hotell'),
  ('se-schengen-visa', 'maintenance_700_sek_per_day', 'Sverige kräver att du har 700 kronor för varje dag som besöket i Sverige varar. Beloppet kan i vissa fall bli lägre, till exempel för yngre barn, om du betalar kostnaden för kost och logi i förväg eller om du ska bo hos släkt eller vänner.'),
  ('se-schengen-visa', 'proof_of_funds', 'Du ska visa att du har tillräckligt med pengar för uppehället med hjälp av exempelvis kontoutdrag från din bank eller dokument där den som bjuder in dig till Sverige lovar att stå för alla kostnader under besöket.'),
  ('se-schengen-visa', 'travel_medical_insurance', 'Det är rekommenderat att du har en individuell medicinsk reseförsäkring som täcker de kostnader som kan uppstå i samband med akut läkarhjälp, brådskande sjukhusvård eller transport till hemlandet av medicinska skäl. Försäkringen bör täcka kostnader på minst 30 000 euro och gälla i alla Schengenländer.'),
  ('se-schengen-visa', 'border_police_no_advance_ruling', 'Gränspolisen kan inte ge förhandsbesked om du kommer att få resa in i Sverige, utan det beslutet tas direkt vid gränskontrollen.'),
  ('se-schengen-visa', 'apply_to_main_destination', 'Om du ska besöka flera länder i Schengenområdet ska du ansöka om Schengenvisum hos myndigheterna i det land som är din huvudsakliga destination.'),
  ('se-schengen-visa', 'visa_fee', 'Person som är 12 år eller äldre: 90 euro Barn 6–11 år: 45 euro Barn 0–5 år: ingen avgift Du får inte tillbaka avgiften om du får avslag på din ansökan.'),
  ('se-schengen-visa', 'fee_exemptions', 'Vissa som ansöker om Schengenvisum behöver inte betala ansökningsavgift: skolelever, högskole- och forskarstuderande samt medföljande lärare som reser till Sverige i studie- eller utbildningssyfte forskare som reser till Sverige för vetenskaplig forskning eller konferens företrädare för ideella organisationer som är 25 år eller yngre'),
  ('se-work-permit-employed', 'valid_passport', 'Du ska ha ett giltigt pass'),
  ('se-work-permit-employed', 'signed_employment_contract', 'Du ska ha ett anställningsavtal Anställningsavtalet ska vara underskrivet av både dig och din arbetsgivare.'),
  ('se-work-permit-employed', 'employment_conditions_match_collective_agreement', 'Din lön och andra anställningsvillkor ska vara på minst samma nivå som svenska kollektivavtal eller vad som är brukligt inom yrket eller branschen.'),
  ('se-work-permit-employed', 'employer_insurances', 'Arbetsgivaren ska ha tecknat sjukförsäkring, livförsäkring, trygghetsförsäkring och tjänstepensionsförsäkring för dig när du påbörjar anställningen.'),
  ('se-work-permit-employed', 'comprehensive_health_insurance_short_contract', 'Om din anställning ska pågå i högst ett år ska du ha, eller ha ansökt om, en heltäckande sjukförsäkring Försäkringen ska gälla för hela den tid som du ska vara i Sverige och täcka kostnader för akut och annan sjukvård, sjukhusvistelse och akut tandvård. Den ska också täcka kostnader för hemtransport av medicinska skäl.'),
  ('se-work-permit-employed', 'salary_requirement', 'Det innebär att du måste ha en månadslön som uppgår till minst 90 procent av den medianlön som Statistiska centralbyrån (SCB) har publicerat och som gällde när du ansökte.'),
  ('se-work-permit-employed', 'salary_minimum_amount', 'För att uppfylla lönekravet ska du ha en månadslön på minst 34 470 kronor. Det motsvarar 90 procent av den aktuella medianlönen som SCB publicerar i juni varje år.'),
  ('se-work-permit-employed', 'salary_may_need_to_exceed_minimum', 'Din månadslön ska även vara i nivå med kollektivavtal eller i nivå med den praxis som gäller inom yrket eller branschen. Det betyder att din lön kan behöva vara högre än 90 procent av medianlönen.'),
  ('se-work-permit-employed', 'exempt_occupations_75_percent', 'Vissa yrken och grupper av sökande är undantagna lönekravet. Om man omfattas av något av undantagen från lönekravet, måste lönen vara minst 75 procent av medianlönen i Sverige vid tidpunkten för ansökan.'),
  ('se-work-permit-employed', 'single_employment_only', 'an inte ha två eller flera anställningar som tillsammans gör att kraven uppfylls.'),
  ('sg-dependants-pass', 'sponsor_holds_ep_or_s_pass', 'Hold an Employment Pass or S Pass.'),
  ('sg-dependants-pass', 'sponsor_salary_6000_not_household', 'Earn a minimum fixed monthly salary of $6,000. This is based on your salary, and not based on your combined household income.'),
  ('sg-dependants-pass', 'sponsored_by_singapore_registered_company', 'Are sponsored by an established, Singapore-registered company (usually your employer).'),
  ('sg-dependants-pass', 'eligible_family_members', 'You can get a pass for the following family members: ... Legally married spouse. ... Unmarried children under 21 years old, including legally adopted children.'),
  ('sg-dependants-pass', 'ict_fta_families_excluded', 'Family members of Employment Pass holders who chose to apply as an overseas ICT under WTO GATS or an applicable FTA are not eligible for Dependant’s Passes or Long-Term Visit Passes, except where they are specifically covered by an applicable FTA and meet the prevailing criteria for consideration.'),
  ('sg-dependants-pass', 'employer_applies', 'Who can apply An employer or appointed employment agent must apply on behalf of the candidate.'),
  ('sg-dependants-pass', 'duration_tied_to_main_pass', 'What is the duration The duration is tied to the validity of the main work pass or up to the duration requested, whichever is shorter.'),
  ('sg-dependants-pass', 'passport_personal_particulars', 'Copy of the personal particulars page of the candidate’s passport. Learn more about the upload requirements.'),
  ('sg-dependants-pass', 'marriage_certificate', 'Copy of the marriage certificate.'),
  ('sg-dependants-pass', 'birth_certificate_naming_parents', 'Copy of the official birth certificate stating the parents'' names.'),
  ('sg-dependants-pass', 'adoption_order', 'Copy of the adoption order or other relevant documents.'),
  ('sg-dependants-pass', 'cda_vaccination_verification_under_12', 'Verification of Vaccination Requirements (for entry to Singapore) document issued by the Communicable Diseases Agency (CDA) is needed for foreign-born children who meet these conditions: ... Aged 12 and below. ... Applying for a new DP - this includes those whose DPs have expired or been cancelled for more than 30 days.'),
  ('sg-dependants-pass', 'english_translation_single_file', 'For non-English documents, please upload the original document together with an English translation as 1 file. You may approach a translation service provider for translations.'),
  ('sg-dependants-pass', 'application_fee', 'Pay $105 fee for each application. You can pay by GIRO, Visa, Mastercard or Amex.'),
  ('sg-dependants-pass', 'issuance_fee', '$225 for each pass ... $30 for each Multiple Journey Visa (if applicable)'),
  ('sg-dependants-pass', 'processing_three_weeks', 'For dependants of EP and S Pass holders ... Processing time: within 3 weeks. Some cases will take more time.'),
  ('sg-dependants-pass', 'ipa_single_entry_six_months', 'The IPA letter is a pre-approved single-entry visa for the foreigner to enter Singapore. It gives the foreigner 6 months to enter Singapore and get their pass issued.'),
  ('sg-dependants-pass', 'dp_holder_needs_a_work_pass_to_work', 'Prospective employers can apply for an Employment Pass (EP), S Pass, or DP-Work Permit (DP-WP) for their DP holders.'),
  ('sg-dependants-pass', 'ep_or_s_pass_ends_the_dependency', 'Will no longer be dependent on the main pass holder for their stay in Singapore. They will need to have their DP cancelled before their EP or S Pass is issued.'),
  ('sg-dependants-pass', 'dp_work_permit_keeps_the_dependency', 'DP holders who get a DP-WP: ... Can be of any nationality/citizenship. ... Are not subject to a minimum qualifying salary. ... Will have their DP-WP’s validity period tied to their DP.'),
  ('sg-employment-pass', 'employer_or_agent_applies', 'An employer or appointed employment agent needs to apply on behalf of the candidate.'),
  ('sg-employment-pass', 'overseas_company_needs_local_sponsor', 'For an overseas company without a Singapore-registered office, you need to apply through a local sponsor.'),
  ('sg-employment-pass', 'two_stage_eligibility_framework', 'To qualify for EP applications, candidates will need to pass a 2-stage eligibility framework:'),
  ('sg-employment-pass', 'ep_qualifying_salary_current', '$5,600 (increases progressively with age from age 23, up to $10,700 at age 45 and above)'),
  ('sg-employment-pass', 'ep_qualifying_salary_financial_services', 'Financial services $6,200 (increases progressively with age from age 23, up to $11,800 at age 45 and above)'),
  ('sg-employment-pass', 'ep_qualifying_salary_from_2027', 'The following EP qualifying salary requirements apply to new applications and renewals: Sector Current minimum qualifying salary Minimum qualifying salary for new applications from 1 Jan 2027, and for renewal of passes expiring from 1 Jan 2028 ... $6,000 (increases progressively with age from age 23, up to $11,500 at age 45 and above)'),
  ('sg-employment-pass', 'salary_gate_not_score', 'Note: Candidates who do not meet stage 1 will not be eligible for an EP, regardless of the points they would have scored under COMPASS.'),
  ('sg-employment-pass', 'compass_40_points', 'Your application needs to earn 40 points to pass COMPASS.'),
  ('sg-employment-pass', 'compass_exemptions', 'Candidates are exempted from COMPASS if they meet any of these conditions: Have a fixed monthly salary of at least $22,500 (similar to the prevailing Fair Consideration Framework (FCF) job advertising exemption from 1 September 2023) ... Are applying as an overseas intra-corporate transferee ... Are filling the role for 1 month or less'),
  ('sg-employment-pass', 'fcf_job_advertising', 'Employers must continue to meet the Fair Consideration Framework (FCF) job advertising requirement before submitting new EP applications.'),
  ('sg-employment-pass', 'advertise_before_you_apply', 'You are required to advertise your job opening on MyCareersFuture to consider all applicants fairly, before you can apply for an Employment Pass.'),
  ('sg-employment-pass', 'passport_personal_particulars', 'Personal particulars page of candidate’s passport. Learn more about the upload requirements.'),
  ('sg-employment-pass', 'acra_business_profile', 'Company’s latest business profile or instant information registered with ACRA.'),
  ('sg-employment-pass', 'qualification_verification_proof', 'Verification proof for candidate''s qualifications (if applicable)'),
  ('sg-employment-pass', 'english_translation_single_file', 'For non-English documents, you must upload the original document together with an English translation as 1 file. The translation can be done by a translation service provider.'),
  ('sg-employment-pass', 'application_fee', 'Pay the $105 fee by GIRO, Visa, Mastercard or Amex.'),
  ('sg-employment-pass', 'pass_issuance_fee', '$225 for each pass ... (If applicable) $30 for each Multiple Journey Visa'),
  ('sg-employment-pass', 'ipa_single_entry_six_months', 'Is a pre-approved single-entry visa for the candidate to enter Singapore. It gives the candidate 6 months to enter Singapore and get their pass issued.'),
  ('sg-employment-pass', 'pass_duration_first_time', 'First-time candidates: Up to 2 years'),
  ('sg-employment-pass', 'singapore_address_housing_requirements', 'Candidate''s Singapore residential address, which must meet the housing requirements'),
  ('sg-employment-pass', 'medical_examination_or_declaration', 'Completed medical examination form or medical declaration form'),
  ('sg-entrepass', 'candidate_applies_directly', 'Who can apply Candidate can apply directly.'),
  ('sg-entrepass', 'no_minimum_salary', 'Minimum salary No stipulated minimum salary.'),
  ('sg-entrepass', 'private_limited_company_acra_30_percent', 'Have started, or intend to start, a private limited company that is: ... Registered with ACRA (Pass holder must hold at least 30% of registered company)'),
  ('sg-entrepass', 'venture_backed_or_innovative_technologies', 'Venture-backed or owns innovative technologies.'),
  ('sg-entrepass', 'twelve_month_cliff', 'If the registered company is more than 12 months old as of the date of application, you will be assessed according to the renewal criteria.'),
  ('sg-entrepass', 'one_of_five_innovation_criteria', 'Meet at least one of the following criteria:'),
  ('sg-entrepass', 'criterion_funding_raised', 'You have raised at least SGD 100,000 from a single funding round from investors for any past or current business.'),
  ('sg-entrepass', 'criterion_incubator_or_accelerator', 'The business is or will be supported by an incubator or accelerator that is either: ... Government-recognised ... Internationally renowned'),
  ('sg-entrepass', 'criterion_founded_and_sold', 'You have founded and sold a business that is venture-backed or owns innovative technologies.'),
  ('sg-entrepass', 'criterion_intellectual_property', 'The registered business or proposed business holds Intellectual Property (IP) that is registered with an approved national IP institution. ... The IP must provide significant competitive advantage which cannot be easily replicated to the business.'),
  ('sg-entrepass', 'criterion_research_collaboration', 'The business has a relevant ongoing research collaboration in Singapore with at least one of the following: ... Institute of Higher Learning (IHL) ... Research Institution (RI)'),
  ('sg-entrepass', 'research_collaboration_not_a_service_contract', 'Contracts of services are not considered research collaborations.'),
  ('sg-entrepass', 'ineligible_business_types', 'The following businesses are not eligible for an EntrePass: ... Coffee shops, hawker centres, food courts ... Bars, night clubs, karaoke lounges ... Foot reflexology, massage parlours ... Acupuncture, traditional Chinese medicine, herbal dispensing businesses ... Employment agencies ... Geomancy business'),
  ('sg-entrepass', 'passport_personal_particulars', 'Personal particulars page of your passport'),
  ('sg-entrepass', 'business_plan_ten_pages', 'A business plan in English. It should include the following in 10 pages or less:'),
  ('sg-entrepass', 'cv_and_testimonials', 'Your curriculum vitae (CV) and past employment testimonials (if any) to elaborate on professional experiences, awards or recognitions'),
  ('sg-entrepass', 'bizfile_business_profile', 'Company’s latest business profile or instant information from Bizfile (if applicable)'),
  ('sg-entrepass', 'financial_statement_after_12_months', 'Latest financial statement (if company is registered with ACRA for more than 12 months)'),
  ('sg-entrepass', 'evidence_for_chosen_criterion', 'You need to provide additional documents depending on the innovative criteria you plan to apply under:'),
  ('sg-entrepass', 'application_fee', 'Pay the $105 application fee by Visa, Mastercard or Amex.'),
  ('sg-entrepass', 'issuance_fee', '$225 for each pass ... (If applicable) $30 for each Multiple Journey Visa'),
  ('sg-entrepass', 'processing_six_weeks_no_stvp_extension', 'Processing time is around 6 weeks. You will not be able to extend your Short Term Visit Pass if it expires before your application is approved.'),
  ('sg-entrepass', 'ipa_single_entry_six_months', 'Is a pre-approved single-entry visa for you to enter Singapore. It gives you 6 months to enter Singapore and get your pass issued.'),
  ('sg-entrepass', 'pass_does_not_authorise_the_business', 'Getting an EntrePass is not a guarantee that your business registration and licences will get approved.'),
  ('sg-entrepass', 'pass_duration_one_year', 'New pass and first renewal: Up to 1 year'),
  ('sg-entry-visa', 'visa_required_by_travel_document', 'If you hold a travel document 1 issued by one of the countries or places listed below, you will require a valid Singapore entry visa to travel to, and seek entry, into Singapore.'),
  ('sg-entry-visa', 'individually_issued_travel_document', '1 All travellers, regardless of age, must hold a valid individually-issued travel document as collective travel documents are not accepted.'),
  ('sg-entry-visa', 'visa_is_not_entry', 'A Singapore entry visa is not an immigration pass. It is a pre-entry permission for the holder of a valid visa to travel to, and seek entry, into Singapore.'),
  ('sg-entry-visa', 'visa_does_not_guarantee_entry', 'Possession of a valid visa does not guarantee entry into Singapore.'),
  ('sg-entry-visa', 'stay_length_decided_at_checkpoint', 'The period of stay in Singapore is not tied to the validity of your visa. The period of stay is determined by the duration of the Visit Pass issued to you in the form of electronic visit pass (e-Pass) at the checkpoint upon entry.'),
  ('sg-entry-visa', 'epass_notified_by_email', 'From 11 March 2022, all foreign visitors arriving in Singapore will be notified digitally of their Visit Pass (e-Pass) through email. There will not be any endorsement on your passport. The e-Pass notification will indicate the period of stay granted and last day of stay allowed.'),
  ('sg-entry-visa', 'sg_arrival_card_is_not_a_visa', 'SG Arrival Card is not a visa.'),
  ('sg-entry-visa', 'no_counter_submission', 'ICA does not accept submission of visa application over the immigration counters.'),
  ('sg-entry-visa', 'submit_online_via_local_contact_or_partner', 'Your visa application can be submitted online using the e-Service through a strategic partner or a local contact in Singapore.'),
  ('sg-entry-visa', 'no_local_contact_route', 'If you do not have a Local Contact with a Singpass/Corppass account, you may submit the visa application: ... Through an authorised visa agent appointed by the Singapore Overseas Missions; or ... At the nearest Singapore Overseas Mission.'),
  ('sg-entry-visa', 'apply_within_30_days_of_arrival', 'You are advised to apply for an entry visa within 30 days prior to arrival in Singapore.'),
  ('sg-entry-visa', 'form_14a', 'Duly completed Form 14A (PDF, 202KB) signed by you. Your visa application shall be made based on the information declared in this form. ICA may request for the form to be submitted.'),
  ('sg-entry-visa', 'passport_photograph_three_months', 'Your recent passport-sized colour photograph taken within the last three months.'),
  ('sg-entry-visa', 'passport_biodata_six_months_validity', 'A photocopy of your passport biodata page (valid for at least six months from the date of your entry into Singapore)'),
  ('sg-entry-visa', 'originals_and_official_translations', 'You will need to provide original documents and official translations (for documents in languages other than English), as well as copies of the documents for ICA to retain.'),
  ('sg-entry-visa', 'loi_case_by_case_group', 'Additional supporting documents (e.g., Form V39A (PDF, 192KB) (Letter of Introduction for Visa Application (LOI)) may be required on a case-by-case basis.'),
  ('sg-entry-visa', 'loi_required_group', 'A completed Form V39A (PDF, 192KB)(Letter of Introduction for Visa Application (LOI)), which may be issued by a local contact* in Singapore.'),
  ('sg-entry-visa', 'loi_local_contact_qualifications', '*The local contact must be either a Singapore citizen (SC) or a Singapore permanent resident (PR) who is at least 21 years old with a Singpass account. If you are applying for an entry visa for business visit (attending business negotiations or discussions), the local contact must be acting on behalf of the Singapore-registered business entity. LOIs issued by your Embassy can also be accepted, if you are unable to secure an LOI from a local contact to support your visa application for social and business visits.'),
  ('sg-entry-visa', 'processing_fee', 'A S$30 non-refundable processing fee is payable online using a Visa or MasterCard credit/debit card.'),
  ('sg-entry-visa', 'processing_time_three_working_days', 'Your visa application will be processed within three working days (excluding the day of submission). Some applications may take longer to process.'),
  ('sg-long-term-visit-pass', 'eligible_categories', 'As a foreigner, you are eligible to apply for a Long-Term Visit Pass if you are a/ an: ... Spouse of a Singapore citizen ... Spouse of a Singapore Permanent Resident (PR) ... Parent of a Singapore citizen or Singapore Permanent Resident (PR)'),
  ('sg-long-term-visit-pass', 'parents_in_law_not_eligible', 'Note: Parent(s)-in-law are not eligible.'),
  ('sg-long-term-visit-pass', 'marriage_does_not_guarantee_approval', 'Check the intended spouse’s chances of getting a Long-Term Visit Pass (LTVP) (as marriage does not guarantee LTVP approval).'),
  ('sg-long-term-visit-pass', 'pmla_before_marriage', 'This free online assessment helps the couple: ... Speed up the LTVP application process: 6 weeks instead of 6 months.'),
  ('sg-long-term-visit-pass', 'pmla_processing_time_rule', 'An LTVP application by a foreign spouse of a Singapore citizen will take up to 6 months to be processed. If you and your spouse had completed the PMLA before your marriage, the LTVP application processing time will be shortened to 6 weeks.'),
  ('sg-long-term-visit-pass', 'work_permit_holders_need_controller_approval', 'Existing and former Work Permit holders (including Training Work Permit) who wish to marry Singapore citizens or Permanent Residents in Singapore or overseas, regardless the type of marriage (civil, religious or customary), must first seek approval from the Controller of Work Passes. If they fail to do so, their privileges to work in Singapore could be withdrawn. They may also be prevented from entering Singapore for a period of time.'),
  ('sg-long-term-visit-pass', 'sponsor_must_hold_singpass', 'After marriage, you may apply for the LTVP. Your Singaporean spouse must sponsor your application via ICA e-Service using Singpass.'),
  ('sg-long-term-visit-pass', 'all_applicants_need_singpass_2_to_5_days', 'Please note that the approval for a Singpass account application may take 2 to 5 working days. Sponsors/ Applicants are recommended to start an application only after all applicants have successfully registered for a Singpass account, where eligible.'),
  ('sg-long-term-visit-pass', 'originals_and_official_translations', 'You will need to provide original documents and official translations (for documents in languages other than English), as well as copies of the documents for ICA to retain.'),
  ('sg-long-term-visit-pass', 'submission_fee', 'S$45 for each application ... All fees are non-refundable.'),
  ('sg-long-term-visit-pass', 'issuance_fee', 'S$60 for issuance of LTVP ... S$30 for a Multiple Journey Visa (if applicable)'),
  ('sg-long-term-visit-pass', 'standard_processing_six_weeks', 'Most applications will be processed within 6 weeks, provided all the required documents are submitted and in order.'),
  ('sg-long-term-visit-pass', 'ipa_is_not_an_immigration_pass', 'Do note that the in-principle approval of the LTVP application is not an immigration pass and does not confer any valid stay to the applicant.'),
  ('sg-long-term-visit-pass', 'formalities_before_ipa_expiry', 'Upon in-principle approval of the LTVP application, you will be informed of the tasks required to complete the formalities. This may include completing a medical check-up. These tasks have to be completed before the expiry of the in-principle approval, otherwise the application will be considered withdrawn.'),
  ('sg-long-term-visit-pass', 'pay_within_14_days', 'Once the uploaded document(s) are verified by ICA, the applicant will be notified to make payment online. Payment must be made within 14 days, otherwise the application will be withdrawn.'),
  ('sg-long-term-visit-pass', 'digital_pass_via_filesg', 'LTVP holders will receive an email from ICA (via FileSG) on how to retrieve the digital pass.'),
  ('sg-long-term-visit-pass', 'renewal_three_months_no_carry_forward', 'Please submit your Long-Term Visit Pass (LTVP) renewal application at least 3 months before the expiry of your current LTVP. The validity of the renewed LTVP will be from the date of issuance (upon payment of the issuance fee). The remaining validity from the current LTVP will not be carried forward to the renewed LTVP.'),
  ('sg-one-pass', 'candidate_may_apply', 'Who can apply Candidates who meet the eligibility criteria can apply. ... Appointed employment agencies and employers can also apply on behalf of their candidate.'),
  ('sg-one-pass', 'one_work_pass_application_at_a_time', 'Note: You may only submit 1 work pass application per candidate at a time. For example, you may only apply for either an Overseas Networks & Expertise Pass or Employment Pass for your candidate at any one time.'),
  ('sg-one-pass', 'salary_past_employment', 'Earned a fixed monthly salary of at least S$30,000, or its equivalent in foreign currency, for the 12 consecutive months leading up to the date of application.'),
  ('sg-one-pass', 'salary_prospective_employment', 'Will earn a fixed monthly salary of at least S$30,000 under an established company that is based in Singapore. ... When applying based on prospective employment in Singapore, submit your application only when your employment will start within 6 months.'),
  ('sg-one-pass', 'established_company_thresholds', 'For a company to be considered established, it must have at least one of the following: ... Market capitalisation of at least US$500 million ... Annual revenue of at least US$200 million'),
  ('sg-one-pass', 'salary_from_one_employer', 'If you drew salaries from more than one employer in the 12 consecutive months leading up to the date of application, your qualifying fixed monthly salary of at least S$30,000 should come from one employer only.'),
  ('sg-one-pass', 'outstanding_achievements_route', 'You may apply without meeting the salary criteria if you have outstanding achievements in at least one of the areas below: ... Sports ... Arts and culture ... Academia and research'),
  ('sg-one-pass', 'existing_pass_holders_one_year', 'Existing pass holders need to have worked in Singapore for at least 1 year.'),
  ('sg-one-pass', 'compass_and_fcf_exemption', 'Exemption from Complementarity Assessment Framework (COMPASS) and Fair Consideration Framework job advertising requirements'),
  ('sg-one-pass', 'multiple_companies_and_job_changes', 'Flexibility to concurrently start, operate and work for multiple companies at any one time (subject to your employment contract terms, where relevant) ... No need to reapply for a pass if you change jobs'),
  ('sg-one-pass', 'spouse_letter_of_consent', 'Your spouse will be able to apply to work on a Letter of Consent.'),
  ('sg-one-pass', 'no_levy_or_quota', 'Foreign worker levy or quota No foreign worker levy or quota required.'),
  ('sg-one-pass', 'pass_duration_five_years', 'First-time candidates: Up to 5 years'),
  ('sg-one-pass', 'renewal_criteria', 'To be eligible for renewal, the pass holder must meet one of the following: ... Earned a fixed monthly salary of at least S$30,000 on average over the past 5 years in Singapore. ... Started and is operating a Singapore-based company that employs at least 5 locals, each earning a gross monthly salary that is at least the prevailing EP minimum qualifying salary.'),
  ('sg-one-pass', 'passport_page', 'All Overseas Networks & Expertise Pass applications need to include a passport page, including any amendments.'),
  ('sg-one-pass', 'twelve_months_payslips', 'Monthly payslips for the 12 consecutive months leading up to the date of application'),
  ('sg-one-pass', 'iras_notice_of_assessment', 'Most recent Notice of Assessment from the Inland Revenue Authority of Singapore'),
  ('sg-one-pass', 'overseas_employment_verification', 'Employment verification proof from a background screening company'),
  ('sg-one-pass', 'employer_financials_within_three_months', 'Latest financial information of the candidate’s employer obtained within the last 3 months. This includes documents indicating the latest market capitalisation or annual company revenue.'),
  ('sg-one-pass', 'application_fee', 'Pay the $105 application fee via Visa or Mastercard.'),
  ('sg-one-pass', 'issuance_fee', '$225 for each pass ... $30 for each Multiple Journey Visa (if applicable)'),
  ('sg-one-pass', 'processing_four_weeks', 'Processing time: 4 weeks for most cases'),
  ('sg-one-pass', 'ipa_single_entry_six_months', 'Is a pre-approved single-entry visa for you to enter Singapore. It gives you 6 months to enter Singapore and get your pass issued.'),
  ('sg-s-pass', 'employer_applies_and_reapplies_on_job_change', 'Who can apply An employer or appointed employment agent must apply on behalf of the applicant. If the pass holder changes jobs, the new employer has to apply for a new pass.'),
  ('sg-s-pass', 'any_nationality_with_job_offer', 'The S Pass is for foreign employees across all nationalities or citizenships who: ... Have a job offer in Singapore.'),
  ('sg-s-pass', 'qualifying_salary_current', '$3,300 (increases progressively with age from age 23, up to $4,800 at age 45 and above)'),
  ('sg-s-pass', 'qualifying_salary_expiring_regime', '$3,150 (increases progressively with age from age 23, up to $4,650 at age 45 and above)'),
  ('sg-s-pass', 'qualifying_salary_from_2027', 'The S Pass minimum qualifying salary will increase from $3,300 to $3,600 for new applications from 1 January 2027 and renewals expiring from 1 January 2028.'),
  ('sg-s-pass', 'financial_services_converge_at_45', 'financial services ... $3,650 (increases progressively with age from age 23, up to $5,650 at age 45 and above) $3,800 (increases progressively with age from age 23, up to $5,650 at age 45 and above) $4,000 (increases progressively with age from age 23, up to $5,650 at age 45 and above)'),
  ('sg-s-pass', 'quota_and_levy_apply', 'Quota or levy Yes. Employers are subject to a quota and levy for S Pass employees.'),
  ('sg-s-pass', 'employer_must_provide_medical_insurance', 'Medical insurance Employers must provide medical insurance for S Pass holders.'),
  ('sg-s-pass', 'primary_care_plan', 'After getting the in-principle approval or renewal letter, buy a PCP for workers who either: ... Stay in dormitories that can accommodate 7 or more workers ... Work in CMP sectors ... Before the S Pass can be issued or renewed, declare the PCP purchase on myMOM Portal.'),
  ('sg-s-pass', 'qualifications_optional', 'Declaring qualifications is optional.'),
  ('sg-s-pass', 'self_assessment_tool_gate', 'If the SAT shows that the candidate is not eligible, you shouldn’t apply for the S Pass because it will be rejected.'),
  ('sg-s-pass', 'sat_ninety_percent', 'If the SAT shows that the candidate is eligible, there is around a 90% chance that the candidate will get a pass.'),
  ('sg-s-pass', 'dependants_pass_at_6000', 'Pass holders who have a fixed monthly salary of at least $6,000 are eligible for a Dependant’s Pass for their spouse and children.'),
  ('sg-s-pass', 'passport_validity_caps_the_pass', 'Note: The duration granted is limited by your passport validity. The pass can only be valid up to 1 month before your passport expiry date.'),
  ('sg-s-pass', 'passport_personal_particulars', 'Personal particulars page of candidate’s passport. Learn more about the upload requirements.'),
  ('sg-s-pass', 'acra_business_profile', 'Company’s latest business profile or instant information registered with ACRA.'),
  ('sg-s-pass', 'regulated_occupation_documents', 'Additional documents are required for: ... Healthcare professionals, lawyers, football players or coaches'),
  ('sg-s-pass', 'application_fee', 'Pay the $105 fee by GIRO, Visa, Mastercard or Amex.'),
  ('sg-s-pass', 'processing_ten_business_days', 'Processing time: Processed or given an update within 10 business days.'),
  ('sg-s-pass', 'medical_and_insurance_at_issuance', 'Candidate''s completed medical examination form. If certified fit to work, buy the Primary Care Plan for those who are required to have it.'),
  ('sg-s-pass', 'singapore_address_housing_requirements', 'Candidate''s Singapore residential address, which must meet the housing requirements for you to get the pass issued.'),
  ('sg-student-pass', 'full_time_acceptance_required', 'To apply for a Student’s Pass, you must be accepted into an approved full-time course in Singapore. Part-time courses and courses conducted in the evening or on weekends are not eligible.'),
  ('sg-student-pass', 'exempt_if_holding_another_pass', '^Holders of valid Long-Term Visit Pass, Dependant''s Pass and Immigration Exemption Order are not required to obtain a Student''s Pass to pursue full time, non-religious related studies. They may enrol in any school within the duration of their existing pass.'),
  ('sg-student-pass', 'exemption_lapses_mid_course', 'If the existing pass expires or is cancelled during the duration of their studies, the foreigner will need to submit an application for a Student''s Pass to continue his/her studies. The prevailing Student''s Pass eligibility criteria will apply.'),
  ('sg-student-pass', 'short_course_exemption_conditions', '*Foreigners attending short-term courses that meet the following criteria are exempted from requiring a Student''s Pass. The course must: ... Be completed during the validity of the Short-Term Visit Pass or within 30 days, whichever is shorter ... Be a complete and stand-alone module; a Student''s Pass is required to undertake courses with multiple programme modules'),
  ('sg-student-pass', 'ihl_full_time_matriculated', 'You will need to apply for a Student’s Pass if you are a foreigner who has been accepted for admission as a full-time matriculated or registered student at one of the following Institutes of Higher Learning (IHL) in Singapore.'),
  ('sg-student-pass', 'pei_must_be_edutrust_certified', 'Non-EduTrust-certified PEIs: PEIs that are not EduTrust-certified cannot offer placements to foreign students. Only foreign students who hold an existing and valid Dependant''s Pass, Long-Term Visit Pass or Immigration Exemption Order may enrol for full-time, non-religious studies in such PEIs. You will need to ensure that your immigration pass is valid for the entire duration of your studies. A Student''s Pass will not be issued to foreigners enrolled in PEIs that are not EduTrust-certified.'),
  ('sg-student-pass', 'religious_study_inverts_exemptions', 'Religious Studies: A Student''s Pass is required if you wish to study in an approved religious school. This includes holders of a valid Long-Term Visit Pass and Dependant''s Pass. Holders of a valid Immigration Exemption Order are exempted.'),
  ('sg-student-pass', 'registration_acknowledgement_letter', 'The Registration Acknowledgement Letter from the school you plan to attend'),
  ('sg-student-pass', 'travel_document_and_birth_certificate', 'Your travel document biodata page and birth certificate (if applicable)'),
  ('sg-student-pass', 'residence_education_employment_history', 'Your personal information, including the list of countries / places you have previously resided in, your educational background, employment history and financial support'),
  ('sg-student-pass', 'family_personal_information', 'Your parents’, spouse''s, and/or siblings’ personal information (if applicable)'),
  ('sg-student-pass', 'singapore_address_and_email', 'Your residential address and contact details in Singapore ... Your email address'),
  ('sg-student-pass', 'photograph_three_months', 'Your recent, passport-sized, digital, colour photograph taken within the last three months.'),
  ('sg-student-pass', 'originals_and_official_translations', 'You will need to provide original documents and official translations (for documents in languages other than English), as well as copies of the documents for ICA to retain.'),
  ('sg-student-pass', 'vaccination_information_under_12', 'Foreign-born applicants aged 12 years 0 day or below, are required to submit their vaccination information to Communicable Diseases Agency (CDA) with effect from 1 February 2019.'),
  ('sg-student-pass', 'apply_two_to_three_months_before', 'You will need to apply online using the e-Service at least two months and not more than three months before course begins.'),
  ('sg-student-pass', 'apply_before_arriving', 'You do not need to be in Singapore while your application is being processed. As such, we recommend you apply for a Student’s Pass before arriving in Singapore as you cannot extend your stay while processing is underway.'),
  ('sg-student-pass', 'processing_fee', 'A non-refundable S$45 processing fee is payable.'),
  ('sg-student-pass', 'processing_time_ihl_one_week', 'The processing time for application is within one week (and within two weeks if Visa is required) (excluding the date of submission). Some applications may take longer time to process.'),
  ('sg-student-pass', 'processing_time_pei_one_month', 'The processing time for a new Student’s Pass application is within one month (and within two weeks for an EduTrust-accredited PEI) (excluding the date of submission). Some applications may take longer time to process.'),
  ('sg-student-pass', 'ipa_carries_the_visa', 'You must be in Singapore on a valid immigration pass for the completion of formalities for the Student’s Pass to be issued. If you require a visa to enter Singapore, the visa will be automatically included in your IPA letter. You are to produce the IPA letter at the immigration checkpoint. However, the letter does not guarantee entry into or stay in Singapore.'),
  ('sg-student-pass', 'medical_examination_report', 'Before your Student’s Pass can be issued, you will need to download and submit Medical Examination Report (if applicable).'),
  ('sg-student-pass', 'formalities_by_appointment', 'The completion of formalities for the Student’s Pass is strictly by appointment. Visit ICA e-Service to select an appropriate date and time for your appointment.'),
  ('sg-student-pass', 'issuance_fee', 'A S$60 issuance fee for Student’s Pass and a S$30 for Multiple Journey Visa (if applicable) are payable via Internet Banking, AMEX, a Visa or MasterCard credit/debit card online.'),
  ('sg-student-pass', 'digital_pass_only', 'From 27 February 2023, ICA will issue the Student''s Pass in digital form only. A digital Student''s Pass will be issued in place of a physical Student''s Pass card.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i130_petition', 'Use this form if you (the petitioner) are a U.S. citizen, lawful permanent resident, or U.S. national (who is not a U.S. citizen) and you need to establish your qualifying relationship with an eligible alien relative (the beneficiary) who wishes to come to or stay in the United States permanently and apply for the Permanent Resident Card (also called a Green Card).'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i130_part4_route_selection', 'You must select only 1 option for Part 4 (Question 61 or 62) to indicate whether the beneficiary will seek adjustment of status inside the United States or consular processing abroad. Do not complete both questions, and do not leave this section blank.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'immigrant_visa_number_available', 'Certain relatives must wait until an immigrant visa number is available before they can file Form I-485 (to adjust their status if they are in the United States) or request an immigrant visa at an embassy or consulate through consular processing (if they are outside the United States). However, if your relative qualifies as an immediate relative, an immigrant visa is always available.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i130a_spouse_supplement', 'Form I-130A, Supplemental Information for a Spouse Beneficiary (PDF, 454.67 KB) ... Please do not submit this checklist with your Form I-130 (and Form I-130A, if required).'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'evidence_petitioner_status', 'Evidence of U.S. citizenship, lawful permanent residence, or U.S. national status: A copy of your birth certificate, issued by a civil registrar, vital statistics office, or other civil authority showing you were born in the United States; A copy of your naturalization or citizenship certificate issued by USCIS or the former Immigration and Naturalization Service (INS); A copy of Form FS-240, Consular Report of Birth Abroad (CRBA), issued by a U.S. Embassy or U.S. Consulate; A copy of your unexpired U.S. passport; An original statement from a U.S. consular officer verifying you are a U.S. citizen with a valid passport; or A copy of the front and back of your Permanent Resident Card (also known as a Green Card or a Form I-551).'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'evidence_family_relationship', 'Evidence of family relationship with 1 of the following (see form instructions for more detailed guidance): Spouse: A copy of your marriage certificate ... Child: A copy of your child’s birth certificate(s). Parent: A copy of your birth certificate. Brother/Sister: A copy of the birth certificate for you and your sibling.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'evidence_prior_marriages_terminated', 'Evidence you or your spouse terminated any prior marriages (if applicable)'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'evidence_bona_fide_marriage', 'Evidence of the bona fides of the marriage, if petitioning for a spouse: Documentation showing joint ownership of property; A lease showing joint tenancy of a common residence, meaning you both live at the same address together; Documentation showing that you and your spouse have combined your financial resources; Birth certificates of children born to you and your spouse together; Affidavits sworn to or affirmed by third parties having personal knowledge of the bona fides of the marital relationship. Each affidavit must contain the full name and address of the person making the affidavit; date and place of birth of the person making the affidavit; and complete information and details explaining how the person acquired their knowledge of your marriage; and Any other relevant documentation to establish that there is an ongoing marital union.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'proof_of_legal_name_change', 'Proof of legal name change (if applicable)'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'passport_style_photographs', '2 passport-style photographs (if applicable).'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'certified_english_translations', 'If you submit any documents (copies or original documents, if requested) in a foreign language, you must include a full English translation along with a certification from the translator verifying that the translation is complete and accurate, and that they are competent to translate from the foreign language into English.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'adopted_child_evidence', 'If you are filing Form I-130 for your adopted child Evidence you meet requirements for the family-based petition process, including: A copy of the adoption decree showing the adoption took place before the child turned 16 (or 18 if the sibling exception applies); Evidence you have had legal custody of the adopted child for 2 years; Evidence you have had joint residence with the adopted child for 2 years; and Evidence the Hague Adoption Convention process does not apply, if you or your spouse is a U.S. citizen and the child is from a Hague Adoption Convention country.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'sign_form_i130', 'Don’t forget to sign your form! We will reject any unsigned form.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i130_filing_fee', 'You can find the filing fee for Form I-130 by visiting our Fee Schedule page.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i485_adjustment_application', 'Use this form to apply for lawful permanent resident status if you are in the United States.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i693_medical_examination', 'When you file Form I-485, you must also submit Form I-693, Report of Immigration Medical Examination and Vaccination Record. A civil surgeon is responsible for providing you with a completed Form I-693 that is signed and placed in a sealed envelope. ... If you are required to submit Form I-693, Report of Immigration Medical Examination and Vaccination Record, or a partial Form I-693 (such as the Vaccination Record), you must submit it with your Form I-485. Otherwise, we may reject your Form I-485.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i485_visa_immediately_available', 'In general, you may not file your Form I-485 until an immigrant visa is immediately available in your category.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'sign_form_i485', 'Don’t forget to sign your form. We will reject any unsigned form.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'i485_filing_fee', 'You can find the filing fee for Form I-485 by visiting our Fee Schedule page.'),
  ('us-family-immigration-immediate-relative-and-family-preference-immigrant-visas', 'submit_all_initial_evidence_together', 'Save time by submitting all required initial evidence and supporting documentation at the same time you file Form I-485. ... Submitting all required initial evidence and supporting documentation at the same time you file Form I-485 may eliminate the need for us to issue a Request for Evidence to get additional documentation and evidence. This may also help avoid adjudication delays if we decide that you do not need to be interviewed.'),
  ('us-temporary-worker-visas', 'i129_petition', 'Petitioners use this form to file on behalf of a nonimmigrant worker to come to the United States temporarily to perform services or labor, or to receive training, as an H-1B, H-2A, H-2B, H-3, L-1, O-1, O-2, P-1, P-1S, P-2, P-2S, P-3, P-3S, Q-1 or R-1 nonimmigrant worker. Petitioners may also use this form to request an extension of stay in or change of status to E-1, E-2, E-3, H-1B1 or TN, or one of the above classifications for an alien.'),
  ('us-temporary-worker-visas', 'sign_form_i129', 'Don’t forget to sign your form. We will reject or deny any improperly signed forms. Forms must include a valid signature as provided in the form instructions. USCIS will not accept: A typed name on the signature line; A signature by an attorney, representative, or family member signing for the requestor; A signature created by a typewriter, word processor, stamp (manual or electronic), autopen, or similar device; An electronic signature rendered external to the USCIS online account, signatures created using commercial signature software, and signatures that do not comply with signature guidance in the USCIS Policy Manual and the DHS Electronic Signature Guidance; or An image of a handwritten signature that is subsequently and separately affixed to the benefit request by either physical or electronic methods.'),
  ('us-temporary-worker-visas', 'i129s_blanket_l', 'All petitioners requesting an extension of stay for a beneficiary who entered the United States based on an approved blanket L petition must file the following: Form I-129, Petition for a Nonimmigrant Worker; Form I-129S, Nonimmigrant Petition Based on Blanket L Petition; and A copy of their previously approved Form I-129S. We may reject any Form I-129 for an L-1 blanket extension of stay request that does not also include Form I-129S.'),
  ('us-temporary-worker-visas', 'h2b_single_petition_only', 'ALERT: If you are filing a Form I-129 H-2B petition, send only one petition with supporting documents. Do not send extra copies of the form, supporting documents, or payment authorization. Sending duplicates may result in them being treated as separate petitions.'),
  ('us-temporary-worker-visas', 'nonimmigrant_visa_still_required', 'Evidence of a petition approval is not a visa, and the beneficiary must possess the appropriate nonimmigrant visa (if one is required) before applying for admission into the United States.'),
  ('us-temporary-worker-visas', 'carry_petition_approval_evidence', 'Along with a valid passport and visa (if applicable), the beneficiary should carry the following documents when traveling to the United States: Form I-797, Notice of Action, stating we approved the petition; or A copy of the approved Form I-129S (if applicable). The beneficiary should present this documentation to U.S. Customs and Border Protection when seeking entry or re-entry into the United States in the approved Form I-129 employment classification.'),
  ('us-temporary-worker-visas', 'i129_filing_fee', 'You can find the filing fee for Form I-129 by visiting our Fee Schedule page.'),
  ('us-temporary-worker-visas', 'i765_employment_authorization', 'Certain aliens who are in the United States may file Form I-765, Application for Employment Authorization, to request an Employment Authorization Document (EAD). Other aliens whose immigration status authorizes them to work in the United States without restrictions may also use Form I-765 to apply for an EAD that shows such authorization.'),
  ('us-temporary-worker-visas', 'ead_photos_unmounted_unretouched', 'ALERT: Please remember that photos submitted to USCIS must be unmounted and unretouched. Unretouched means the photos must not be edited or digitally enhanced. The submission of any mounted or retouched images will delay the processing of your application and may prompt USCIS to require that you appear at an Applicant Support Center to verify your identity.'),
  ('us-temporary-worker-visas', 'h4_spouse_concurrent_i765', '(c)(26) You may file Form I-765 at the same time as your Form I-539 and your H1-B spouse’s Form I-129, Petition for a Nonimmigrant Worker.'),
  ('us-temporary-worker-visas', 'ead_renewal_timing', 'We generally recommend you file a Form I-765 to request a renewal Employment Authorization Document (EAD) up to 180 days before your current EAD expires. We generally do not backdate or postdate a renewal EAD to the end of your current EAD’s validity period. ... To renew your Employment Authorization Document, file Form I-765 at least 90 days before the expiration.'),
  ('us-temporary-worker-visas', 'sign_form_i765', 'Don’t forget to sign your form. We will reject any unsigned form.'),
  ('us-temporary-worker-visas', 'i765_filing_fee', 'You can find the filing fee for Form I-765 by visiting our Fee Schedule page.'),
  ('us-temporary-worker-visas', 'keep_uscis_address_current', 'Please ensure you have the correct mailing address on file with USCIS. If your mailing address changes after you file your application, you must update your address with USCIS and USPS as soon as possible. If you don’t update your address promptly, your case could be delayed, your document(s) could get lost, and you may need to reapply and pay the fee again.'),
  ('us-visa-waiver-program-esta', 'vwp_participating_country_citizen', 'The Visa Waiver Program (VWP), administered by the Department of Homeland Security (DHS) in consultation with the State Department, permits citizens of 42 countries to travel to the United States for business or tourism for stays of up to 90 days without a visa.'),
  ('us-visa-waiver-program-esta', 'stay_90_days_or_less', 'for stays of up to 90 days without a visa'),
  ('us-visa-waiver-program-esta', 'purpose_business_or_tourism', 'to travel to the United States for business or tourism for stays of up to 90 days without a visa'),
  ('us-visa-waiver-program-esta', 'e_passport_required', 'You must have an e-Passport to use the VWP. An e-Passport is an enhanced secure passport with an embedded electronic chip. You can readily identify an e-Passport, because it has a unique international symbol on the cover.'),
  ('us-visa-waiver-program-esta', 'esta_authorization', 'ESTA is an automated system that determines the eligibility of visitors to travel to the United States under the Visa Waiver Program (VWP).'),
  ('us-visa-waiver-program-esta', 'esta_application_biographic_info', 'The ESTA application collects biographic information and answers to VWP eligibility questions.'),
  ('us-visa-waiver-program-esta', 'apply_before_booking', 'ESTA applications may be submitted at any time prior to travel, though it is recommended that travelers apply as soon as they begin preparing travel plans or prior to purchasing airline tickets.'),
  ('us-visa-waiver-program-esta', 'esta_is_not_admissibility', 'Authorization via ESTA does not determine whether a traveler is admissible to the United States. U.S. Customs and Border Protection officers determine admissibility upon travelers’ arrival.')
) as v(visaai_id, requirement_code, display)
join public.visa_types t on t.visaai_id = v.visaai_id
where r.visa_type_id = t.id
  and r.requirement_code = v.requirement_code
  and r.source_excerpt_display is distinct from v.display;

-- Assert the fix actually landed, and that it did not disturb anything else.
do $$
declare quoted int; total int; drafted int;
begin
  select count(*) into quoted from public.visa_requirements
   where status = 'active' and source_excerpt_display is not null;
  select count(*) into total from public.visa_requirements where status = 'active';

  if quoted = 0 then
    raise exception 'No active requirement carries a display excerpt — the backfill did nothing.';
  end if;

  -- The whole registry must not have been sent back to draft by this.
  select count(*) into drafted from public.visa_requirements where status = 'draft';
  raise notice 'display excerpts: % of % active requirements can quote the authority (% still draft).',
    quoted, total, drafted;
end $$;

commit;
